--s_wip				="\n\n<c=o>（开发中）</c>"
--wpn_prof_d		="你知道在战斗中如何使用这类武器。"--\n\n此类武器攻击+4。	+4 bonus on attack rolls with weapons of the group.	+4 bonus aux jets d'attaque avec les armes du groupe.	このグループの武器を使用した攻撃ロールに＋４のボーナス。	你知道在战斗中如何使用这类武器。You understand how to use weapons of this group in combat.Vous savez comment utiliser les armes de ce type en combat.このグループの武器を戦闘で使用する方法を理解している。戦闘でこのグループの武器の使い方を理解している。\n\nこのグループの武器を使った攻撃時に+4のボーナスを得る。
--simple_wpn_d		="\n\n顾名思义，此类武器简单易用，大多数职业都擅长所有简易武器。"..s_auto_prof
--s_exotic_wp_d		="你知道在战斗中如何使用这种异种武器。\n\n相对于简易和军用武器，异种武器较为罕见且难以使用，需要接受专门的训练才能运用自如。"--\n\n此种武器攻击+4。	+4 bonus on attack rolls with the weapon.	+4 bonus aux jets d'attaque avec l'arme.	武器の攻撃ロールに+4ボーナス。
s_for_touch			="本专长也适用于接触攻击。"
s_for_touch_m		="本专长也适用于近战接触攻击。"
s_for_touch_r		="本专长也适用于远程接触攻击。"
melee_only			="本专长仅适用于近战。"
ch_1_eff			="\n\n每次重击只能引发1个重击效果，除非拥有重击掌握专长。"
use_a				="\n\n<c=fc_b>每天使用次数：5 + 角色等级/4。\n最多15次/天。</c>"
use_b				="\n\n<c=fc_b>每天使用次数：角色等级/4。\n最多5次/天。</c>"
s_feat_x_spl_add_2x	="可多次获得此专长。"
s_feat_x_spl_cvt_1x	="可多次获得此专长，每次须选择不同的法术。"
s_feat_x_spl_cpy_1x	="可多次获得此专长，每次须选择不同的法术或类法术能力。"
s_feat_x_mle_undr	="可多次获得此专长，每次须选择不同的特殊材料。你的近战武器在穿透伤害减免时视为用所有这些材料制成。"-- Each time you select the feat, you select a different special material.
s_feat_x			="可多次获得此专长，效果叠加。"-- You can gain this feat multiple times. You may select this feat multiple times. A character can gain this feat multiple times. This feat may be taken multiple times. Its effects stack.
s_feat_x_max		="最多可获得%d次。"
s_feat_x_23			="两个两倍等于三倍，以此类推。"-- Remember that two doublings equals a tripling, and so on/forth.
s_feat_no_stk		="此专长不能和类似能力叠加。"
s_feat_no_stk_itm	="此专长不能和魔法物品或非永久魔法效果给予的类似效果叠加。"
s_shp_lmt			="体型限制和你的动物变身体型限制相同。"
s_x_nwpns			="%d个或更多天生武器"-- Three or more natural weapons
s_has_perm_sr		="有来自专长、职业特性或其他永久效果的法抗"
s_has_som_9			="能施展该学派至少一个九环法术"
s_has_cst_max_spl	="能施展至少一个施法者职业能施展的最高级法术"
s_has_acst_max_spl	="能施展一个奥术施法者职业能施展的最高级法术"
s_epic_feats		="传奇专长"	s_epic_feats_d=[[向百米开外的对手发射箭矢，空手赤拳便能斩敌首级，亦或用美妙歌声来迷惑巫妖——这就是传奇专长的力量。

和普通专长一样，传奇专长也是一种特殊能力，它要么赋予你的角色一种新的能力，要么增强一项已有的能力。然而，传奇专长将能力的领域从平凡升华至神话。

传奇专长只适用于角色等级为21级或以上的传奇角色。传奇角色在很大程度上是由其所选择的传奇专长来定义的。]]


s_turn1				="精通驱散"		s_turn1_d				="驱散检定+1加值。"
s_turn2				="高等驱散"		s_turn2_d				="精通驱散的加值再+1。"
s_turn_extra		="额外驱散"		s_turn_extra_d			="驱散的每天使用次数+4。"

s_abi_1_1x			="提升力量"		s_abi_1_1x_d			="你的肌肉和体能超出常人。\n\n力量增加1点。"
s_abi_2_1x			="提升敏捷"		s_abi_2_1x_d			="你的灵敏和协调超出常人。\n\n敏捷增加1点。"
s_abi_3_1x			="提升体质"		s_abi_3_1x_d			="你的健康和坚韧超出常人。\n\n体质增加1点。"
s_abi_4_1x			="提升智力"		s_abi_4_1x_d			="你的理解和学习能力超出常人。\n\n智力增加1点。"
s_abi_5_1x			="提升感知"		s_abi_5_1x_d			="你的意志力和洞察力超出常人。\n\n感知增加1点。"
s_abi_6_1x			="提升魅力"		s_abi_6_1x_d			="你的说服力和领导力超出常人。\n\n魅力增加1点。"
s_abi_7_1x			="提升体能属性"	s_abi_7_1x_d			="体能属性增加1点。"
s_abi_8_1x			="提升心灵属性"	s_abi_8_1x_d			="心灵属性增加1点。"
s_abi_9_1x			="提升所有属性"	s_abi_9_1x_d			="所有属性增加1点。"
s_hp_20x			="传奇健壮"		s_hp_20x_d				="你异常得强壮。\n\n生命值+20点。"
s_ft_4				="传奇强韧"		s_ft_4_d				="你异常得坚韧。\n\n所有强韧检定+4加值。"
s_rf_4				="传奇反射"		s_rf_4_d				="你拥有超常得快速反应。\n\n所有反射检定+4加值。"
s_wl_4				="传奇意志"		s_wl_4_d				="你拥有超常得坚强意志。\n\n所有意志检定+4加值。"
s_spd_6				="传奇神速"		s_spd_6_d				="你比正常人移动更迅速。\n\n速度提升30尺。\n\n特殊：穿着重甲时，此专长无效。"-- 先决条件：敏捷21，飞跑。
s_haste_5x			="闪电速度"		s_haste_5x_d			="你能短时间爆发出高速行动。\n\n每天能在如同加速术作用下行动5轮（无需连续）。激活此能力是一个自由动作。"-- 先决条件：敏捷25。	，每次增加5轮/天的加速效果。Each time you take the feat, it grants an additional 5 rounds of haste per day.
s_init_4x2			="高级先攻"		s_init_4x2_d			="战斗中，你比正常人反应更快。\n\n先攻检定+4加值。"-- 先决条件：精通先攻	此加值已包含（而非叠加）精通先攻的加值。This bonus overlaps (does not stack with) the bonus from Improved Initiative.
s_nac_2x			="装甲皮肤"		s_nac_2x_d				="你的皮肤如同护甲。\n\nAC+2天生防御加值，或现有天生防御加值增加2点。"
s_dr_3x				="伤害减免"		s_dr_3x_d				="你能减少攻击对你造成的部分伤害。\n\n获得伤害减免3/-。"-- 先决条件：体质21。	，但能和永久魔法效果、职业能力或此专长自身给予的伤害减免叠加	, but it does stack with any damage reduction granted by permanent magical effects, class features, or this feat itself	特殊：可多次获得此专长，每次增加3点伤害减免。Each time you gain the feat, your damage reduction increases by 3.
s_hr_3x				="快速痊愈"		s_hr_3x_d				="你的伤口愈合得很快。\n\n获得快速痊愈3，或现有快速痊愈增加3。"-- 先决条件：体质25。
s_imm_ill_psn		="完美体魄"		s_imm_ill_psn_d			="你免疫普通的疾病和毒素。\n\n免疫所有非魔法疾病，以及DC25及以下的毒素。"-- 先决条件：体质25，强韧加强
s_er_10x			="能量抗力"		s_er_10x_d				="你能抵抗某些类型的能量效果。\n\n选择一种能量类型（强酸、寒冷、电击、火焰、音波），获得10点对此能量类型的抗力，或现有此能量类型抗力增加10点。"-- 若选了同一种能量类型，则效果叠加。if the same type of energy is chosen, the effects stack.
s_sr_2x				="强化法术抗力"	s_sr_2x_d				="你对魔法效果的天生抵抗力增加了。\n\n法术抗力+2加值。"-- 先决条件：必须有来自专长、职业特性或其他永久效果的法术抗力。Prerequisite: Must have spell resistance from a feat, class feature, or other permanent effect.
s_dk_vis_2x			="强化黑暗视觉"	s_dk_vis_2x_d			="你在黑暗中视物的能力超乎寻常。\n\n黑暗视觉距离加倍。"-- 先决条件：黑暗视觉。
s_ll_vis_2x			="强化昏暗视觉"	s_ll_vis_2x_d			="你的昏暗视觉看得更远。\n\n昏暗视觉距离加倍。"-- 先决条件：昏暗视觉。

s_sa_ao				="借机偷袭"		s_sa_ao_d				="一旦对手放松警惕，你就可以进行偷袭。\n\n你所做的任何借机攻击都被视为是一次偷袭。"-- 先决条件：偷袭+8d6，趁势攻击职业特性。
s_sa_dot			="延续伤害"		s_sa_dot_d				="你的偷袭在你出手后仍会继续造成伤害。\n\n你成功造成偷袭伤害后，目标在你的下一回合将再次受到等同此偷袭额外伤害值的伤害。"-- 先决条件：偷袭+8d6，要害攻击职业特性。
s_rf_as_ft			="灵活坚韧"		s_rf_as_ft_d			="你能以非凡的灵敏抵抗物理攻击。\n\n每轮一次，当被需强韧检定的效果作为目标时，你可以进行一个反射检定来避免此效果（反射闪避不适用）。"-- 先决条件：敏捷25，心智灵活职业能力。
s_rf_as_wl			="灵活意志"		s_rf_as_wl_d			="你能以非凡的灵敏抵抗胁迫效果。\n\n每轮一次，当被需意志检定的效果作为目标时，你可以进行一个反射检定来避免此效果（反射闪避不适用）。"-- 先决条件：敏捷25，心智灵活职业能力。
s_dodge_atk			="传奇闪避"		s_dodge_atk_d			="你能以非凡的灵敏闪避攻击。\n\n每轮一次，当被武器攻击命中时，你能自动避开这次攻击的所有伤害。"-- 先决条件：敏捷 25，闪避，翻滚30级，精通反射闪避，翻躲职业特性。		当被你指定闪避的对手的一次攻击命中时	when struck by an attack from an opponent you have designated as the object of your dodge
s_miss_10			="自我隐蔽"		s_miss_10_d				="战斗中，你的形体变得模糊不清，很难被击中。\n\n对你的攻击有10%的失手率，类似隐蔽的效果。当你失去AC的敏捷加值时，你也会失去此效果。"-- 先决条件：敏捷30，躲藏30级，滚翻30级，精通反射闪避。		此专长官方未修正版：特殊：角色可以多次选择这个专长，每次增加10%，最高为50%。Special: This feat may be taken multiple times. Each time it is taken, the miss chance increases by 10% to a maximum of 50% after it has been taken five times.
s_rage_4_2			="强力狂暴"		s_rage_4_2_d			="你的狂暴更具威力。\n\n狂暴时，力量和体质+8加值，意志检定+4士气加值（用这些加值替换正常狂暴加值）。"-- 先决条件：力量21，体质21，大狂暴职业特性，狂暴5次/天。
s_rage_us			="激发狂暴"		s_rage_us_d				="当你进入狂暴时，60尺内的所有盟友会受你影响全部进入狂暴（盟友可自由选择不狂暴）。只要你仍在狂暴，盟友获得+4力量，+4体质，以及意志豁免+2士气加值，但AC受到-2减值。\n\n受影响盟友的狂暴持续时间等于3+他们的体质调整值，不管他们是否停留在你周围60尺内。其他方面则与正常的野蛮人狂暴一样（包括结束时的疲乏）。\n\n特殊：这是一个影响心灵的效果。"-- 先决条件：魅力25，大狂暴职业特性。
s_rage_chaos		="混沌狂暴"		s_rage_chaos_d			="你的狂暴对秩序生物更具伤害性。\n\n狂暴时你挥舞的任何武器均视为混沌武器（对守序阵营生物+2d6点伤害）。"-- 先决条件：狂暴5次/天，混乱阵营。	...不叠加（例如已是混沌武器）。This ability does not stack with similar abilities (for instance, if the weapon is already a chaotic weapon).
s_rage_thdr			="雷鸣狂暴"		s_rage_thdr_d			="狂暴时你发出雷鸣般得咆哮，能把敌人震聋。\n\n狂暴时你挥舞的任何武器均视为雷鸣武器。重击时造成额外1d8点音波伤害。若武器重击倍数为x3，则为2d8；x4则3d8。\n\n而且目标须进行一次强韧豁免检定（DC=10+1/2你的等级+你的力量调整值），失败则永久耳聋。"-- 先决条件：力量25，狂暴5次/天。	整合雷鸣描述 原文仅：...视为雷鸣武器。对抗耳聋的强韧检定DC=10+1/2你的等级。The DC of the Fortitude save to resist deafness is equal to 10 + 1/2 your level.
s_rage_obj			="破坏狂暴"		s_rage_obj_d			="狂暴时你能对物体造成极大伤害。\n\n狂暴时，你的攻击无视物体硬度。而且你在蛮力破坏物体而非造成正常伤害的力量检定上的力量加值翻倍（包括挣脱束缚，如绳子或镣铐）。"-- 先决条件：力量25，猛力攻击，精通击破武器，狂暴5次/天。
s_smite_2x			="强力重破斩"	s_smite_2x_d			="你的破邪斩或破善斩更具威力。\n\n当你成功使用破邪斩或破善斩时，在伤害值上加上两倍的适用等级值（而非仅一倍）。"-- 先决条件：魅力25，破邪斩或破善斩（职业特性或领域赋予的能力）。
s_wpn_as_good		="神圣打击"		s_wpn_as_good_d			="你的攻击能对邪恶生物造成巨大伤害。\n\n你挥舞的任何武器均视为神圣武器（善良阵营，对邪恶阵营的生物造成额外2d6点伤害）。若武器已有阵营，则此专长对此武器无效。"-- 先决条件：破邪斩职业特性，任意善良阵营。
s_wpn_as_evil		="邪恶打击"		s_wpn_as_evil_d			="你的攻击能对善良生物造成巨大伤害。\n\n你挥舞的任何武器均视为邪恶武器（邪恶阵营，对善良阵营的生物造成额外2d6点伤害）。若武器已有阵营，则此专长对此武器无效。"-- 先决条件：破善斩职业特性，任意邪恶阵营。
s_aura_vs_fear_8	="强化勇气灵光"	s_aura_vs_fear_8_d		="你的勇气灵光能产生更强的作用。\n\n你的勇气灵光在盟友对抗恐惧效果的豁免检定上+8士气加值。"-- 先决条件：魅力25，勇气灵光职业特性。
s_aura_saves_n4		="强化绝望暗气"	s_aura_saves_n4_d		="你的绝望暗气能产生更强的作用。\n\n你的绝望暗气在敌人所有豁免检定上-4士气减值。"-- 先决条件：魅力25，绝望暗气职业特性。
s_aura_vs_fear_r20	="扩展勇气光环"	s_aura_vs_fear_r20_d	="你的勇气光环能影响更大的范围。\n\n你的勇气光环能影响100尺内的所有盟友。"-- 先决条件：魅力25，勇气灵光职业特性。
s_aura_saves_r20	="扩展绝望暗气"	s_aura_saves_r20_d		="你的绝望暗气能影响更大的范围。\n\n你的绝望暗气能影响100尺内的所有敌人。"-- 先决条件：魅力25，绝望暗气职业特性。
s_fav_enm_1x		="强化宿敌"		s_fav_enm_1x_d			="对宿敌的唬骗、聆听、察言观色、侦查、生存检定，以及伤害骰均+1加值。"-- 先决条件：5个或更多的宿敌。
s_fav_enm_2_2d6		="宿敌克星"		s_fav_enm_2_2d6_d		="你能对宿敌造成巨大的伤害。\n\n特殊：攻击宿敌时，你挥舞的任何武器均视为破敌武器（+2增强加值，+2d6伤害）。"-- 先决条件：生存24级，5个或更多的宿敌（巡林客职业特性）。
s_fav_enm_kill		="宿敌杀手"		s_fav_enm_kill_d		="你一击就能杀掉你的宿敌。\n\n当你成功重击宿敌时，它须进行一次强韧豁免检定（DC=10+1/2你的巡林客等级+你的感知调整值），失败将立刻死亡。\n\n特殊：对重击免疫的生物不受本专长影响。"-- 先决条件：宿敌克星，生存30级，5个或更多的宿敌（巡林客职业特性）。
s_shp_ani_s2		="微型变身"		s_shp_ani_s2_d			="你能用野性变身变成微型动物。"-- 先决条件：能用野性变身变成超大型动物。	正常：若无此专长，你无法用野性变身变成超小型以下的动物。\n\nNormal: Without this feat, you cannot wild shape into an animal [of ]smaller than Tiny size.
s_shp_ani_s1		="超微型变身"	s_shp_ani_s1_d			="你能用野性变身变成超微型动物。"-- 先决条件：能用野性变身变成微型生物。	...
s_shp_ani_s8		="巨型变身"		s_shp_ani_s8_d			="你能用野性变身变成巨型动物。"-- 先决条件：能用野性变身变成超大型动物。	...超大型...Huge
s_shp_ani_s9		="超巨型变身"	s_shp_ani_s9_d			="你能用野性变身变成超巨型动物。"-- 先决条件：巨型变身	...
s_shp_plt			="植物变身"		s_shp_plt_d				="你能用野性变身变成植物。"-- 先决条件：自然知识24级，野性变身4次/天。	...形态。你能用正常的野性变身能力变身为植物。
s_shp_bug			="虫类变身"		s_shp_bug_d				="你能用野性变身变成虫类生物。"-- 先决条件：自然知识24级，野性变身6次/天。	...
s_shp_mbs			="魔法兽变身"	s_shp_mbs_d				="你能用野性变身变成魔法兽。你获得所变成的魔法兽的所有超自然能力。"-- 先决条件：感知25，自然知识27级，野性变身6次/天。	...
s_shp_dgn			="龙之变身"		s_shp_dgn_d				="你能用野性变身变成龙（可选：黑龙、蓝龙、绿龙、红龙、白龙、黄铜龙、青铜龙、赤铜龙、金龙或银龙）。你获得所变成的龙的所有特异和超自然能力。"-- 先决条件：感知30，自然知识30级，野性变身6次/天。	...
s_shp_elm_all		="强化元素变身"	s_shp_elm_all_d			="你能变身为更多种类的元素生物。\n\n你变身为元素生物的能力可包含所有元素生物（而非仅风、土、火和水元素）。你获得所变成的元素生物的所有特异和超自然能力。"-- 先决条件：感知25，能用野性变身变成元素。	例如，如果你通常能用野性变身变成巨型动物，你现在也能变身成巨型元素生物。\n\n正常：若无此专长，你只能用野性变身变成小型、中型或大型风、土、火或水元素。For instance, if you are normally capable of using wild shape to become a Huge animal, you can now wild shape into a Huge elemental creature.\n\nNormal: Without this feat, you may only wild shape into a Small, Medium-size, or Large air, earth, fire, or water elemental.
s_cmp_mbs			="魔法兽伙伴"	s_cmp_mbs_d				="你能与有限智力的魔法兽成为朋友。\n\n以下魔法兽添加到你能选择的动物伙伴列表。\n1级（无调整）：蚊蝠，暗幕魔兽\n4级（-3）：鹫马，电蜥蜴\n7级（-6）：蛇鸡兽，掘地虫，移位兽，狮鹫，枭熊，猫鱼*\n10级（-9）：石化蜥蜴，恐兽，四臂猩猩，食蛛兽\n13级（-12）：鲨蜥兽，奇美拉，百足魔兽\n16级（-15）：石化牛，灰袋兽\n\n特殊：有星号标记的生物仅在水生环境可选。"-- 先决条件：自然知识24级，野性变身6次/天。
s_mus_deaf			="震耳歌谣"		s_mus_deaf_d			="你的吟唱能让周围生物变聋。\n\n你能用歌谣或诗歌让你周围30尺内的所有敌人暂时耳聋。强韧检定（DC=10+1/2你的职业等级+你的魅力调整值）成功则无效。只要你持续演奏震耳歌谣，耳聋效果就一直持续，最多可持续演奏10轮。"-- 先决条件：表演24级，吟唱职业特性。	你可以选择让任何角色不受此效果影响（通常是你的盟友）。你可以一边歌唱、演奏或朗诵一边做其他事，但不能与魔法有关（详见吟游诗人的激发勇气能力）。使用震耳歌谣计入你一天的吟唱次数。	You can choose to exclude any characters from this effect (usually your allies). You may sing, play, or recite a deafening song while taking other mundane actions, but not magical ones (see the bard's inspire courage ability for more details). Using the deafening song counts as one of your uses of song or poetics for the day.
s_mus_uncst			="扰乱歌谣"		s_mus_uncst_d			="你的吟唱能干扰敌对施法者。\n\n你能用歌谣或诗歌干扰你周围30尺内的施法者。若想在此区域内成功施法，施法者需进行专注检定，如同防御式施法。最多可持续演奏扰乱歌谣10轮。"-- 先决条件：震耳歌谣，表演27级，吟唱职业特性。	...扰乱...	...hindering...	如同防御式施法，且检定上受到你等级一半的减值	, and all such checks have a penalty equal to half your level
s_mus_abi			="提振潜能"		s_mus_abi_d				="你能通过表演提升同伴的能力。\n\n你能用歌谣或诗歌使盟友的一项属性获得加值。盟友须听到吟唱1整轮才会受影响。吟唱时效果一直持续，停止吟唱（或听不到吟唱）后还会持续5轮。\n\n吟唱前你必须先选择一个属性，被提振盟友的此属性值+4表现加值。\n\n特殊：此专长是一种超自然、影响心灵的能力。就影响属性的专长而言，此专长视为吟唱提振能力。"-- 先决条件：表演30级，吟唱职业特性。	吟唱时，吟游诗人可以战斗但不能施法、触发储法物品（比如卷轴）或用指令启动魔法物品（比如魔杖）。	使用这个专长计入你每天的吟唱次数。	While singing, the bard can fight but cannot cast spells, activate magic items by spell completion (such as scrolls), or activate magic items by command word (such as wands).	Using this feat counts as one of your uses of song or poetics for the day.	比如，你可以给所有的盟友力量加值或是体质加值，但你不能给一部分盟友力量加值，又给另一部分盟友体质加值。For instance, you could grant all allies a bonus to Strength, or all allies a bonus to Constitution, but you couldn't grant some allies a bonus to Strength and some a bonus to Constitution with the same performance.
s_mus_rng			="远距吟唱"		s_mus_rng_d				="你的吟唱能影响更大的范围。\n\n所有吟唱能力的影响范围（若有）加倍。"-- 先决条件：表演25级，吟唱职业特性。	举例来说，有这个专长的诗人唱破咒曲时影响范围为60尺（而不是普通的30尺）；你可以使最远180尺外的一个生物迷魂；你可以给最远60尺内的所有盟友提振技能或提振战力。（如果生物必须听到吟唱才能受影响，这个条件不会改变，不管吟唱能力的范围有多远）。For instance, you can use countersong to protect creatures within 60 feet of you (rather than 30 feet); you can fascinate a creature up to 180 feet away; and you can inspire competence or greatness in an ally up to 60 feet away. (If the creature must hear the bard to be affected by the ability, that requirement doesn’t change regardless of any extended range the bard’s ability may have.)
s_mus_fast			="快速吟唱"		s_mus_fast_d			="你能更快得吟唱以激励盟友。\n\n能以标准动作使用任意吟唱提振能力，动作完成后立刻生效。"-- 先决条件：表演25级，吟唱职业特性。
s_mus_dur			="持久激发"		s_mus_dur_d				="你的歌声在你的声音消逝很久以后仍继续激励着盟友。\n\n所有吟唱提振能力在吟唱结束后的持续时间（若有）为正常的10倍。"-- 先决条件：表演25级，吟唱职业特性。	（比如提振技能）(such as inspire competence)	你的吟唱提振能力在吟唱结束后效果额外持续正常10倍的时间。此专长对停止吟唱后无持续效果的提振能力无效。
s_mus_grp			="群体振奋"		s_mus_grp_d				="你的提振技能和提振战力能同时激励更多盟友。\n\n提振技能、提振战力可影响的盟友数量加倍。当提振技能影响多个盟友时，可选择给他们提振不同的技能。"-- 先决条件：表演30级，吟唱职业特性。
s_mus_1x			="传奇吟唱"		s_mus_1x_d				="你的吟唱拥有超常的激励效果。\n\n吟唱能力给予的所有表现加值、闪避加值和士气加值均+1。若有提振战力吟唱能力，则增加的HD数+1。"-- 先决条件：魅力25，表演30级，吟唱职业特性。
s_mus_mind			="神之颂谣"		s_mus_mind_d			="你的吟唱能影响那些通常免疫影响心灵效果的生物。但那些生物对抗此类效果的意志检定+10加值。"-- 先决条件：魅力25，表演30级，吟唱职业特性。	你的吟唱能影响免疫影响心灵效果的生物。\n\n你的吟唱甚至
s_mus_unspl_anytime	="直觉破咒"		s_mus_unspl_anytime_d	="你能用破咒曲对抗音波或基于语言的魔法攻击。\n\n你能在任何时候开始吟唱破咒曲，即使不在你的回合。因此，你可以使用破咒曲作为反应动作对抗音波或基于语言的魔法攻击。\n\n你不能在使用其他吟唱能力时使用直觉破咒（虽然你可以停下其他吟唱能力再开始直觉破咒）。"-- 先决条件：战斗反射，表演30级，吟唱职业特性。	回合（就像法师准备动作反制魔法），但你无需事先准备动作	\n\n正常：若无此专长，你只能在你的回合使用破咒曲。 (much like a wizard who has readied a counterspell action), though you don’t have to ready an action to do so.	\n\nNormal: Without this feat, you can only use countersong on your turn.
s_zdd_def_6			="防御壁垒"		s_zdd_def_6_d			="防御姿态的加值提升为+4力量，+6体质，所有豁免检定+4抗力加值，AC+6闪避加值。"-- 先决条件：体质25，防御姿态3次/天。
s_zdd_def_mov_2		="移动防御"		s_zdd_def_mov_2_d		="你能在保持防御姿态的情况下调整站位。\n\n防御姿态下，每轮能做一个五尺快步而不失去防御姿态的优势。"-- 先决条件：敏捷15，闪避，灵活移动，跳跃攻击，防御姿态3次/天职业特性。	正常：若无此专长，防御姿态下不能移动。Normal: Without this feat, you can’t move while in a defensive stance.
s_zaa_da_2x			="强化死亡箭"	s_zaa_da_2x_d			="死亡箭的DC+2。"-- 先决条件：敏捷19，感知19，近程射击，精准射击，死亡箭职业特性。
s_zas_da_2x			="精通夺命攻击"	s_zas_da_2x_d			="夺命攻击的DC+2。"-- 先决条件：夺命攻击职业特性，偷袭+5d6。

s_all_atk_1x		="传奇神武"		s_all_atk_1x_d			="你在战斗中获得了高超的技巧。\n\n所有攻击检定+1加值。"
s_wpn_atk_2x2		="传奇专攻武器"	s_wpn_atk_2x2_d			="你尤其擅长使用某些武器。\n\n所有擅长武器的攻击检定+2加值。"-- 先决条件：专攻武器。	特殊：可多次获得此专长，但每次必须选择不同的武器。Special: You can gain this feat multiple times. Its effects do not stack. Each time you take the feat, it applies to a different type of weapon.
s_wpn_dmg_4x2		="传奇专精武器"	s_wpn_dmg_4x2_d			="你使用某些武器能造成超常的伤害。\n\n使用擅长武器造成的伤害+4加值。远程武器仅在30尺内有此伤害加值。"-- 先决条件：传奇专攻武器，专攻武器，武器专精（都在选择的武器上）	...
s_ch_kill			="致命重击"		s_ch_kill_d				="你使用某些武器能一击毙敌。\n\n当你使用擅长的近战武器造成重击时，目标必须进行一次强韧豁免检定（DC=10+你的角色等级/2+你的力量调整值），失败将立刻死亡。\n\n此专长对免疫重击的生物无效。"-- 先决条件：力量25，顺势斩，大顺势斩，精通重击（必须选同一种武器）、毁灭重击（必须选同一种武器）、猛力攻击、专攻武器（必须选同一种武器）。	特殊：可多次获得此专长，但是每次必须选新的一种武器。
s_natk_pen_0		="精通多重攻击"	s_natk_pen_0_d			="此生物特别善于同时使用其所有的天生武器。\n\n使用天生武器进行次要攻击无减值。"-- 先决条件：三个及以上的天生武器，多重攻击。	次要攻击仍只能将此生物的力量加值的一半（若有）加到伤害检定上。正常：若无此专长，此生物使用天生武器进行次要攻击受到-5减值（若有多重攻击专长则为-2减值）。They still add only one-half the creature’s Strength bonus, if any, to damage dealt.\n\nNormal: Without this feat, the creature’s secondary natural attacks have a –5 penalty (or a –2 penalty if it has the Multiattack feat).	[General]

s_ww_std			="精通旋风攻击"	s_ww_std_d				="你变成一股令人眼花缭乱的剑刃风暴，同时攻击周围的所有敌人。\n\n以一个标准动作，对攻击范围内的每个对手各进行一次近战攻击，最多攻击次数为你的基本攻击加值（包括传奇加值）/5。这些攻击（以及你在下一轮开始前做出的所有其他攻击）受到-4减值。"-- 先决条件：智力13，敏捷23，闪避，寓守于攻，灵活移动，跳跃攻击，旋风攻击。	epic attack bonus; round fractions down	\n\n使用此专长时，你还会失去其他专长或能力（比如顺势斩和加速术）带来的奖励或额外攻击。\n\n由于这些攻击都是一个标准动作的一部分，你在攻击期间不能进行五尺快步。\n\n正常：若无此专长，旋风攻击是整轮动作，而你可在任意两次攻击期间进行五尺快步。 For example, if your base attack bonus plus epic attack bonus were +24, you could make four separate melee attacks as a single standard action.\n\nWhen you use the Improved Whirlwind Attack feat, you also forfeit any bonus or extra attacks granted by other feats or abilities (such as Cleave or the haste spell).\n\nSince these attacks are made as part of a standard action, you can’t take a 5-foot step between them.\n\nNormal: Without this feat, using the Whirlwind Attack feat requires a full attack action, and you can take a 5-foot step between any two of the attacks.
s_chg_fatk_1		="恐怖冲锋"		s_chg_fatk_1_d			="你能以整轮攻击作为冲锋的一部分。\n\n如果你在战斗的第一轮或突袭轮对某个敌人发起冲锋，则你可对其进行整轮攻击。"-- 先决条件：精通先攻。	（或突袭轮，若你此时能行动的话）	正常：若无此专长，你冲锋时只能进行一次攻击。	surprise round, if you are allowed to act in it	\n\nNormal: Without this feat, you may only make a single attack as part of a charge.
s_ao_x				="精通战斗反射"	s_ao_x_d				="你能在任意数量的对手放松警惕时作出反应。\n\n你在一轮内可进行任意多次借机攻击。"-- 先决条件：敏捷21，战斗反射。	但一次借机仍然最多进行一次借机攻击。(You still can’t make more than one attack of opportunity for a given opportunity.)
s_def_cst_pen		="压制施法者"	s_def_cst_pen_d			="受你威胁的施法者很难进行防御式施法。\n\n任何施法者在你威胁范围内进行防御式施法时，专注检定会受到-10减值。"-- 先决条件：战斗反射。	你的等级一半的	takes a penalty on Concentration checks made to cast defensively equal to 1/2 your level
s_mle_undr			="穿透伤害减免"	s_mle_undr_d			="你能穿透生物的伤害减免。\n\n选择一种特殊材料，你的近战武器（包括天生武器）在穿透生物的伤害减免时视为用所选材料制成。特殊材料的其他特性不会应用到你的近战武器上。"-- 你的近战攻击能穿透生物的伤害减免，如同你的武器是用此材料制作的。	（比如精金的忽视硬度，或炼银武器的伤害-1） (such as adamantine’s ability to ignore hardness, or the –1 penalty to damage for silver weapons)

s_bow_no_ao			="格斗箭术"		s_bow_no_ao_d			="你能安全地在近战距离射箭。\n\n你能在敌人威胁范围内射箭而不会导致借机攻击。"-- 先决条件：闪避，灵活移动，近程射击。	正常：没有这个专长，你在使用弓箭时会受到威胁你的敌人的借机攻击。Normal: Without this feat, you incur an attack of opportunity from all opponents who threaten you whenever you use a bow.
s_rng_no_miss_50	="离奇精确"		s_rng_no_miss_50_d		="你使用远程武器时无视任何不高于全掩蔽或全隐蔽的情况。\n\n你的远程攻击无视全隐蔽导致的失手率。\n\n特殊：11级或更高等级的巡林客即使未满足先决条件也可选择本专长，但仅在穿着轻甲或无甲时有效。"-- 先决条件：敏捷21，基本攻击加值+11，近程射击，精准射击，精通精准射击，侦查20级。	你仍需攻击正确的方格来获得此专长的优势。正常：没有这个专长时，远程攻击全隐蔽的目标有50%的失手几率。You must aim your attacks at the correct square to gain the advantage of this feat.\n\nNormal: Without this feat, you suffer a 50% miss chance when making a ranged attack against a target with total concealment.
s_thr_all			="投掷风暴"		s_thr_all_d				="你化身为投掷武器的风暴，席卷附近所有对手。\n\n以一个整轮动作，使用一件魔法轻武器以最高基本攻击加值对30尺内的每个对手各投掷一次。"-- 先决条件：敏捷23，近程射击，即时备战（速拔），快速射击。	你能以最高基本攻击加值对30尺内的每个对手各投掷一件轻武器	而且你可以混合使用不同的武器，比如一个人类可以混合投掷匕首、飞镖和飞斧。All light weapons thrown need not be the same type; for instance, a human could throw a mix of daggers, darts, and throwing axes.

s_dfl_any			="卓越拨挡"		s_dfl_any_d				="你能像拨挡箭矢一样拨挡任何远程攻击，包括需远程接触攻击的法术。"-- 先决条件：敏捷21，感知19，拨挡飞箭，精通徒手击打。	传奇偏转	你能拨挡任何类型的远程攻击。You can deflect any type of ranged attack.	拨挡法术时，拨挡DC需加上法术等级。If deflecting a spell, add the spell level to the DC to deflect the attack.
s_rfl_any			="折返飞箭"		s_rfl_any_d				="你能把远程攻击折返回攻击者身上。\n\n当你拨挡箭矢或其他远程攻击后，此攻击会以你的基本远程攻击加值返还给攻击者。"-- 先决条件：敏捷25，拨挡飞箭，精通徒手击打。
s_dfl_x				="无限拨挡"		s_dfl_x_d				="每轮你能进行任意次数的拨挡。"-- 先决条件：敏捷25，战斗反射，拨挡飞箭，精通徒手击打。	无限偏转	你能拨挡无限数量的投射物。You can deflect an infinite number of projectiles.
