s_unarm_law			="秩序击打"		s_unarm_law_d			="你的徒手击打对混乱阵营生物更具伤害性。\n\n你的徒手击打视为守序武器（守序阵营，对混乱阵营的生物造成额外2d6点伤害）。"-- 先决条件：感知19，精通徒手击打，震慑拳，守序阵营，斗气击（守序）。	...叠加（例如其他效果已给予你的徒手击打守序特性）。(for instance, if some other effect has granted the axiomatic property to your unarmed strike).
s_unarm_ch3			="锋锐击打"		s_unarm_ch3_d			="你的徒手击打利如剑刃。\n\n你的徒手击打具有重击范围18-20且造成挥砍伤害（你可选择造成钝击伤害，但无法享有增强的重击范围）。"-- 先决条件：力量23，感知23，精通重击（徒手击打），精通徒手击打，震慑拳，斗气击（精金）。	此能力不与其他扩展徒手击打重击范围的能力叠加。This ability doesn’t stack with other abilities that expand your unarmed strike’s threat range.
s_unarm_kill		="斩首击打"		s_unarm_kill_d			="你的徒手击打能将对手斩首。\n\n你的徒手击打视为挥砍型斩首武器（你可选择造成钝击伤害，但会失去斩首特性）。"-- 先决条件：力量25，感知25，精通重击（徒手击打），精通徒手击打，锐锋击打，震慑拳，斗气击（精金）。	碎颅击	...叠加（例如其他效果已给予你的徒手击打斩首特性）。(for instance, if some other effect has already granted your unarmed strikes the vorpal quality).

s_spl_dc_1			="法术专攻"		s_spl_dc_1_d			="你的某些魔法学派的法术比其他法术强力得多。\n\n所选学派的法术豁免检定DC+1加值。"-- 法术专攻 专攻法术	选择一个法术学派。所选择学派的法术的所有豁免检定DC都获得+1加值。特殊：你可以多次选择本专长。其效果并不累加。每次必须选择不同的学派。高等专攻法术	选择一个你已经拥有专攻法术专长的法术学派。效果：所选择学派的法术的豁免检定DC都获得+1加值。该加值与专攻法术的加值可累加。特殊：你可以多次选择此专长，其效果并不累加。每次你都必须选择不同的已拥有专攻法术的学派。Choose a school of magic. Add +1 to the Difficulty Class for all saving throws against spells from the school of magic you select. Special: You can gain this feat multiple times. Its effects do not stack. Each time you take the feat, it applies to a new school of magic. Greater Spell Focus	Choose a school of magic to which you already have applied the Spell Focus feat. Add +1 to the Difficulty Class for all saving throws against spells from the school of magic you select. This bonus stacks with the bonus from Spell Focus. Special: You can gain this feat multiple times. Its effects do not stack. Each time you take the feat, it applies to a new school of magic to which you already have applied the Spell Focus feat.
