s_spl_cpy_1x		="法术仿制"		s_spl_cpy_1x_d			="选择一个你拥有的类法术能力或能施放的法术。一旦该魔法在你附近被使用，你就能获得其效果。\n\n你与所选魔法高度同调。若另一施法者在你周围300尺内使用该魔法，你也能立刻获得该魔法的效果，就如同那个施法者将该魔法用在你身上一样。\n\n你与施法者之间必须有直接的效果线以获得该同调魔法的好处（虽然你不必知道施法者的存在，而且你可以处于措手不及状态）。魔法的持续时间、效果等细节由其原施法者的等级决定。"-- 先决条件：辨识法术24级，施法者等级12。
s_spl_cvt_1x		="自发施法"		s_spl_cvt_1x_d			="选择一个你能施放的法术，你能将任何准备好的同级法术自发转化成所选法术，就像牧师引导能量将其他法术转化成治疗法术一样。"-- 先决条件：辨识法术25级，能够施展至少一个施法者职业所能施展的最高级法术。	ability to cast the maximum normal spell level of at least one spellcasting class.	选择一个你能施放的法术。你能将其他同级法术自发转化为该法术。You can spontaneously convert spells of that spell’s level into that spell.

