--[[
即时备战（QUICK DRAW）[一般专长]
先决条件：基本攻击加值+1。
效果：你拔取武器的动作视为即时动作，而非移动动作。你可以以一个移动动作拔取一把藏着的武器（见技能“手上功夫”）
选择了本专长的人物可以以其完整的正常攻击频率投掷武器（就如同使用弓的人物一般）。
正常：若没有本专长，你可以以一个移动动作拔取武器，或作为移动的一部分以一个即时动作（只要基本攻击加值达到+1或更高）拔取武器。若没有本专长，你可以以一个标准动作拔取一把藏着的武器。
特殊：战士可以选择本专长作为其战士奖励专长。
QUICK DRAW [GENERAL]
Prerequisite: Base attack bonus +1.
Benefit: You can draw a weapon as a free action instead of as a move action. You can draw a hidden weapon (see the Sleight of Hand skill) as a move action.
A character who has selected this feat may throw weapons at his full normal rate of attacks (much like a character with a bow).
Normal: Without this feat, you may draw a weapon as a move action, or (if your base attack bonus is +1 or higher) as a free action as part of movement. Without this feat, you can draw a hidden weapon as a standard action.
Special: A fighter may select Quick Draw as one of his fighter bonus feats.
]]
s_pa				="猛力攻击"		s_pa_d			=[[以超出的近战攻击加值换取伤害。

当你的近战攻击加值高过对手的防御等级时，超出部分自动转化为伤害加值（最多为你的基本攻击加值）。

当以双手武器攻击，或双手持握一把单手武器，或唯一主要天生武器，此伤害加值翻倍；而轻武器则无此伤害加值（除了徒手攻击或天生武器）。]]--pa_note		= "\n\n无需主动使用，条件符合时自动生效（如目标等级很低或处于睡眠昏迷等状态）。"	pa_note			= "\n\nNo need to use actively, the feat takes effect automatically when the conditions are met (e.g. target of very low level or stunned)."	pa_note			= "\n\nPas besoin de l'utiliser activement, le don prend effet automatiquement lorsque les conditions sont réunies (par exemple cible de très bas niveau ou étourdi)."	pa_note			="\n\nこの特技は積極的に使用する必要はなく、条件が満たされれば（例えば、非常に低いレベルのターゲットや朦朧状態の場合）自動的に有効になる。"
pwr_rng_pa_n		="猛力射击"		pwr_rng_pa_d	="类似<t=@pwr_pa c=fc_b>猛力攻击</t>，但应用于远程攻击（除了伤害加值翻倍规则）。"
--[[
当你的近战攻击高过对手的防御时，每1点多余的攻击自动转化为1点伤害。	Trade extra melee attack bonus for damage.\n\nIf your melee attack bonus is higher than your opponent's defense, redundant part converts to damage bonus automatically.	Échangez un bonus d'attaque de mêlée supplémentaire contre des dégâts.\n\nSi votre bonus d'attaque de mêlée est supérieur à la défense de votre adversaire, la partie redondante se convertit automatiquement en bonus de dégâts.	余剰した近接攻撃ボーナスをダメージに変換する。\n\n使用者の近接攻撃ボーナスが相手防御を上回ったならば、自動的に余剰分がダメージ・ボーナスに変換される。

猛力攻击（POWER ATTACK）[一般专长]
先决条件：力量13。
效果：当你动作时，在所有攻击检定之前，你可以选择让所有近战攻击减去特定数值，再将该数值加到所有近战伤害掷骰上。该数值不能超过你的基本攻击加值。攻击减值和伤害加值将持续到下轮动作之前。
特殊：如果你用双手武器攻击，或双手挥舞一把单手武器，伤害应加上两倍的攻击检定上减去的数值。在使用轻型武器时不能将猛力攻击中得到的加值加到伤害上（除了徒手击打或天生武器攻击之外），尽管攻击检定上的减值依然有效。（通常双头武器视为一把单手武器加一把轻型武器。如果你选择如同双手武器般使用双头武器，在一轮中仅用一头攻击，则其视为一把双手武器。）
战士可以选择本专长作为其战士奖励专长。

POWER ATTACK [GENERAL]
Prerequisite: Str 13.
Benefit: On your action, before making attack rolls for a round, you may choose to subtract a number from all melee attack rolls and add the same number to all melee damage rolls. This number may not exceed your base attack bonus. The penalty on attacks and bonus on damage apply until your next turn.
Special: If you attack with a two-handed weapon, or with a one-handed weapon wielded in two hands, instead add twice the number subtracted from your attack rolls. You can’t add the bonus from Power Attack to the damage dealt with a light weapon (except with unarmed strikes or natural weapon attacks), even though the penalty on attack rolls still applies. (Normally, you treat a double weapon as a one-handed weapon and a light weapon. If you choose to use a double weapon like a two-handed weapon, attacking with only one end of it in a round, you treat it as a two-handed weapon.)
A fighter may select Power Attack as one of his fighter bonus feats.

pf 猛力攻击（Power Attack）〔战斗〕
通过牺牲准度来换取力道，你能够做出异常致命的近战攻击。
先决条件：力量13，基本攻击加值+1。
专长效果：你可以选择在所有近战攻击和战技检定上承受-1减值，以在所有近战伤害检定上获得+2加值。如果你进行攻击时使用的是双手武器、双手持用的单手武器或可在伤害检定上加上1.5倍力量修正的主要天生武器，此伤害加值提升一半（+50%）。如果你进行攻击时使用的是副手武器或次要天生武器，此伤害加值减半（-50%）。当你的BAB达到+4，和以后的每4点提升，攻击减值再-1，伤害加值再+2。你必须在进行攻击检定前选择使用此专长，其效果持续到你的下回合之前。接触攻击和不造成生命点数伤害的效果无法获得伤害加值。

You can make exceptionally deadly melee attacks by sacrificing accuracy for strength.
Trade melee attack bonus for damage. You can choose to take a –1 penalty on all melee attack rolls and combat maneuver checks to gain a +2 bonus on all melee damage rolls. This bonus to damage is increased by half (+50%) if you are making an attack with a two-handed weapon, a one handed weapon using two hands, or a primary natural weapon that adds 1-1/2 times your Strength modifier on damage rolls. This bonus to damage is halved (–50%) if you are making an attack with an off-hand weapon or secondary natural weapon.\n\nWhen your base attack bonus reaches +4, and every 4 points thereafter, the penalty increases by –1 and the bonus to damage increases by +2.\n\nYou must choose to use this feat before making an attack roll, and its effects last until your next turn. The bonus damage does not apply to touch attacks or effects that do not deal hit point damage.
]]

s_tw			="双武器战斗"		s_tw_d			=[[你可以两手各持一把武器战斗。你每轮可以用第二把武器做一次额外攻击。

以这种方式进行战斗时，你的常规攻击或主手攻击会受到-6的减值，而你的副手攻击则会受到-10的减值。

你可以用以下两种方法来降低这些减值：
- 若你副手为轻型武器，则双手减值各降低2（徒手攻击始终视为轻型武器）。
- 双武器战斗专长可以使主手减值降低2，副手减值降低6。

下表归纳了所有这些因素组合作用时的效果。

双武器战斗减值：
<b>情况			主手	副手</b>
正常减值		-6	-10
副手轻武器		-4	-8
双武器战斗专长		-4	-4
专长 + 轻武		-2	-2

<b>双头武器：</b>你可以使用双头武器副手端所在的那一头进行一次额外攻击，如同使用两把武器战斗一样。计算减值时，副手端所在的那一头视为一把轻型武器。]]
s_hr_tw_ratk_2	="<t=$s_tw_nd c=fc_b>双武器战斗</t>：常规攻击时也有额外的一次副手攻击<c=twa>（未选：仅全力攻击时）</c>"
pwr_tw_n		="双武器战斗"		pwr_tw_d		="降低你使用两把武器战斗时受到的减值。你的主手减值降低2，副手减值降低6。\n\n通常："..s_tw_d
pwr_tw1_n		="精通双武器战斗"		pwr_tw1_d		="除了原本额外的一次副手攻击外，你还可以用副手多攻击一次，但有-5减值。"
pwr_tw2_n		="高等双武器战斗"		pwr_tw2_d		="你可以用副手武器作出第三次攻击，但有-10减值。"
pwr_tw3_n		="完美双武器战斗"		pwr_tw3_d		="你可以用副手武器进行和主手相同的攻击，包括相同的攻击次数，相同的基本攻击加值。你仍会受到使用双武器战斗的减值。"-- \n\n特殊：没有先决条件中的专长的巡林客也可选择本专长，只要他穿着轻甲或未着甲。	\n\nSpecial: A ranger can qualify for this feat even if he hasn’t taken the feats in the prerequisites, but can only use it when wearing light armor or no armor.
pwr_tw_def_n	="双武器防御"		pwr_tw_def_d	="当舞动一把双头武器或两把武器（不包括天生武器或徒手击打）时，你的防御等级获得+1盾牌加值。\n\n当你进行全力防御时，此盾牌加值增加为+2。"
pwr_tw_def1_n	="精通双武器防御"		pwr_tw_def1_d	="双武器防御的加值翻倍。"
pwr_tw_off_n	="双切"				pwr_tw_off_d	="副手伤害应用全部力量加值。\n\n你的副手武器在伤害上获得你的全部力量加值。通常你在副手武器上只能将力量调整值的一半计入伤害投骰。\n\n本专长也适用于猛力攻击和冲锋的额外伤害加成。"
pwr_tw_rend_n	="双武器撕裂"		pwr_tw_rend_d	="近战双武器同时命中时，撕裂对手。\n\n若你主手武器和副手武器的攻击都命中对手，则你额外造成1d10+1.5倍你的力量调整值的伤害。撕裂伤害导致的死亡不引发顺势斩。"
--[[
双武器攻击（TWO-WEAPON FIGHTING）[一般专长]
你可以两手各持一把武器战斗。你每轮可以用第二把武器作一次额外攻击。
先决条件：敏捷15。
效果：你用两把武器作战而遭受的减值将减低。你主手的减值减少2，而副手的减值减少6。
正常：若你的副手也使用一把武器，你每轮可用该武器作一次额外攻击。此时你主手的常规攻击将有-6减值而副手的攻击将有-10减值。如果你副手用的是轻型武器，则每只手的攻击检定减值各减少2（徒手击打永远视为轻型武器）。
特殊：选择了双武器战斗流派的2级巡林客在穿着轻甲或不穿甲时视为具有本专长，即使他不具备先决条件。
战士可以选择本专长作为战士的奖励专长。
TWO-WEAPON FIGHTING [GENERAL]
You can fight with a weapon in each hand. You can make one extra attack each round with the second weapon.
Prerequisite: Dex 15.
Benefit: Your penalties on attack rolls for fighting with two weapons are reduced. The penalty for your primary hand lessens by 2 and the one for your off hand lessens by 6.
Normal: If you wield a second weapon in your off hand, you can get one extra attack per round with that weapon. When fighting in this way you suffer a –6 penalty with your regular attack or attacks with your primary hand and a –10 penalty to the attack with your off hand. If your off-hand weapon is light the penalties are reduced by 2 each. (An unarmed strike is always considered light.)
Special: A 2nd-level ranger who has chosen the two-weapon combat style is treated as having Two-Weapon Fighting, even if he does not have the prerequisite for it, but only when he is wearing light or no armor.
A fighter may select Two-Weapon Fighting as one of his fighter bonus feats.

精通双武器攻击（IMPROVED TWO-WEAPON FIGHTING）[一般专长]
先决条件：敏捷17，双武器攻击，基本命中加值+6。
效果：除了原本额外的一次副手攻击外，你还可以用副手多攻击一次，但有-5减值。
正常：没有此专长，你只能用副手武器做一次额外攻击。
特殊：战士可以选择本专长作为其战士奖励专长。
选择了双武器战斗流派的6级巡林客在穿着轻甲或不穿甲时视为具有本专长，即使他不具备先决条件。
IMPROVED TWO-WEAPON FIGHTING [GENERAL]
Prerequisites: Dex 17, Two-Weapon Fighting, base attack bonus +6.
Benefit: In addition to the standard single extra attack you get with an off-hand weapon, you get a second attack with it, albeit at a –5 penalty.
Normal: Without this feat, you can only get a single extra attack with an off-hand weapon.
Special: A fighter may select Improved Two-Weapon Fighting as one of his fighter bonus feats.
A 6th-level ranger who has chosen the two-weapon combat style is treated as having Improved Two-Weapon Fighting, even if he does not have the prerequisites for it, but only when he is wearing light or no armor.

高等双武器攻击（GREATER TWO-WEAPON FIGHTING）[一般专长]
先决条件：敏捷19、精通双武器攻击、双武器攻击、基本攻击加值+11。
效果：你可以用你的副手武器作出第三次攻击，但有-10减值。
特殊：战士可以选择本专长作为其战士奖励专长。
选择了双武器战斗流派的11级巡林客视为拥有本专长，即使不具备先决条件，但需穿着轻甲或不穿甲。
GREATER TWO-WEAPON FIGHTING [GENERAL]
Prerequisites: Dex 19, Improved Two-Weapon Fighting, Two-Weapon Fighting, base attack bonus +11.
Benefit: You get a third attack with your off-hand weapon, albeit at a –10 penalty.
Special: A fighter may select Greater Two-Weapon Fighting as one of his fighter bonus feats.
An 11th-level ranger who has chosen the two-weapon combat style is treated as having Greater Two-Weapon Fighting, even if he does not have the prerequisites for it, but only when he is wearing light or no armor.

双武器防御（TWO-WEAPON DEFENSE）[一般专长]
先决条件：敏捷15、双武器攻击。
效果：当舞动一把双头武器或两把武器（不包括天生武器或徒手击打）时，你的防御等级获得+1盾牌加值。
当你进行防御式战斗或做全防动作时，该盾牌加值增加为+2。
特殊：战士可以选择本专长作为战士的奖励专长。
TWO-WEAPON DEFENSE [GENERAL]
Prerequisites: Dex 15, Two-Weapon Fighting.
Benefit: When wielding a double weapon or two weapons (not including natural weapons or unarmed strikes), you gain a +1 shield bonus to your AC.
When you are fighting defensively or using the total defense action, this shield bonus increases to +2.
Special: A fighter may select Two-Weapon Defense as one of his fighter bonus feats.
]]

pwr_th_n="双手武器战斗"	pwr_th_d="近战双手武器的伤害检定+2加值。"
pwr_th1_n="精通双手武器战斗"	pwr_th1_d="双手武器战斗的加值再+2。"
pwr_th_ko_n="击倒"	pwr_th_ko_d="近战双手武器命中时，10%几率触发击倒检定，目标战技对抗失败则倒地。"
pwr_th_ko1_n="精通击倒"	pwr_th_ko1_d="击倒的几率变为20%。"
pwr_th_atk1_n="双手武器专攻"	pwr_th_atk1_d="近战双手武器的攻击检定+1加值。"

pwr_rng_near_n="近程射击"		pwr_rng_near_d="使用远程武器攻击30英尺内的目标时，攻击和伤害检定+1加值。"
pwr_rng_far_n="远程射击"	pwr_rng_far_d="当你使用弹射类武器时（如弓），射程增加1/2（即乘1.5）。当你使用投掷类武器时，射程翻倍。"-- 特殊：战士可以选择本专长作为其战士奖励专长。Special: A fighter may select Far Shot as one of his fighter bonus feats.	range increment
pwr_rng_precise_n="精准射击"	pwr_rng_precise_d="远程攻击混战中的目标不受减值。\n\n你对处于混战中的对手进行远程攻击时不需在攻击上承受通常的-4减值。"
pwr_rng_precise1_n="精通精准射击"	pwr_rng_precise1_d="你的远程攻击忽略所有掩蔽和隐蔽效果，除了完全掩蔽或完全隐蔽。\n\n此外，当你远程攻击处于擒抱状态的目标时，你不会误伤（无此专长则需投随机骰来确定究竟攻击到谁）。"-- 除全掩蔽以外，你的远程攻击忽略任何其他较弱事物给目标带来的防御等级，同时除全隐蔽外，你还忽视任何其他较弱事物给目标带来的失手几率。全掩蔽和全隐蔽仍对你的远程攻击起正常作用。此外...你自动命中你选定的敌人	正常：掩蔽和隐蔽效果见其正常规则。无此专长的角色向擒抱中的敌人射击或投掷远程武器时必须投随机骰来确定该攻击究竟攻击到谁。	战士可以选择本专长作为其战士奖励专长。	A fighter may select Improved Precise Shot as one of his fighter bonus feats.	No cover or concealment chance on ranged attacks.	Your ranged attacks ignore the AC bonus granted to targets by anything less than total cover, and the miss chance granted to targets by anything less than total concealment. Total cover and total concealment provide their normal benefits against your ranged attacks.	Normal: See the normal rules on the effects of cover and concealment. Without this feat, a character who shoots or throws a ranged weapon at a target involved in a grapple must roll randomly to see which grappling combatant the attack strikes.
pwr_atk_r_atk2_n="快速射击"	pwr_atk_r_atk2_d="你使用远程武器时，每轮可以多攻击一次。这次攻击基于你最高基本攻击加值，但该轮内所有攻击检定（额外的这次和正常的那些）均有-2减值。你必须在全力攻击时使用本专长。"
--[[
快速射击（RAPID SHOT）[一般专长]
先决条件：敏捷13、近程射击。
效果：你使用远程武器时，每轮可以多攻击一次。这次攻击以最高的基本攻击加值计算，但该轮内所有攻击检定（额外的这次和正常的那些）均有-2减值。你必须在全力攻击时使用本专长。
特殊：战士可以选择本专长作为其战士奖励专长。
选择了箭术战斗流派的2级巡林客在穿着轻甲或不穿甲时视为具有本专长，即使他不具备先决条件。
RAPID SHOT [GENERAL]
Prerequisites: Dex 13, Point Blank Shot.
Benefit: You can get one extra attack per round with a ranged weapon. The attack is at your highest base attack bonus, but each attack you make in that round (the extra one and the normal ones) takes a –2 penalty. You must use the full attack action to use this feat.
Special: A fighter may select Rapid Shot as one of his fighter bonus feats.
A 2nd-level ranger who has chosen the archery combat style is treated as having Rapid Shot, even if he does not have the prerequisites for it, but only when he is wearing light or no armor.
]]
pwr_atk_r_atk2_1_n="精通快速射击"	pwr_atk_r_atk2_1_d="免除快速射击的惩罚。"
pwr_atk_r_atk2_2_n="高等快速射击"	pwr_atk_r_atk2_2_d="快速射击的攻击次数变为3次。"
pwr_atk_r_tgt3_n="多重射击"	pwr_atk_r_tgt3_d="对指定范围内的多个敌人，分别进行一次远程攻击。所有攻击基于你最高基本攻击加值，但有-2减值。"..use_a
--[[
多重射击（MANYSHOT）[一般专长]
先决条件：敏捷17，近程射击，速射，基本攻击加值+6。
效果：你可以以一个标准动作向30尺内的一个单一敌人射出两箭。这两支箭使用同样的攻击掷骰（有-4减值）来决定是否命中，并且正常地造成伤害（见“特殊”）。
你的基本攻击加值每比+6高5，你就可以在一次攻击中多射一支箭，最多可射4支箭（当基本攻击达到16）。然而，每比两支箭多射一支箭都要在攻击掷骰上递加-2的减值（射三支箭共有-6的减值，而射四支共有-8的减值）。
伤害减免和其他抗性单独作用于每一支箭。
特殊：无论你射出多少支箭，你只能应用一次基于精准的攻击伤害。如果你掷出重击，只有射出的第一箭造成重击伤害；其他所有的箭造成普通伤害。
战士可以选择本专长作为其战士奖励专长。
选择了箭术战斗流派的6级巡林客在穿着轻甲或不穿甲时视为具有本专长，即使他不具备先决条件。
MANYSHOT [GENERAL]
Prerequisites: Dex 17, Point Blank Shot, Rapid Shot, base attack bonus +6
Benefit: As a standard action, you may fire two arrows at a single opponent within 30 feet. Both arrows use the same attack roll (with a –4 penalty) to determine success and deal damage normally (but see Special).
For every five points of base attack bonus you have above +6, you may add one additional arrow to this attack, to a maximum of four arrows at a base attack bonus of +16. However, each arrow after the second adds a cumulative –2 penalty on the attack roll (for a total penalty of –6 for three arrows and –8 for four).
Damage reduction and other resistances apply separately against each arrow fired.
Special: Regardless of the number of arrows you fire, you apply precision-based damage only once. If you score a critical hit, only the first arrow fired deals critical damage; all others deal regular damage.
A fighter may select Manyshot as one of his fighter bonus feats.
A 6th-level ranger who has chosen the archery combat style is treated as having Manyshot even if he does not have the prerequisites for it, but only when he is wearing light or no armor.
]]
pwr_atk_r_tgt3_1_n="精通多重射击"	pwr_atk_r_tgt3_1_d="免除多重射击的惩罚。"
pwr_atk_r_tgtx_n="箭雨"	pwr_atk_r_tgtx_d="对远程攻击范围内的所有敌人，分别进行一次远程攻击。所有攻击基于你最高基本攻击加值，但有-2减值。"..use_b
pwr_atk_r_tgtx_1_n="精通箭雨"	pwr_atk_r_tgtx_1_d="免除箭雨的惩罚。"
pwr_rng_xbow_n="弩狙击"	pwr_rng_xbow_d="弩类武器的伤害检定+2加值。"
pwr_rng_wis_n="禅宗箭术"	pwr_rng_wis_d="远程攻击时，你可以在攻击检定中使用你的感知调整值代替敏捷调整值。"--不适用于重投掷。 Not for heavy thrown weapons. Ne fonctionne pas sur les armes lourdes.重投擲武器には適用不可。

pwr_stunning_fist_d=[[
你徒手攻击打出的震慑拳除正常造成伤害外，还进行一次强韧检定（你的角色等级/2 + 感知调整值 vs 目标的强韧防御），成功则目标被<t=@cond_stunned_nd c=r>震慑</t>一轮。

每天使用次数：武僧等级 + 非武僧等级/4。
每轮最多使用1次。攻击失手时也会消耗次数。
]]-- 一般专长 敏捷13、感知13、精通徒手击打、基本攻击加值+8。	被震懾的生物無法行動，防禦等級上失去所有敏捷加值，並且還有-2減值。	构装生物、泥状怪物、植物、不死生物、虚体生物和免疫重击的生物无法被震慑。	攻击之前必须先宣布使用本专长（因此，若攻击检定失败则即失去该次尝试机会）。	特殊：武僧可以在1级时选择本专长作为奖励专长，即使未满足先决条件。选择了本专长的武僧每天可以使用震慑攻击的次数等于其武僧级别加上非武僧级别除以四。战士可以选择本专长作为战士的奖励专长。

pwr_ch_mle_dmg_d=[[
使用擅长的近战武器重击时，能造成额外伤害：
若武器致命系数为x2，加1d6点伤害。
若武器致命系数为x3，加2d6点伤害。
若武器致命系数为x4，加3d6点伤害。

此专长对免疫重击的生物无效。
]]-- Epic 选择一种近战武器（如长剑或巨斧），此武器的重击效果更强。	力量23，猛力攻击，顺势斩，大顺势斩，精通重击（同一种武器），专攻武器（同一种武器）。	特殊：你可以多次选择本专长。效果不累加。每次你获得此专长，其应用于新的武器类型。

pwr_rage_fear_d=[[
狂暴时，你能让对手陷入恐慌。

当你狂暴时，所有看见你的敌人都必须进行一次意志检定（你的威吓等级 vs 敌人的意志防御），成功时：

若敌人角色等级 ＜ 你的角色等级，则陷入恐慌，持续1d4轮。

若敌人角色等级 ≥ 你的角色等级但 ≤ 你的人物等级x2，则陷入战栗，持续1d4轮。

若敌人角色等级 ＞ 你的角色等级x2，则不受影响。
]]-- Epic 	威吓25级，5次狂暴/每天。Intimidate 25 ranks, rage 5/day.	3r 4d6

pwr_unarmed_strike_d=[[
武僧受过严格的徒手战斗训练，徒手作战时具有很强的威力。

武僧的攻击可以用双拳，也可以用肘、膝、或脚，所以即使双手都拿着东西仍可使用徒手攻击。武僧徒手攻击时也无主副手之分，总是将完整的力量加值加到伤害骰上。

随着武僧等级的提升，其徒手击打拥有更多的攻击次数（6、14、18级时各增加1次）和更高的伤害。

各体型武僧徒手击打伤害表：
等级	小体型	中体型	大体型
1	1d4	1d6	1d8
4	1d6	1d8	2d6
8	1d8	1d10	2d8
12	1d10	2d6	3d6
16	2d6	2d8	3d8
20	2d8	2d10	4d8

<c=o>此能力作为开关能力开启时，近战始终徒手攻击，即使正持握近战武器。</c>
]]-- z_lv_dmg_dice	通常武僧的徒手攻击造成的是正常伤害，不过他也可以选择造成非致命伤而不必受到任何命中减值。在擒抱时他同样可以选择造成何种伤害。	在考虑增强人工武器或天生武器的法术效果时，武僧的徒手攻击既视为人工武器又视为天生武器。	当使用法术效果（例如「魔牙术」或「魔化武器」）来提升或强化人造武器或天生武器时，武僧的徒手攻击可被同时视为人造及天生武器。		武僧的攻击可以用双拳，也可以用肘，膝，或脚。这意味着武僧甚至可以在双手都拿着东西的情况下进行徒手攻击。对武僧的徒手攻击来说，没有副手攻击这个概念。武僧可以将其完整的力量加值加在所有的徒手攻击上。

pwr_flurry_of_blows_d=[[
未着防具时，武僧可以牺牲准确性来换取疾风连击的能力。

1级：	额外攻击1次。本轮所有攻击检定-2减值。
5级：	减值降为-1。
9级：	无减值。
11级：	额外攻击2次。

必须徒手或使用特殊武僧武器进行疾风连击。徒手时，徒手击打本身的额外攻击次数也生效。

疾风连击的伤害骰上总是应用完整的力量加值。

当穿着盔甲、持用盾牌、中载或重载时，无法使用此能力。
]]-- Ex	（单镰、双截棍、木棍、十手、手里剑、破魔椎）	11级起，额外攻击次数再+1。	当使用武器时，无论单手或双手持用，伤害骰上都应用完整的力量加值。	可以交替使用徒手和武僧武器进行攻击。	不能使用非武僧武器来做疾风攻击。	如果使用的武器是木棍，在进行疾风连击时木棍的两头当作是不同的武器。即使木棍需要双手持用，只要疾风连击的攻击次数允许，武僧仍然能使用徒手攻击。例如8级武僧进行疾风连击时可攻击三次，他可以使用木棍攻击两次（分别用木棍两端），攻击加值为+5，第三次使用徒手攻击，攻击加值为+0。他也可以使用木棍攻击一次，徒手攻击一次，两次的攻击加值皆为+5，再用木棍攻击第三次，攻击加值为+0。不过在持用木棍时不能再持用其他武器。	（而非1+1/2或1/2的力量加值）	pf 8级额外攻击2次 15级3

pwr_ac_bonus_d=[[
武僧受过良好的闪避训练，具有独特的第六感，可以下意识地躲开攻击。

未着防具且未超重时，武僧可将感知加值加到防御上。此外，每5个武僧等级获得+1加值（5级+1，10级+2…）。

即使面对接触攻击或措手不及，这些加值仍有效。但若动弹不得、陷入无助、穿着盔甲或法袍等、持用盾牌、中载或重载时，则会失去这些加值。
]]-- Ex	pf 每4级 也用于cmd

pwr_ki_atk_d=[[
武僧的徒手攻击中灌注着真气，随着武僧等级提升而增强。

徒手攻击每5级+1增强加值（5级时+1，10级时+2…）。

穿透伤害减免时，其徒手攻击视为特定类型的武器：
4级：	魔法武器
7级：	寒铁和炼银武器
10级：	守序武器
16级：	精金武器

<c=o>（寒铁和守序武器相关怪物开发中）</c>
]]-- 攻破硬度时视为精金	pf 气运丹田 气池	z_ki_atk

pwr_quivering_palm_d=[[
武僧能使用恐怖的渗透劲，在其他生物体内制造致命的震荡。

此能力开启时，若武僧击中目标且造成伤害，则渗透劲攻击成功。

此后任意时刻，武僧可尝试直接用意念杀死目标：武僧等级/2 + 感知调整值 vs. 目标强韧，成功则目标死亡，失败则此渗透劲失效。

此能力对免疫重击的生物无效。]]-- 此后武僧等级天数内	武僧能在其他生物体内制造一种震荡，之后如果武僧愿意，这震动足以致命。	对方将不会再因这次渗透劲而受到伤害，但是他依然可能被之后其他渗透劲攻击所伤。	这之后武僧可以在一定天数内尝试杀死对方，该时间期限天数为他的武僧等级。要做杀死对方，武僧只需要用意念让对方死即可（即时动作），如果对方没有通过强韧检定（DC=10+1/2武僧等级+武僧感知修正），它就死了。如果该豁免检定获得成功，对方将不会再因这次渗透劲而受到伤害，但是他依然可能被之后其他渗透劲攻击所伤。	渗透劲无法作用于构装生物、泥形生物、植物、不死生物、虚体生物和无法遭受重击的生物。	只须心中想着要使目标死亡（即时动作），目标便须进行强韧检定（DC=10+武僧等级的一半+武僧感知调整值），若失败则死亡。如果目标通过强韧检定，则不会再受此次渗透劲所威胁（但或许下次又中了渗透劲）。

pwr_empty_body_d=[[
武僧能进入以太位面，化成灵体。

此能力持续期间，武僧身处以太位面，一个与正常主物质位面重叠共存的世界。能力结束时，武僧将返回主物质位面，变回实体。每日总维持轮数=武僧等级，可分多次使用。

对于主物质位面而言，灵体不可见也摸不到。而它可看见和听见主物质位面，但一切看上去都是灰色的模糊的。它在主物质位面的视觉与听觉范围为60英尺。

一般而言，灵体生物和实体生物无法攻击对方。而灵体生物或物品之间则如同均为实体。

另外，作为没有实体的生物，灵体可以穿越主物质位面的固体，包括活物。若能力结束时它仍在固体中（如墙体），则会被挤到最近的空地，每经过5英尺遭受1d6点伤害。
]]-- pf 1分钟


