pwr_fire_ball_d="火球术造成一团带着低鸣的火焰爆炸，对区域内所有生物造成每级1d6点火焰伤害。"
--[[
火球术（Fireball）
 塑能系[火]
等级：术士/法师 3
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：远距（400英尺+40英尺/每等级）
区域：20英尺半径扩散区域
持续时间：立即
豁免：反射减半
法术抗力：可

火球术法术造成一团带着低鸣的火焰爆炸，对区域内所有生物造成每施法者等级1d6（最高10d6）的火伤害。没有被持用的物品也要受到这个伤害。爆炸几乎不会造成压力。

你用手指指向目标点，并决定火球术爆发起点的距离（距离和高度）。一颗豌豆大小的炽热小球会从指尖飞出，之后除非在到达前撞上物体或固体阻碍物，否则会在指定点爆炸开。（提前碰撞会在那点炸开。）如果你尝试让小球通过狭窄通道，例如箭孔等，你必须通过一个远程接触攻击来“命中”那个开口，否则就会撞上阻碍而过早引爆。

火球术会引燃易燃物，并且对区域内的物品造成伤害。它可以熔化低熔点的金属，例如铅、金、铜、银、青铜。如果伤害足以粉碎或破坏这类阻碍，火球术可以扩散到这阻碍后；否则和其他法术效果一样，它会被这阻碍所阻止。

材料成分：一个蝙蝠粪和硫磺小球。

 Fireball
 Evocation [Fire]
Level: Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Area: 20-ft.-radius spread
Duration: Instantaneous
Saving Throw: Reflex half
Spell Resistance: Yes

A fireball spell is an explosion of flame that detonates with a low roar and deals 1d6 points of fire damage per caster level (maximum 10d6) to every creature within the area. Unattended objects also take this damage. The explosion creates almost no pressure.

You point your finger and determine the range (distance and height) at which the fireball is to burst. A glowing, pea-sized bead streaks from the pointing digit and, unless it impacts upon a material body or solid barrier prior to attaining the prescribed range, blossoms into the fireball at that point. (An early impact results in an early detonation.) If you attempt to send the bead through a narrow passage, such as through an arrow slit, you must "hit" the opening with a ranged touch attack, or else the bead strikes the barrier and detonates prematurely.

The fireball sets fire to combustibles and damages objects in the area. It can melt metals with low melting points, such as lead, gold, copper, silver, and bronze. If the damage caused to an interposing barrier shatters or breaks through it, the fireball may continue beyond the barrier if the area permits; otherwise it stops at the barrier just as any other spell effect does.

Material Component: A tiny ball of bat guano and sulfur.
]]

pwr_meteor_swarm_d=[[
流星爆是一个强力而且壮观的法术，它在很多方面都跟火球术很像，除了范围更大，伤害更猛烈。

当你施展此法术时，无数颗火球从目标区域上空轰鸣着飞出。这些流星会拖着一条条火光灿烂的尾巴，以直线路径砸向你选定的区域，对其中的所有生物造成每级1d6点火焰伤害和每2级1d6点钝击伤害。
]]
--[[
流星爆（Meteor Swarm）
 塑能系[火焰]
等级：术士/法师9
法术成分：言语，姿势
施法时间：1个标准动作
距离：远距（400英尺+40英尺/施法者每等级）
区域：四个半径40英尺的扩散范围；见说明
持续时间：立即
豁免：无；或反射，通过则效果减半；见说明
法术抗力：可

流星爆是一个强力而且壮观的法术，它很多方面都跟火球术（fireball）很像。当你施展此法术时，四颗直径2英尺的火球从你伸展的手中飞出，这些流星会拖着一条火光灿烂的尾巴，以直线路径飞向你选定的地点。

如果你将流星瞄准一个特定的生物，你必须分别为每颗流星做一个远程接触攻击检定来使流星命中目标。任何生物只要被流星击中，每颗击中他的流星会对他造成2d6点钝击伤害（无豁免），并且接下来他不能对成功击中他的流星所产生的火焰伤害做任何豁免（见下文）。如果流星没有成功命中所指定的目标，则会在目标生物所在空间边最近的方格交叉点爆炸。你可以指定多颗流星瞄准同一个目标。

一旦流星到达目的地，它就会爆炸并波及所有半径40英尺扩散范围内的生物。每颗流星会对每个在爆炸区域内的生物造成6d6点伤害。如果生物在多颗流星的爆炸范围内，他必须分别对每颗流星做反射检定。（火焰抗力也需分别对每颗流星计算。）

Meteor Swarm
 Evocation [Fire]
Level: Sor/Wiz 9
Components: V, S
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Area: Four 40-ft.-radius spreads; see text
Duration: Instantaneous
Saving Throw: None or Reflex half; see text
Spell Resistance: Yes

Meteor swarm is a very powerful and spectacular spell that is similar to fireball in many aspects. When you cast it, four 2- foot-diameter spheres spring from your outstretched hand and streak in straight lines to the spots you select. The meteor spheres leave a fiery trail of sparks.

If you aim a sphere at a specific creature, you may make a ranged touch attack to strike the target with the meteor. Any creature struck by one of these spheres takes 2d6 points of bludgeoning damage (no save) and receives no saving throw against the sphere's fire damage (see below). If a targeted sphere misses its target, it simply explodes at the nearest corner of the target's space. You may aim more than one meteor at the same target.

Once a sphere reaches its destination, it explodes in a 40-foot-radius spread, dealing 6d6 points of fire damage to each creature in the area. If a creature is within the area of more than one sphere, it must save separately against each. (Fire resistance applies to each sphere's damage individually.)
]]


pwr_ice_nova_d="冻结周围的敌人，使之无法移动，并造成每级1d4点寒冷伤害。"

pwr_ice_storm_d="猛烈的魔法冰雹从天而降，持续一整轮，对范围内每个生物造成每2级1d6点钝击伤害与每3级1d6点寒冷伤害，且移动速度减半。法术结束后，冰雹消失，不会留下任何痕迹（除了造成的伤害）。"
--[[
冰风暴（Ice Storm）
 塑能系 [寒冷]
等级：德鲁伊 4，术士/法师4，水 5
法术成分：言语，姿势，材料/法器
施法时间：1个标准动作
距离：远距 （400英尺+40英尺/等级）
区域：柱状（半径20英尺，40英尺高）
持续时间：1整轮
豁免：无
法术抗力：可

强烈的魔法冰雹从天而降，持续一整轮，对范围内的一切生物造成3d6钝击伤害与2d6的寒冷伤害。冰风暴内的生物在聆听检定上有-4减值，并所有陆地移动速度减半。在法术结束后，冰雹会消失而不会留下任何痕迹（除了造成的伤害）。

奥术材料：一撮沙子和几滴水。

Ice Storm
 Evocation [Cold]
Level: Drd 4, Sor/Wiz 4, Water 5
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Area: Cylinder (20-ft. radius, 40 ft. high)
Duration: 1 full round
Saving Throw: None
Spell Resistance: Yes

Great magical hailstones pound down for 1 full round, dealing 3d6 points of bludgeoning damage and 2d6 points of cold damage to every creature in the area. A -4 penalty applies to each Listen check made within the ice storm's effect, and all land movement within its area is at half speed. At the end of the duration, the hail disappears, leaving no aftereffects (other than the damage dealt).

Arcane Material Component: A pinch of dust and a few drops of water.
]]


pwr_litn_d="你从指尖释放出一道强力的闪电束，对处于影响区域内的的每个生物造成每级1d6点电击伤害。"
--[[
闪电束（Lightning Bolt）
 塑能系 [电击]
等级：术士/法师 3
法术成分：言语，姿势，材料
施法时间：1个标准动作
距离：120英尺
区域：120英尺线状
持续时间：立即
豁免：反射，通过则效果减半
法术抗力：可

你从指尖释放出一道强力的闪电束，对处于影响区域内的的每个生物造成每施法者等级1d6（最多10d6）的伤害。

闪电束会引燃可燃物，同时会损害路径上的物品。闪电会融化某些低熔点金属，如：铅、金、铜、银和青铜。如果障碍物被击穿或是击碎，闪电会穿过障碍物继续前进，直到超出法术的最大距离。否则，闪电就象其他法术效果一样会被障碍物挡住。

法术材料：一些毛皮和一块琥珀、水晶或玻璃棒

Lightning Bolt
 Evocation [Electricity]
Level: Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: 120 ft.
Area: 120-ft. line
Duration: Instantaneous
Saving Throw: Reflex half
Spell Resistance: Yes

You release a powerful stroke of electrical energy that deals 1d6 points of electricity damage per caster level (maximum 10d6) to each creature within its area. The bolt begins at your fingertips.

The lightning bolt sets fire to combustibles and damages objects in its path. It can melt metals with a low melting point, such as lead, gold, copper, silver, or bronze. If the damage caused to an interposing barrier shatters or breaks through it, the bolt may continue beyond the barrier if the spell's range permits; otherwise, it stops at the barrier just as any other spell effect does.

Material Component: A bit of fur and an amber, crystal, or glass rod.
]]

pwr_litn_x_d=[[
此法术在你的指尖上制造出一股放电电流，电流在释放的时候仅仅是单独的一道。与闪电束不同的是，连环闪电会先击中一个目标或生物，再通过电弧击中其他目标。

闪电对主要目标造成每级1d6点电击伤害。击中后，闪电弧还可击中视野内其他次要目标。次要目标与主要目标距离不得超过30英尺，最大数量等于你的施法者等级，且同一目标不可被击中超过一次。

次要目标所受的伤害为主要目标所受伤害的一半。所有受害者若通过反射检定则只受到一半伤害。
]]
--[[
连环闪电（Chain Lightning）
 塑能系[电]
等级：气 6,术士/法师 6
法术成分：言语，姿势，器材
施法时间：一个标准动作
距离：远距（400英尺+40英尺/每等级）
目标：一个主要目标，加上每等级一个次要目标（每个次要目标都必须在距离主要目标30英尺的范围内）
持续时间：立即
豁免检定：反射，通过则效果减半
法术抗力：可

此法术在你的指尖上制造出一股放电电流，电流在释放的时候仅仅是单独的一道。与闪电束（lightning bolt）不同的是，连环闪电会先击中一个目标或生物，再通过电弧击中其他目标。

闪电可对主要目标造成每施法者等级1d6点伤害（最多20d6）。击中后，闪电弧还可击中其他次要目标，次要目标数量等于你施法者等级（最多20个次要目标）。次要目标所受的伤害为主要目标所受伤害的一半（舍去小数）。

所有受害者若通过反射检定则只受到一半伤害。你可以自行选定次要目标，但他们与主要目标距离不得超过30英尺，而且同一目标不可被击中超过一次。所选次要目标数可以少于最多次要目标数。

器材：一些毛皮、一块琥珀、玻璃或一柄水晶权杖，再加上数量与你施法者等级相同的银质别针。

Chain Lightning
 Evocation [Electricity]
Level: Air 6, Sor/Wiz 6
Components: V, S, F
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Targets: One primary target, plus one secondary target/level (each of which must be within 30 ft. of the primary target)
Duration: Instantaneous
Saving Throw: Reflex half
Spell Resistance: Yes

This spell creates an electrical discharge that begins as a single stroke commencing from your fingertips. Unlike lightning bolt, chain lightning strikes one object or creature initially, then arcs to other targets.

The bolt deals 1d6 points of electricity damage per caster level (maximum 20d6) to the primary target. After it strikes, lightning can arc to a number of secondary targets equal to your caster level (maximum 20). The secondary bolts each strike one target and deal half as much damage as the primary one did (rounded down).

Each target can attempt a Reflex saving throw for half damage. You choose secondary targets as you like, but they must all be within 30 feet of the primary target, and no target can be struck more than once. You can choose to affect fewer secondary targets than the maximum.

Focus: A bit of fur; a piece of amber, glass, or a crystal rod; plus one silver pin for each of your caster levels.
]]


pwr_acid_arrow_d=[[
从你手中飞出一支魔法强酸箭迅速射向目标。你必须做一次成功的远程接触攻击才能击中你的目标。

这支箭造成每3级2d4点强酸伤害（无溅射伤害）。

除非被某种方法中和掉，强酸持续1轮+1轮/每3级（18级时达到最多7轮），并在该轮内再次造成每3级2d4点强酸伤害。
]]
--[[
强酸箭（Acid Arrow）
 咒法系（创造）[强酸]
等级：术士/法师 2
法术成分：言语，姿势，材料，器材
施法时间：一个标准动作
距离：远距（400英尺+40英尺/每等级）
效果：一支强酸箭
持续时间：1轮+1轮/每3等级
豁免：无
法术抗力：不可

从你手中飞出一支魔法强酸箭迅速射向目标。你必须做一次成功的远程接触攻击才能击中你的目标。这支箭造成2d4的酸伤害，但并没有溅射伤害。除非被某种方法中和掉，否则每三个施法者等级（18级时达到最大）都会额外持续一轮，并在该轮内造成另外一次2d4点伤害。

材料成分：弄碎的大黄叶和一条蝰蛇的胃囊。
器材：一只飞镖。

Acid Arrow
 Conjuration (Creation) [Acid]
Level: Sor/Wiz 2
Components: V, S, M, F
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Effect: One arrow of acid
Duration: 1 round + 1 round per three levels
Saving Throw: None
Spell Resistance: No

A magical arrow of acid springs from your hand and speeds to its target. You must succeed on a ranged touch attack to hit your target. The arrow deals 2d4 points of acid damage with no splash damage. For every three caster levels (to a maximum of 18th), the acid, unless somehow neutralized, lasts for another round, dealing another 2d4 points of damage in that round.

Material Component: Powdered rhubarb leaf and an adder's stomach.
Focus: A dart.
]]

pwr_acid_fog_d=[[
酸雾术创造出一大团浓烈的汽雾。除了能让生物减速外，这道法术的蒸汽带有强烈的酸性。

从你施法开始算起，在你回合中每轮结束的时候，雾气会对处在其中的所有生物造成每5级1d6点强酸伤害。
]]
--[[
酸雾术（Acid Fog）
 咒法系（创造）[强酸]
等级：术士/法师 6，水 7
法术成分：言语，姿势，材料/法器
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
效果：20英尺半径扩散的雾，20英尺高
持续时间：1轮/每等级
豁免：无
法术抗力：不可

酸雾术创造出一大团浓烈的汽雾，很像重雾术（solid fog）产生的雾气。除了能让生物减速和阻碍其视觉外，这道法术的蒸汽带有强烈的酸性。从你施法开始算起，在你回合中每轮结束的时候，雾气会对处在其中的所有生物和物体造成2d6酸伤害。

奥术材料成分：一撮混合了动物蹄粉末的干豌豆粉。

Acid Fog
 Conjuration (Creation) [Acid]
Level: Sor/Wiz 6, Water 7
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Fog spreads in 20-ft. radius, 20 ft. high
Duration: 1 round/level
Saving Throw: None
Spell Resistance: No

Acid fog creates a billowing mass of misty vapors similar to that produced by a solid fog spell. In addition to slowing creatures down and obscuring sight, this spell's vapors are highly acidic. Each round on your turn, starting when you cast the spell, the fog deals 2d6 points of acid damage to each creature and object within it.

Arcane Material Component: A pinch of dried, powdered peas combined with powdered animal hoof.
]]


pwr_mm_d=[[
一颗以魔法能量构成的飞弹从你的指尖射出并攻击目标，对目标造成每10级1d4+1点力场伤害。

无论目标是否有隐蔽、掩蔽（除非全掩蔽或全隐蔽）或是在近战中，飞弹都会精确命中目标。

1级之后，你的施法者等级每提升2级可多发射一颗飞弹——3级时2颗，5级时3颗，7级时4颗，9级时达到最大值5颗。
]]
--[[
魔法飞弹（Magic Missile）
 塑能系[力场]
等级：术士/法师1
法术成分：言语，姿势
施法时间：1个标准动作
距离：中距（100英尺+10英尺/施法者每等级）
目标：最多可选定5个生物，生物之间的距离不可超过15英尺
持续时间：立即
豁免：无
法术抗力：可

一颗以魔法能量构成的飞弹从你的指尖射出并攻击目标，对目标造成1d4+1点力场伤害。

无论目标是否有隐蔽、掩蔽（除非全掩蔽或全隐蔽）或是在近战中，飞弹都会精确命中目标。你不能指定飞弹攻击生物的特定部位。非活化的物体不会被此法术所伤害。

1级之后，你的施法者等级每提升2级可以多发射一颗飞弹——3级时2颗，5级时3颗，7级时4颗，9级时达到最大值5颗。如果你射出多颗飞弹，你可以决定让所有飞弹攻击同一个目标也可以决定让飞弹射向不同目标，但每颗飞弹只能击中一个生物。你必须在法术抗力掷骰和伤害掷骰前决定目标。

Magic Missile
 Evocation [Force]
Level: Sor/Wiz 1
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Targets: Up to five creatures, no two of which can be more than 15 ft. apart
Duration: Instantaneous
Saving Throw: None
Spell Resistance: Yes

A missile of magical energy darts forth from your fingertip and strikes its target, dealing 1d4+1 points of force damage.

The missile strikes unerringly, even if the target is in melee combat or has less than total cover or total concealment. Specific parts of a creature can't be singled out. Inanimate objects are not damaged by the spell.

For every two caster levels beyond 1st, you gain an additional missile - two at 3rd level, three at 5th, four at 7th, and the maximum of five missiles at 9th level or higher. If you shoot multiple missiles, you can have them strike a single creature or several creatures. A single missile can strike only one creature. You must designate targets before you check for spell resistance or roll damage.
]]


pwr_searing_lit_d=[[
将神力聚焦在一起如同太阳的光束，你从你打开的手掌中放射出一道光的冲击。要击中目标，你必须进行一次成功的远程接触攻击。

被这道光束击中的生物受到每2级1d8点伤害。

不死生物受到每级1d6点伤害，特别畏惧强光的不死生物则受到每级1d8点伤害。

构装体仅受到每2级1d6的伤害。
]]
--[[
灼热光辉（Searing Light）
 塑能系
等级：牧师 3，太阳 3
法术成分：言语，姿势
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
效果：射线
持续时间：立即
豁免：无
法术抗力：可

将神力聚焦在一起如同太阳的光束，你从你打开的手掌中放射出一道光的冲击。要击中目标，你必须进行一次成功的远程接触攻击。被这道光束击中的生物要受到每两个施法者等级1d8的伤害（最多5d8）。不死生物受到每施法者等级1d6的伤害（最多10d6），如果是特别会受到强光伤害的不死生物，它将受到每施法者等级1d8的伤害（最多10d8）。构装体或者非活化物品仅受到每两个施法者等级1d6的伤害（最多5d6）。

Searing Light
 Evocation
Level: Clr 3, Sun 3
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Ray
Duration: Instantaneous
Saving Throw: None
Spell Resistance: Yes

Focusing divine power like a ray of the sun, you project a blast of light from your open palm. You must succeed on a ranged touch attack to strike your target. A creature struck by this ray of light takes 1d8 points of damage per two caster levels (maximum 5d8). An undead creature takes 1d6 points of damage per caster level (maximum 10d6), and an undead creature particularly vulnerable to bright light takes 1d8 points of damage per caster level (maximum 10d8). A construct or inanimate object takes only 1d6 points of damage per two caster levels (maximum 5d6).
]]


pwr_heal_d=[[
用你的手掌接触一个活物并将正能量导入，治疗每级2d8点+每级1点伤害。

正能量还会治愈中毒、流血、疯狂、昏迷等不良状态。

由于不死生物以负能量为能源，因此该法术会对它们造成伤害而非治疗。不死生物可以应用法术抗力来抵抗，也可通过意志豁免检定将伤害减半。
]]

pwr_harm_d=[[
当你的手放在生物身体上时，你引导负能量造成每级1d8+每级1点负能量伤害。

由于不死生物以负能量为能源，因此该法术治疗等量的伤害，而非伤害它们。
]]

pwr_heal2_d=[[
你可以导入正能量来医治疾病和损伤，可医疗每级10点伤害。同时瞬间终结目标所受以下所有不良状态：属性伤害，目盲，困惑，晕眩，目眩，耳聋，疾病，力竭，疲乏，弱智术，精神错乱，反胃，恶心，震慑，以及中毒。

医疗术无法移除负向能级，也无法回复被永久吸取的等级或被永久吸取的属性值。

当作用于不死生物时，其作用如同重伤术。
]]

pwr_harm2_d=[[
重伤术将负能量充入一个目标，造成每级10点伤害。如果该生物成功通过豁免，则只造成一半伤害，且无法让目标的生命降至1以下。

当作用于不死生物时，其作用如同医疗术。
]]

pwr_heal_x_d="类似治疗术，但针对多个目标。"
pwr_harm_x_d="类似伤害术，但针对多个目标。"
pwr_heal2_x_d="类似医疗术，但针对多个目标。"
pwr_harm2_x_d="类似重伤术，但针对多个目标。"
--[[
治疗轻伤（Cure Light Wounds）
 咒法系（医疗）
等级：吟游诗人1，牧师1，德鲁伊1，医疗1，圣武士1，巡林客2
法术成分：言语，姿势
施法时间：一个标准动作
距离：接触
目标：接触到的生物
持续时间：立即
豁免检定：意志，通过则效果减半（无害）；见说明
法术抗力：可（无害）；见说明

用你的手掌接触一个活着的生物并将正能量导入，治疗1d8点伤害，每施法者等级再+1点（最高5点）。

因为不死生物的能源为负能量，这个法术会对它们造成伤害而非治疗。一个不死生物可以应用法术抗力抵抗，也可通过意志豁免检定将伤害减半。

Cure Light Wounds
 Conjuration (Healing)
Level: Brd 1, Clr 1, Drd 1, Healing 1, Pal 1, Rgr 2
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will half (harmless); see text
Spell Resistance: Yes (harmless); see text

When laying your hand upon a living creature, you channel positive energy that cures 1d8 points of damage +1 point per caster level (maximum +5).

Since undead are powered by negative energy, this spell deals damage to them instead of curing their wounds. An undead creature can apply spell resistance, and can attempt a Will save to take half damage.

造成轻伤（Inflict Light Wounds）
 死灵系
等级：牧师 1，破坏 1
法术成分：言语，姿势
施法时间：1个标准动作
距离：接触
目标：接触到的生物
持续时间：立即
豁免：意志，通过则减半
法术抗力：可

当你的手放在生物身体上时，你引导负能量造成1d8+每施法者等级1点（最多+5）伤害。

由于不死生物是用负能量作为能源，因此该法术治疗等量的伤害，而不是伤害它们。

Inflict Light Wounds
 Necromancy
Level: Clr 1, Destruction 1
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will half
Spell Resistance: Yes

When laying your hand upon a creature, you channel negative energy that deals 1d8 points of damage +1 point per caster level (maximum +5).

Since undead are powered by negative energy, this spell cures such a creature of a like amount of damage, rather than harming it.

医疗术（Heal）
 咒法系（医疗）
等级：牧师 6，德鲁伊 7，医疗 6
法术成分：言语，姿势
施法时间：1个标准动作
距离：接触
目标：接触到的生物
持续时间：立即
豁免：意志，通过无效（无害）
法术抗力：可（无害）

你可以导入正能量来医治疾病和损伤。此法术可瞬间终结目标所受的所有以下不良状态：属性伤害（ability damage），目盲（blinded），困惑（confused），晕眩（dazed），目眩（dazzled），耳聋（deafened），疾病（diseased），力竭（exhausted），疲乏（fatigued），弱智术（feebleminded），精神错乱（insanity），反胃（nauseated），恶心（sickened），震慑（stunned），以及中毒（poisoned）。同时医疗每施法者等级10点伤害，最高达到15级150点。

医疗术无法移除负向能级，也无法回复被永久吸取的等级或被永久吸取的属性值。

当作用于不死生物时，其作用如同重伤术（harm）。

Heal
 Conjuration (Healing)
Level: Clr 6, Drd 7, Healing 6
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

Heal enables you to channel positive energy into a creature to wipe away injury and afflictions. It immediately ends any and all of the following adverse conditions affecting the Target: ability damage, blinded, confused, dazed, dazzled, deafened, diseased, exhausted, fatigued, feebleminded, insanity, nauseated, sickened, stunned, and poisoned. It also cures 10 hit points of damage per level of the caster, to a maximum of 150 points at 15th level.

Heal does not remove negative levels, restore permanently drained levels, or restore permanently drained ability score points.

If used against an undead creature, heal instead acts like harm.

重伤术（Harm）
 死灵系
等级：牧师 6,破坏 6
法术成分：言语，姿势
施法时间：1个标准动作
距离：接触
目标：接触到的生物
持续时间：立即
豁免：意志，通过减半; 见下文
法术抗力：可

重伤术将负能量充入一个目标，这会造成每施法者等级10点的伤害（最高可达到15级时的150点）。如果该生物成功通过豁免，则重伤术只会造成一半伤害，但此时该法术无法让目标的生命降至比1更少。

当作用于不死生物时，其作用如同医疗术（heal）。

Harm
 Necromancy
Level: Clr 6, Destruction 6
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will half; see text
Spell Resistance: Yes

Harm charges a subject with negative energy that deals 10 points of damage per caster level (to a maximum of 150 points at 15th level). If the creature successfully saves, harm deals half this amount, but it cannot reduce the target's hit points to less than 1.

If used on an undead creature, harm acts like heal.

群体治疗轻伤（Cure Light Wounds, Mass）
 咒法系（医疗）
等级：吟游诗人5，牧师5，德鲁伊5，医疗5
法术成分：言语，姿势
施法时间：一个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：1个生物/每等级，任意两个生物的间距不超过30英尺
持续时间：立即
豁免检定：意志，通过则效果减半（无害）；见说明
法术抗力：可（无害）；见说明
 你将正能量导入每一个被挑选的生物，治愈他们1d8+1点伤害，每施法者等级再+1点（最高25点）。
 和其他治疗法术一样，群体治疗轻伤会对区域内的不死生物造成正能量伤害而非治疗。每一个受影响的不死生物都可以做一个意志豁免检定来将伤害减半。

Cure Light Wounds, Mass
 Conjuration (Healing)
Level: Brd 5, Clr 5, Drd 6, Healing 5
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature/level, no two of which can be more than 30 ft. apart
Duration: Instantaneous
Saving Throw: Will half (harmless) or Will half; see text
Spell Resistance: Yes (harmless) or Yes; see text
 You channel positive energy to cure 1d8 points of damage +1 point per caster level (maximum +25) in each selected creature.
 Like other cure spells, mass cure light wounds deals damage to undead in its area rather than curing them. Each affected undead may attempt a Will save for half damage.

群体造成轻伤（Inflict Light Wounds, Mass）
 死灵系
等级：牧师 5，破坏 5
法术成分：言语，姿势
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：每等级1个生物，任意两者相距不超过30英尺
持续时间：立即
豁免：意志，通过减半
法术抗力：可
 负能量从目标点开始向各个方向扩散，对附近的活物造成1d8+每施法者等级1点（最多+25）伤害。
 如同其他的造成伤害法术，群体造成轻伤治疗而不是伤害亡灵。能自发施展造成伤害法术的牧师也能自发施展群体造成轻伤。

Inflict Light Wounds, Mass
 Necromancy
Level: Clr 5, Destruction 5
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature/level, no two of which can be more than 30 ft. apart
Duration: Instantaneous
Saving Throw: Will half
Spell Resistance: Yes
 Negative energy spreads out in all directions from the point of origin, dealing 1d8 points of damage +1 point per caster level (maximum +25) to nearby living enemies.
 Like other inflict spells, mass inflict light wounds cures undead in its area rather than damaging them. A cleric capable of spontaneously casting inflict spells can also spontaneously cast mass inflict spells.

