pwr_slay_live_d="你可以杀死任何活物。你必须通过近战接触攻击成功的接触到对方，而对方可以通过强韧豁免来避免死亡。如果对方豁免成功，那么它只会受到每3级1d6+每级1点伤害。"
pwr_dead_finger_d="你能杀死任何距离内的一个活物。目标可以进行一次强韧豁免来避免被杀。如果该豁免成功，该生物将只受到每4级1d6+每级1点伤害。"
pwr_wail_of_the_banshee_d="你发出恐怖的尖叫，闻者皆亡（除了你自己）。"
--[[
杀生术（Slay Living）
 死灵系 [死亡]
等级：牧师 5，死亡 5
法术成分：言语，姿势
施法时间：一个标准动作
距离：接触
目标：被接触的活物
持续时间：立即
豁免：强韧，通过则部分有效
法术抗力：可

你可以杀死任何活物。你必须通过近战接触攻击成功的接触到对方，而对方可以通过强韧豁免来避免死亡。如果对方豁免成功，那么它只会受到3d6+每施法者等级1点伤害。

Slay Living
 Necromancy [Death]
Level: Clr 5, Death 5
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous
Saving Throw: Fortitude partial
Spell Resistance: Yes

You can slay any one living creature. You must succeed on a melee touch attack to touch the subject, and it can avoid death with a successful Fortitude save. If it succeeds, it instead takes 3d6 points of damage +1 point per caster level.

死亡一指（Finger of Death）
 死灵系[死亡]
等级：德鲁伊 8，术士/法师 7
法术成分：言语，姿势
施法时间：一个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个活物
持续时间：立即
豁免：强韧，通过则部分生效
法术抗力：可

你能杀死任何距离内的一个活物。目标可以进行一次强韧豁免来避免被杀。如果该豁免成功，该生物将只受到3d6+1/每施法者等级（最多+25）的伤害。

即便目标豁免成功，它依然有可能因为受到伤害而死亡。

Finger of Death
 Necromancy [Death]
Level: Drd 8, Sor/Wiz 7
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature
Duration: Instantaneous
Saving Throw: Fortitude partial
Spell Resistance: Yes

You can slay any one living creature within range. The target is entitled to a Fortitude saving throw to survive the attack. If the save is successful, the creature instead takes 3d6 points of damage +1 point per caster level (maximum +25).

The subject might die from damage even if it succeeds on its saving throw.

女妖之嚎（Wail of the Banshee）
 死灵系[死亡，音波]
等级：死亡9，术士/法师9
法术成分：言语
施法时间：1个标准动作
距离：近距（25英尺+5英尺/2等级）
区域：40英尺扩散范围内，1个活物/等级
持续时间：立即
豁免：强韧，通过则无效
法术抗力：可

你发出恐怖的尖叫，闻者皆亡（除了你自己）。最接近源发点的生物最先受影响。

Wail of the Banshee
 Necromancy [Death, Sonic]
Level: Death 9, Sor/Wiz 9
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Area: One living creature/level within a 40-ft.-radius spread
Duration: Instantaneous
Saving Throw: Fortitude negates
Spell Resistance: Yes

You emit a terrible scream that kills creatures that hear it (except for yourself ). Creatures closest to the point of origin are affected first.
]]


pwr_false_life_d="控制反生命的力量让你获得能在一定限度内避开死亡的能力。当此法术生效时，你获得每3级1d10+每级1点的暂时生命值。"
pwr_aid_d="援助术给目标的攻击投骰和对抗恐惧效果的豁免上提供+1士气加值，外加每3级1d8+每级1点的暂时生命值。"
pwr_death_knell_d=[[
你吸取生物正在减弱的生命力以补充自己的力量。施展此法术时，你要接触一个剩余1/5或更少生命值的生物。

若该生物豁免检定失败则死亡，同时你可获得每3级1d8点暂时生命值和力量+2加值。

另外，你的有效施法者等级上升1，从而增强与此有关的施法能力。（这不会增加你的可用法术数量。）
]]
--[[
虚假生命（False Life）
 死灵系
等级：术士/法师 2
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：个人
目标：你自己
持续时间：1小时/每等级或直到被耗散掉；见正文

控制反生命的力量让你获得能在一定限度内避开死亡的能力。当此法术起作用时，你获得1d10+1/每施法者等级（最多+10）的暂时生命值。

材料成分：少量酒精或蒸馏烈酒，在施法的时候用它在你身体上画出某些符号。在酒精或烈酒蒸发后，这些符号将变得不可见。

False Life
 Necromancy
Level: Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 hour/level or until discharged; see text

You harness the power of unlife to grant yourself a limited ability to avoid death. While this spell is in effect, you gain temporary hit points equal to 1d10 +1 per caster level (maximum +10).

Material Component: A small amount of alcohol or distilled spirits, which you use to trace certain sigils on your body during casting. These sigils cannot be seen once the alcohol or spirits evaporate.

援助术（Aid）
 惑控系（胁迫）[影响心灵]
等级：牧师 2，善良 2，机运 2
法术成分：言语，姿势，法器
施法时间：一个标准动作
距离：接触
目标：接触的活物
持续时间：1分钟/每等级
豁免：无
法术抗力：可（无害）

援助术给目标的攻击投骰和对抗恐惧效果的豁免上提供+1士气加值，再提供了1d8+施法者等级的暂时生命值（暂时生命值在施法者等级10级时达到最大，为1d8+10）。

Aid
 Enchantment (Compulsion) [Mind-Affecting]
Level: Clr 2, Good 2, Luck 2
Components: V, S, DF
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: 1 min./level
Saving Throw: None
Spell Resistance: Yes (harmless)

Aid grants the target a +1 morale bonus on attack rolls and saves against fear effects, plus temporary hit points equal to 1d8 + caster level (to a maximum of 1d8+10 temporary hit points at caster level 10th).

死亡丧钟（Death Knell）
 死灵系 [死亡、邪恶]
等级：牧师 2，死亡 2
法术成分：言语，姿势
施法时间： 一个标准动作
距离：接触
目标：接触到的活物
持续时间：立即/每目标HD 10分钟；见说明
豁免检定：意志，通过则无效
法术抗力：可

你吸取生物正在减弱的生命力以补充自己的力量。施展此法术时，你要接触一个生命值-1或更少的生物。若该生物豁免检定失败则死亡，同时你可获得1d8点暂时生命值和力量+2加值。另外，你的有效施法者等级也上升1，从而增强与此有关的施法能力。（这不会增加你的可用法术数量。）这些效果可持续受术者的HDx10分钟。

Death Knell
 Necromancy [Death, Evil]
Level: Clr 2, Death 2
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous/10 minutes per HD of subject; see text
Saving Throw: Will negates
Spell Resistance: Yes

You draw forth the ebbing life force of a creature and use it to fuel your own power. Upon casting this spell, you touch a living creature that has -1 or fewer hit points. If the subject fails its saving throw, it dies, and you gain 1d8 temporary hit points and a +2 bonus to Strength. Additionally, your effective caster level goes up by +1, improving spell effects dependent on caster level. (This increase in effective caster level does not grant you access to more spells.) These effects last for 10 minutes per HD of the subject creature.
]]


pwr_power_word_stun_d="别名“真言术：震”。你仅发出一个威力无比的词就能让你选定的一个生物昏迷1d4轮。目标当前生命值须低于150或最大生命值的1/5。"
pwr_power_word_kill_d="别名“真言术：死”。你仅发出一个威力无比的词就能立即杀死你选定的一个活物。目标当前生命值须低于100或最大生命值的1/10。"
--[[
真言术：震（Power Word Stun）
 惑控系（胁迫） [影响心灵]
等级：术士/法师 8， 战争 8
法术成分：言语
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个150或更少生命值的生物
持续时间： 见正文
豁免：无
法术抗力：可

你仅发出一个威力无比的词就能让你选定的一个生物震慑，不管它是否能听见那个词。该法术的持续时间和目标的当前总生命值相关。任何当前具有151或者更多生命值的生物都不受真言术：震影响。

生命值	持续时间
50或更少	4d4轮
51–100	2d4轮
101–150	1d4轮

Power Word Stun
 Enchantment (Compulsion) [Mind-Affecting]
Level: Sor/Wiz 8, War 8
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature with 150 hp or less
Duration: See text
Saving Throw: None
Spell Resistance: Yes

You utter a single word of power that instantly causes one creature of your choice to become stunned, whether the creature can hear the word or not. The duration of the spell depends on the target's current hit point total. Any creature that currently has 151 or more hit points is unaffected by power word stun.

Hit Points	Duration
50 or less	4d4 rounds
51-100		2d4 rounds
101-150		1d4 rounds

真言术：死（Power Word Kill）
 惑控系（胁迫） [死亡，影响心灵]
等级：术士/法师 9， 战争 9
法术成分：言语
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个100或更少生命值的活物
持续时间：立即
豁免：无
法术抗力：可

你仅发出一个威力无比的词就能立即杀死你选定的一个生物，不管它是否能听见那个词。任何当前具有101或者更多生命值的生物都不受真言术：死影响。

Power Word Kill
 Enchantment (Compulsion) [Death, Mind-Affecting]
Level: Sor/Wiz 9, War 9
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature with 100 hp or less
Duration: Instantaneous
Saving Throw: None
Spell Resistance: Yes

You utter a single word of power that instantly kills one creature of your choice, whether the creature can hear the word or not. Any creature that currently has 101 or more hit points is unaffected by power word kill.
]]


pwr_bulls_strength_d="受术者变得更加强壮。力量+4加值。"
pwr_cats_grace_d="受术者变得更加优雅灵活，拥有十分良好的平衡性。敏捷+4加值。"
pwr_bears_endurance_d="受术者获得更强的生命力和耐力。体质+4加值。"
pwr_foxs_cunning_d="受术者变得更聪明。智力+4加值。"
pwr_owls_wisdom_d="受术者变得更睿智。感知+4加值。"
pwr_eagles_splendor_d="受术者变得更自信，健谈、富有人格魅力。魅力+4加值。"
pwr_mass_bulls_strength_d="类似牛之力量，但针对多个目标。"
pwr_mass_cats_grace_d="类似猫之优雅，但针对多个目标。"
pwr_mass_bears_endurance_d="类似熊之坚韧，但针对多个目标。"
pwr_mass_foxs_cunning_d="类似狐之狡黠，但针对多个目标。"
pwr_mass_owls_wisdom_d="类似枭之睿智，但针对多个目标。"
pwr_mass_eagles_splendor_d="类似鹰之威仪，但针对多个目标。"

pwr_true_strike_d="你暂时获得敏锐的洞察力，可以看出下回合攻击的时机。你的下一次攻击检定获得+20洞察加值。"
pwr_divine_favor_d="呼唤神的力量与智慧，你在攻击检定和武器伤害检定上获得每3个施法者等级+1幸运加值（至少+1，最多+3）。\n\n攻击检定包括武器攻击，战技，接触类法术的攻击检定。"-- 法术伤害无加值。	The bonus doesn't apply to spell damage.
pwr_divine_power_d="呼唤你所信仰神祗的威力，为自己注入一股战斗力量和技能。\n\n你的基本攻击加值等同你的角色等级（可能获得额外攻击次数），力量获得+6增强加值，并获得每施法者等级1点暂时生命值。"
--[[
神能（Divine Power）
 塑能系
等级：牧师 4，战争 4
法术成分：言语，姿势, 法器
施法时间： 一个标准动作
距离：个人
目标：自己
持续时间：1 轮/等级

呼唤你所信仰神祗的威力，为自己注入一股战斗力量和技能。你的基本攻击加值变为等于你的人物等级（这也许可使你进行多次攻击），你的力量获得+6的增强加值，并获得每施法者等级1点暂时生命值。

Divine Power
 Evocation
Level: Clr 4, War 4
Components: V, S, DF
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level

Calling upon the divine power of your patron, you imbue yourself with strength and skill in combat. Your base attack bonus becomes equal to your character level (which may give you additional attacks), you gain a +6 enhancement bonus to Strength, and you gain 1 temporary hit point per caster level.
]]
pwr_heroism_d="目标在战斗中拥有无比的勇气与高昂的士气。攻击和豁免检定+2士气加值。"
pwr_greater_heroism_d="类似英雄气概，但加值为+4，同时免疫恐惧，并获得等同于施法者等级的暂时生命值。"
--[[
高等英雄气概（Heroism, Greater）
 惑控系（胁迫） [影响心灵]
等级：吟游诗人 5，术士/法师6
持续时间：1分钟/每等级

此法术如同英雄气概，但生物是在攻击，豁免和技能上获得+4士气加值，同时对恐惧效果免疫，并获得等同于施法者等级的暂时生命值（最多20点）。

Heroism, Greater
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 5, Sor/Wiz 6
Duration: 1 min./level

This spell functions like heroism, except the creature gains a +4 morale bonus on attack rolls, saves, and skill checks, immunity to fear effects, and temporary hit points equal to your caster level (maximum 20).
]]
pwr_shield_of_faith_d="创造一个闪着微光的魔法场环绕着目标，为其挡开敌人的攻击。目标防御等级+2偏斜加值（额外+1/每6施法者等级；最多在18级时获得+5偏斜加值）。"
pwr_shield_d="创造一个隐形、可移动、塔盾般大小的力场碟在你前方盘旋，使你完全无视魔法飞弹的攻击，并且防御等级+4盾牌加值。"
pwr_mage_armor_d="在目标周围创造一层隐形但又确实存在的力场，使其防御等级+4盔甲加值。"
pwr_expeditious_retreat_d="速度+6增强加值。"
pwr_protection_from_spells_d="受术者对抗法术时+8抗性加值。"
pwr_death_ward_d="受术者免疫所有死亡法术、魔法死亡效果、以及任何负能量效果。"

s_fear1d	="移除恐惧"	s_fear1d_u	="对抗恐惧效果时+4士气加值\n消除恐惧状态"	s_fear1d_d	=[[将勇气注入目标心中，使其对抗恐惧效果时获得+4士气加值，持续10分钟。

若受到本法术时目标已在某恐惧效果影响下，则在本法术持续时间内该效果被压制。]]-- z_fear
s_fear1		="惊恐术"	s_fear1_d	=[[目标变为惊惧状态1d4轮；意志豁免成功则仅战栗1轮。]]
s_fear2		="恐吓术"	s_fear2_d	=[[类似惊恐术，但影响多个目标。]]
s_fear4		="恐惧术"	s_fear4_d	=[[一个不可见的恐怖锥形将其范围内所有活物变为恐慌状态1d4轮；意志豁免成功则仅战栗1轮。

被逼到绝路时，恐慌的生物会变成畏缩状态。]]
--[[
移除恐惧（Remove Fear）
防护系
等级：吟游诗人 1， 牧师 1
法术成分：言语，姿势
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个生物加上每四级一个额外生物，任意两者之间不能超过30英尺
持续时间： 10分钟；见正文
豁免：意志通过则无效（无害）
法术抗力：可（无害）
你将勇气注入目标的心中，使之10分钟内对抗恐惧效果时得到+4士气加值。如果受到本法术时目标已在恐惧效果影响下，在本法术的持续时间内那效果都会被压制。
移除恐惧反制并解除惊恐术（cause fear）。
Remove Fear
Abjuration
Level: Brd 1, Clr 1
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: One creature plus one additional creature per four levels, no two of which can be more than 30 ft. apart
Duration: 10 minutes; see text
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
You instill courage in the subject, granting it a +4 morale bonus against fear effects for 10 minutes. If the subject is under the influence of a fear effect when receiving the spell, that effect is suppressed for the duration of the spell.
Remove fear counters and dispels cause fear.

惊恐术（Cause Fear）
死灵系[恐惧，影响心灵]
等级：吟游诗人1，牧师1，死亡1，术士/法师1
法术成分：言语，姿势
施法时间：一个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个HD5或更少的活物
持续时间：1d4轮或1轮，见说明
豁免检定：意志，通过则部分有效
法术抗力：可
受术者变为惊惧状态（frightened）。如果通过意志豁免则战栗（shaken）1轮。HD达到6或更多的生物对此法术免疫。
惊恐术可以反制移除恐惧（remove fear）。
Cause Fear
Necromancy [Fear, Mind-Affecting]
Level: Brd 1, Clr 1, Death 1, Sor/Wiz 1
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature with 5 or fewer HD
Duration: 1d4 rounds or 1 round; see text
Saving Throw: Will partial
Spell Resistance: Yes
The affected creature becomes frightened. If the subject succeeds on a Will save, it is shaken for 1 round. Creatures with 6 or more Hit Dice are immune to this effect.
Cause fear counters and dispels remove fear.

恐吓术（Scare）
死灵系[恐惧，影响心灵]
等级：吟游诗人 2，术士/法师 2
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
目标：每三等级一个活物，任意两者之间距离不得超过30英尺
持续时间：1轮/每等级或1轮；见惊恐术（cause fear）说明
豁免：意志，通过则部分生效
法术抗力：可
该法术作用类似惊恐术（cause fear），只是所有HD少于6的目标生物都会惊惧（frightened）。
材料成分：一点从不死生物骷髅（skeleton）、僵尸（zombie）、食尸鬼（ghoul）、妖鬼（ghast）或木乃伊（mummy）身上取出的骨头。
Scare
Necromancy [Fear, Mind-Affecting]
Level: Brd 2, Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Targets: One living creature per three levels, no two of which can be more than 30 ft. apart
Duration: 1 round/level or 1 round; see text for cause fear
Saving Throw: Will partial
Spell Resistance: Yes
This spell functions like cause fear, except that it causes all targeted creatures of less than 6 HD to become frightened.
Material Component: A bit of bone from an undead skeleton, zombie, ghoul, ghast, or mummy.

恐惧术（Fear）
死灵系[恐惧，影响心灵]
等级：吟游诗人 3，术士/法师 4
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：30英尺
区域：锥形爆发
持续时间：1轮/每等级或1轮；见正文
豁免：意志，通过则部分生效
法术抗力：可
一个不可见的锥形范围恐惧让这个区域内的所有活物都变为恐慌状态，除非他们成功地进行了一次意志豁免。如果被逼到绝路，恐慌的生物会变成畏缩状态。如果意志豁免成功，那么该生物战栗1轮。
材料成分：母鸡心脏或者一片白羽毛。
Fear
Necromancy [Fear, Mind-Affecting]
Level: Brd 3, Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: 30 ft.
Area: Cone-shaped burst
Duration: 1 round/level or 1 round; see text
Saving Throw: Will partial
Spell Resistance: Yes
An invisible cone of terror causes each living creature in the area to become panicked unless it succeeds on a Will save. If cornered, a panicked creature begins cowering. If the Will save succeeds, the creature is shaken for 1 round.
Material Component: Either the heart of a hen or a white feather.
]]

pwr_halt_undead_d="让不死生物无法行动。非智能的不死生物无法作豁免检定；智能的不死生物则可以。当目标被攻击或受到伤害时，定身终止。"
pwr_hold_person_d="目标被麻痹，僵在原地无法做任何动作。\n\n每一轮当其行动时，会自动进行一次豁免检定来尝试终止该效果。"
pwr_hold_monster_d="类似人类定身术，但可用于任何活物。"
pwr_mass_hold_person_d="类似人类定身术，但作用范围更大。"
pwr_mass_hold_monster_d="类似怪物定身术，但作用范围更大。"

pwr_sleep_d="睡眠术会使生物陷入魔法睡眠。睡眠中的生物处于无助状态，受到拍击或伤害时会苏醒，但普通的声响不会唤醒它们。\n\n睡眠术对已昏迷的生物，构装体或不死生物无效。"
--[[
睡眠术（Sleep）
 惑控系 （胁迫）[影响心灵]
等级：吟游诗人 1，术士/法师 1
法术成分：言语，姿势，材料
施法时间：1轮
距离：中距（100英尺+10英尺/每等级）
区域：半径十英尺爆发范围内的数个活物
持续时间： 1分钟/等级
豁免：意志，通过则无效
法术抗力：可
睡眠术会使4HD及以下的生物陷入昏睡。低HD的生物会先受到影响。在HD相同的生物中，靠近法术源起点的生物会先受影响。剩下的HD若不足以影响其它生物则舍去不计。
 睡眠中的生物陷入无助状态。它们会在受到拍击或是受伤时苏醒，但普通的声响不会唤醒它们。唤醒一个生物是标准动作（协助他人的一种应用方式）。
睡眠术对已昏迷的生物，构装体或不死生物无效。
材料成分：一把细沙，玫瑰花瓣，或一只活蟋蟀。

Sleep
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 1, Sor/Wiz 1
Components: V, S, M
Casting Time: 1 round
Range: Medium (100 ft. + 10 ft./level)
Area: One or more living creatures within a 10-ft.-radius burst
Duration: 1 min./level
Saving Throw: Will negates
Spell Resistance: Yes
 A sleep spell causes a magical slumber to come upon 4 Hit Dice of creatures. Creatures with the fewest HD are affected first.
 Among creatures with equal HD, those who are closest to the spell's point of origin are affected first. Hit Dice that are not sufficient to affect a creature are wasted.
 Sleeping creatures are helpless. Slapping or wounding awakens an affected creature, but normal noise does not. Awakening a creature is a standard action (an application of the aid another action).
Sleep does not target unconscious creatures, constructs, or undead creatures.
Material Component: A pinch of fine sand, rose petals, or a live cricket.
]]
pwr_irresistible_dance_d="受术者感受到无法抑制的强烈跳舞欲望并开始摇头晃脑打拍子。\n\n目标除了手舞足蹈外什么都做不了，反射-10，防御等级-4并失去所有盾牌加值，在其每轮回合开始时还会引发借机攻击。"
pwr_grease_d="在指定位置制造一片油腻区域。此区域视作困难地形，且其中的所有生物每回合都需进行一次反射检定，失败则跌倒。\n\n具有火焰伤害的法术可引燃油腻区域。燃烧时，其中的生物会受到2d8点火焰伤害。"
--[[
油腻术（Grease）
 咒法系（创造）
等级：吟游诗人 1, 术士/法师 1
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标或区域：一个物品或一个10英尺边长正方形
持续时间：1轮/每等级（可解消）
豁免：见正文
法术抗力：不可
油腻术能在固体表面上覆盖一层光滑的油脂。施放法书时任何在此区域的生物都必须做一个成功的反射豁免，否则就会跌倒。只要生物继续留在该区域，那么每轮在你的回合时它都要重复一次这种豁免。走进或穿过油脂区域的生物可以通过一次DC 10的平衡检定来以正常速度的一半行走。失败则意味着在该轮没法移动（同时必须进行一次反射豁免否则就会跌倒），失败5或更多则意味着它跌倒了（详见平衡技能说明）。
 该法术还可以用在物品上创造出一层油脂表面。没被使用的非魔法物品必然会被此法术影响，但是正被生物持有或使用的物品可以进行一次反射豁免来避开它。如果这个初始反射失败了，那么该生物将立刻掉掉该物品。尝试拣起或使用被油腻的物品需要每轮进行一次豁免。如果穿着被油腻的盔甲或衣服，那么生物在进行脱逃术检定和擒抱检定来抵抗擒抱或从擒抱中脱身时，或脱离压制时，它都能获得+10环境加值。
材料成分：一小块猪皮或牛油。

Grease
 Conjuration (Creation)
Level: Brd 1, Sor/Wiz 1
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target or Area: One object or a 10-ft. square
Duration: 1 round/level (D)
Saving Throw: See text
Spell Resistance: No
 A grease spell covers a solid surface with a layer of slippery grease. Any creature in the area when the spell is cast must make a successful Reflex save or fall. This save is repeated on your turn each round that the creature remains within the area. A creature can walk within or through the area of grease at half normal speed with a DC 10 Balance check. Failure means it can't move that round (and must then make a Reflex save or fall), while failure by 5 or more means it falls (see the Balance skill for details).
 The spell can also be used to create a greasy coating on an item. Material objects not in use are always affected by this spell, while an object wielded or employed by a creature receives a Reflex saving throw to avoid the effect. If the initial saving throw fails, the creature immediately drops the item. A saving throw must be made in each round that the creature attempts to pick up or use the greased item. A creature wearing greased armor or clothing gains a +10 circumstance bonus on Escape Artist checks and on grapple checks made to resist or escape a grapple or to escape a pin.
Material Component: A bit of pork rind or butter.
]]
pwr_web_d="制造一大片坚韧且粘稠的丝状物。其中的生物每回合都会受到蛛网的纠缠，反射检定失败则禁足1回合。\n\n具有火焰伤害的法术可引燃蛛网区域。燃烧时，其中的生物会受到2d4点火焰伤害。"
--[[
蛛网术（Web）
 咒法系（创造）
等级：术士/法师2
法术成分：言语、姿势、材料
施法时间：1个标准动作
距离：中距（100英尺+10英尺/每等级）
效果：半径20英尺扩散范围内的蜘蛛网
持续时间；10分钟/每等级
豁免：反射，通过则无效；见下文
法术杭力：可
蛛网术可造出一大片多层又坚韧又粘稠的丝状物。这些粘丝会困住其中的生物。它们看起来像蜘蛛网，但远比蜘蛛网更大更粗。这些粘丝必须固定在两个或多个完全相对的固定点上，否则就会因不能完全张开而消失。在蛛网中的生物会被粘丝纠缠住。但攻击蛛网内的生物不会让你也被纠缠住
 法术范围内的任何生物都必须进行反射豁免。如果豁免成功，那么尽管依然是被纠缠状态，但是仍然能够移动，只是移动会因纠缠而变得比往常困难（见后）。如果豁免失败，那么生物被缠住并且不能移动，但可以用一轮的时间挣脱，挣脱需要通过DC20的力量检定或是DC25的脱逃检定。一旦挣脱(不管是因为最初的反射豁免还是后来的力量检定或脱逃检定)，那么生物尽管仍然被纠缠。但可以缓慢地在蛛网内移动。如果要进行移动，那么每轮都要做一次新的力量或脱逃检定。若检定结果超过10，则每超过整5点可以移动5英尺。
 你和对手之间若至少有5英尺蛛网，就会形成掩蔽。若你们之间的蛛网有20英尺以上，则形成完全掩蔽。
蛛网术产生的粘丝是易燃物。一把魔法火焰剑可以轻松切开它。任何火焰可以以5平方英尺每轮的速度将其点燃烧除，蛛网燃烧时，困在其中的生物会受到2d4点火焰伤害。
蛛网术的效果可以利用魔法恒定术（permanency）永久化。被损伤的（而非被摧毁的）永久化蛛网会在10分钟后复原。
材料成分：一点蜘蛛网。

Web
 Conjuration (Creation)
Level: Sor/Wiz 2
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Webs in a 20-ft.-radius spread
Duration: 10 min./level (D)
Saving Throw: Reflex negates; see text
Spell Resistance: No
Web creates a many-layered mass of strong, sticky strands. These strands trap those caught in them. The strands are similar to spider webs but far larger and tougher. These masses must be anchored to two or more solid and diametrically opposed points or else the web collapses upon itself and disappears. Creatures caught within a web become entangled among the gluey fibers. Attacking a creature in a web won't cause you to become entangled.
 Anyone in the effect's area when the spell is cast must make a Reflex save. If this save succeeds, the creature is entangled, but not prevented from moving, though moving is more difficult than normal for being entangled (see below). If the save fails, the creature is entangled and can't move from its space, but can break loose by spending 1 round and making a DC 20 Strength check or a DC 25 Escape Artist check. Once loose (either by making the initial Reflex save or a later Strength check or Escape Artist check), a creature remains entangled, but may move through the web very slowly. Each round devoted to moving allows the creature to make a new Strength check or Escape Artist check. The creature moves 5 feet for each full 5 points by which the check result exceeds 10.
 If you have at least 5 feet of web between you and an opponent, it provides cover. If you have at least 20 feet of web between you, it provides total cover.
 The strands of a web spell are flammable. A magic flaming sword can slash them away as easily as a hand brushes away cobwebs. Any fire can set the webs alight and burn away 5 square feet in 1 round. All creatures within flaming webs take 2d4 points of fire damage from the flames.
Web can be made permanent with a permanency spell. A permanent web that is damaged (but not destroyed) regrows in 10 minutes.
Material Component: A bit of spider web.
]]
pwr_sum_d="召唤一只随机元素生物。它会立即开始自动攻击你的敌人，直到战斗结束或被摧毁。同一时刻你只能维持1只元素生物的存在。\n\n召唤者的魅力调整值会应用于召唤物的3项体能属性。"
pwr_mk_ud_d="将范围内死亡生物的骨骼或尸体转化为骷髅或僵尸。它们会立即开始自动攻击你的敌人，直到战斗结束或被摧毁。同一时刻你最多只能维持2只不死生物的存在。\n\n召唤者的魅力调整值会应用于召唤物的3项体能属性。"
pwr_dispel_d="解除指定区域内，所有由法术产生的的效果，区域和生物。如队友的睡眠状态，蛛网术区域和各种召唤生物等。"
pwr_resurrect_d="使一个已经死亡的生命体起死回生。非生命体，如亡灵生物，构装生物和元素生物无法用此法术复活。"
pwr_teleport_d="将自身传送至指定位置；或将某目标传送至目标附近的随机位置。"




pwr_disintegrate_d=[[
一道细细的绿色射线从你指尖射出。你必须通过远程接触攻击来命中目标。被击中的生物受到每级2d6点伤害。强韧检定成功则只受每2级1d6点伤害。生命值被此射线降到0或更低则立即被完全分解，只留下一点微细的灰烬痕迹。被解离的生物的装备不受影响。
]]
--[[
解离术（Disintegrate）
 变化系
等级：毁灭 7，术士/法师 6
法术成分：言语，姿势，材料/法器
施法时间： 一个标准动作
距离：中距 （100英尺+10英尺/等级）
效果：射线
持续时间：立即
豁免检定：强韧，通过则效果减半（物体）
法术抗力：可
一道细细的绿色射线从你指尖射出。你必须通过远程接触攻击来命中目标。被击中的生物受到每施法者等级2d6点伤害（最多40d6）。生命值被此射线降到0或更低则立即被完全分解，只留下一点微细的灰烬痕迹。被解离的生物的装备不受影响。
目标为物品时，射线可解离10立方英尺的非生命物品。因此，此法术只能解离庞大物体或结构的一部分。此法术甚至对完全由力场构成的物体也有效，如飞击掌（forceful hand）或力场墙（wall of force），但对法术无效结界（globe of invulnerability）或反魔场（antimagic field）之类的法术效果无效。
 通过强韧检定的生物或物体只受到5d6点伤害。若它们的生命值因此降到0或更低则立即被完全分解。
 只有第一个被击中的生物或物品会被影响，这就是说，每次施法，射线只对一个目标有效。
奥术材料成分 ：一块天然磁石和一小撮灰尘。

Disintegrate
 Transmutation
Level: Destruction 7, Sor/Wiz 6
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Ray
Duration: Instantaneous
Saving Throw: Fortitude partial (object)
Spell Resistance: Yes
A thin, green ray springs from your pointing finger. You must make a successful ranged touch attack to hit. Any creature struck by the ray takes 2d6 points of damage per caster level (to a maximum of 40d6). Any creature reduced to 0 or fewer hit points by this spell is entirely disintegrated, leaving behind only a trace of fine dust. A disintegrated creature's equipment is unaffected.
When used against an object, the ray simply disintegrates as much as one 10- foot cube of nonliving matter. Thus, the spell disintegrates only part of any very large object or structure targeted. The ray affects even objects constructed entirely of force, such as forceful hand or a wall of force, but not magical effects such as a globe of invulnerability or an antimagic field.
A creature or object that makes a successful Fortitude save is partially affected, taking only 5d6 points of damage. If this damage reduces the creature or object to 0 or fewer hit points, it is entirely disintegrated.
Only the first creature or object struck can be affected; that is, the ray affects only one target per casting.
Arcane Material Component: A lodestone and a pinch of dust.
]]

pwr_mislead_d=[[
]]
--[[
假象术（Mislead）
 幻术系（虚假幻觉，五官幻觉）
等级：吟游诗人5，机运6，术士/法师6，诡术6
法术成分：姿势
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
 目标/效果：自己/一个幻象分身
持续时间：1轮/施法者每等级（可解消）和专注+3轮；见说明
豁免：无；或意志，通过则不相信（若发生互动）；见说明
法术抗力：无
 你变为隐形（同高等隐形术（Greater Invisibility），为五官幻觉），同时出现一个跟你一样的幻影（同强效幻影（major image），为虚假幻觉）。之后你和你的分身可以分开移动。分身会出现在法术有效范围内，并往你指定的方向移动（需要在施法后的第一轮开始保持专注。你也可以使幻象分身在出现时完美地叠合在你的身体上，使敌人无法察觉分身出现而你已经隐形，然后你和分身接下来可以往不同方向移动。分身的移动速度和你一样，它的说话方式和动作非常自然，跟真的一样。分身不能攻击或施法，但它可以做出类似的假动作。
 幻象分身的持续时间是专注+3轮。当你结束专注后，幻象分身将继续进行与之前相同的动作直到其持续时间结束。高级隐形术效果的持续时间则是每等级1轮，而不会受到专注的影响。

Mislead
 Illusion (Figment, Glamer)
Level: Brd 5, Luck 6, Sor/Wiz 6, Trickery 6
Components: S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target/Effect: You/one illusory double
Duration: 1 round/level (D) and concentration + 3 rounds; see text
Saving Throw: None or Will disbelief (if interacted with); see text
Spell Resistance: No
 You become invisible (as improved invisibility, a glamer), and at the same time, an illusory double of you (as major image, a figment) appears. You are then free to go elsewhere while your double moves away. The double appears within range but thereafter moves as you direct it (which requires concentration beginning on the first round after the casting). You can make the figment appear superimposed perfectly over your own body so that observers don't notice an image appearing and you turning invisible. You and the figment can then move in different directions. The double moves at your speed and can talk and gesture as if it were real, but it cannot attack or cast spells, though it can pretend to do so.
 The illusory double lasts as long as you concentrate upon it, plus 3 additional rounds. After you cease concentration, the illusory double continues to carry out the same activity until the duration expires. The improved invisibility lasts for 1 round per level, regardless of concentration.
]]

pwr_eyebite_d=[[
你能以一个移动动作瞄准目标，然后用邪恶力量波攻击它。
]]
--[[
摄心目光（Eyebite）
死灵系 [邪恶]
等级：吟游诗人 6, 术士/法师 6
法术成分：言语，姿势
施法时间： 一个标准动作
距离：近距（25英尺+5英尺/2等级）
目标：一个活物
持续时间：每三等级一轮；见说明
豁免检定：强韧，通过则无效
法术抗力：可
每一轮，你都可以选择一个目标，用邪恶力量波攻击它。根据受术者的HD，此法术产生以下三种效果。
HD	效果
10或更多	恶心
5–9	恐慌，恶心
4 或更低	沉睡，恐慌，恶心
效果可累加，并同时发生。
恶心（Sickened）：目标遭到突如起来的痛苦及热病。恶心状态的生物在攻击，伤害，豁免，技能及属性检定上承受-2的减值。此效果持续10分钟/施法者等级。移除疾病（remove disease）和医疗术（heal）无法去除此效果，但移除诅咒（remove curse）可以。
恐慌（Panicked）：目标陷入恐慌状态1d4轮。即便恐慌结束，目标依然会处于战栗（shaken）状态，持续时间为每施法者等级10分钟，如果在此期间它又进入你的视线范围，它会重新陷入恐慌。这属于恐惧效果。
沉睡（Comatose）：目标陷入僵硬的病态沉眠，持续10分钟/施法者等级。在此期间，生物无法以任何不足以解除此魔法的方式叫醒。这并非是睡眠效果，因此精灵不能免疫它。
此法术可持续每3施法者等级1轮，第一轮后每轮你必须以一个移动动作来瞄准目标。

Eyebite
Necromancy [Evil]
Level: Brd 6, Sor/Wiz 6
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature
Duration: 1 round per three levels; see text
Saving Throw: Fortitude negates
Spell Resistance: Yes
Each round, you may target a single living creature, striking it with waves of evil power. Depending on the target's HD, this attack has as many as three effects.
HD	Effect
10 or more	Sickened
5-9	Panicked, sickened
4 or less	Comatose, panicked, sickened
The effects are cumulative and concurrent.
Sickened: Sudden pain and fever sweeps over the subject's body. A sickened creature takes a -2 penalty on attack rolls, weapon damage rolls, saving throws, skill checks, and ability checks. A creature affected by this spell remains sickened for 10 minutes per caster level. The effects cannot be negated by a remove disease or heal spell, but a remove curse is effective.
Panicked: The subject becomes panicked for 1d4 rounds. Even after the panic ends, the creature remains shaken for 10 minutes per caster level, and it automatically becomes panicked again if it comes within sight of you during that time. This is a fear effect.
Comatose: The subject falls into a catatonic coma for 10 minutes per caster level. During this time, it cannot be awakened by any means short of dispelling the effect. This is not a sleep effect, and thus elves are not immune to it.
The spell lasts for 1 round per three caster levels. You must spend a move action each round after the first to target a foe.
]]

pwr_flesh_to_stone_d=[[
受术者及其所有携带的装备都被转变为没有心智，完全静止的雕像。

如果这座被法术制造的雕像被打坏或受损，受术者（如果它转化回之前的状态）也会受到类似的伤害或缺损。

只有有肉的生物才会被此法术影响。
]]
--[[
石化术（Flesh to Stone）
 变化系
等级：术士/法师 6
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
目标：一个生物
持续时间：立即
豁免：强韧，通过则无效
法术抗力：可

受术者及其所有携带的装备都被转变为没有心智，完全静止的雕像。如果这座被法术制造的雕像被打坏或受损，受术者（如果它转化回之前的状态）也会受到类似的伤害或缺损。当用观命术（deathwatch）这类法术察看时，该生物并不算死，但是也不算活。

只有有肉的生物才会被此法术影响。

材料成分：石灰，水，泥土。

Flesh to Stone
 Transmutation
Level: Sor/Wiz 6
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One creature
Duration: Instantaneous
Saving Throw: Fortitude negates
Spell Resistance: Yes

The subject, along with all its carried gear, turns into a mindless, inert statue. If the statue resulting from this spell is broken or damaged, the subject (if ever returned to its original state) has similar damage or deformities. The creature is not dead, but it does not seem to be alive either when viewed with spells such as deathwatch.

Only creatures made of flesh are affected by this spell.

Material Component: Lime, water, and earth.
]]

pwr_stone_to_flesh_d=[[
此法术可使一个被石化的生物恢复原状，但其必须通过一个DC15的强韧豁免才能在此过程中存活。
]]
--[[
解除石化（Stone to Flesh）
 变化系
等级：术士/法师 6
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
目标：1个遭石化的生物，或者一个直径1至3英尺，最高10英尺的石柱
持续时间：立即
豁免：强韧，通过则无效（物体）；见正文
法术抗力：可

此法术可使一个遭石化的生物恢复原状，包括生命和它携带的物品。生物必须通过DC 15的强韧豁免才能在此过程中存活。任何体型的石化生物都可以被复原。

此法术也能将石头转化成肉体。这样的肉体并没有生命，除非被赋予生命或魔法能量。（比如，石魔像可由此变为肉魔像，但一般的石像只能变成尸体。）你可以影响的目标必须可以放在一个直径1至3英尺，高10英尺的柱形区域内，也可以对更大的的石块中符合上述限制的部分施法。

材料成分：一撮泥土和一滴血。

Stone to Flesh
 Transmutation
Level: Sor/Wiz 6
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One petrified creature or a cylinder of stone from 1 ft. to 3 ft. in diameter and up to 10 ft. long
Duration: Instantaneous
Saving Throw: Fortitude negates (object); see text
Spell Resistance: Yes

This spell restores a petrified creature to its normal state, restoring life and goods. The creature must make a DC 15 Fortitude save to survive the process. Any petrified creature, regardless of size, can be restored.

The spell also can convert a mass of stone into a fleshy substance. Such flesh is inert and lacking a vital life force unless a life force or magical energy is available. (For example, this spell would turn a stone golem into a flesh golem, but an ordinary statue would become a corpse.) You can affect an object that fits within a cylinder from 1 foot to 3 feet in diameter and up to 10 feet long or a cylinder of up to those dimensions in a larger mass of stone.

Material Component: A pinch of earth and a drop of blood.
]]

pwr_transformation_d=[[
你变成一个纯粹的战斗机器 —— 更强，更狠，更快，更精于战斗。你的思维完全转换为战斗型，享受战斗但无法施法。

你获得：
- 你的基本攻击加值等同你的角色等级（可能获得额外攻击次数）。
- 力量，敏捷，体质+4增强加值。
- 防御等级+4天生防御加值。
- 强韧+5能力加值。
- 擅长所有简易和军用武器。

但你失去施法能力。
]]
--[[
转变术（Transformation）
 变化系
等级：术士/法师6
法术成分：言语，姿势，材料
施法时间：1个标准动作
距离：个人
目标：自己
持续时间：1轮/等级

你变成一个纯粹的战斗机器——更强，更狠，更快，更精于战斗。你的思维完全转型成为战斗类型，所以你无法施法，甚至不能使用魔法物品。

你的力量，敏捷，体质获得+4的增强加值，AC获得+4的天生防御加值，强韧检定获得+5能力加值，并且擅长所有简易和军用武器。你的基本攻击加值为你的人物等级（这也许会使你可以进行多次攻击）。

你将失去施法能力，包括需要利用法术启动或完成的魔法物品，就好像你的职业能力里不再有那些法术。

材料成分：一瓶牛之力量药水，你必须喝掉它（它的效果包含在上文所述的法术效果中）。

Transformation
 Transmutation
Level: Sor/Wiz 6
Components: V, S, M
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level

You become a virtual fighting machine - stronger, tougher, faster, and more skilled in combat. Your mind-set changes so that you relish combat and you can't cast spells, even from magic items.

You gain a +4 enhancement bonus to Strength, Dexterity, and Constitution, a +4 natural armor bonus to AC, a +5 competence bonus on Fortitude saves, and proficiency with all simple and martial weapons. Your base attack bonus equals your character level (which may give you multiple attacks).

You lose your spellcasting ability, including your ability to use spell activation or spell completion magic items, just as if the spells were no longer on your class list.

Material Component: A potion of bull's strength, which you drink (and whose effects are subsumed by the spell effects).
]]

pwr_iron_body_d=[[
此法术使你变成有生命的钢铁，从而具有多种强大的抵抗与防御能力。

你获得：
- 每级1/精金的伤害减免。
- 免疫重击、电、毒、属性伤害、震慑、目盲、耳聋、疾病，以及所有影响生理机能和呼吸方面的效果。
- 所受强酸和火焰伤害减半。
- 力量+6增强加值，敏捷-6减值（最低1）。
- 徒手攻击视为武装攻击，伤害为1d6（小体型1d4）。

同时遭受下列效果：
- 速度减半。
- 50%奥术失败率，-8防具检定减值。
- 影响铁魔像的特殊攻击也影响你。
- 不能饮用药剂。
]]
--[[
钢筋铁骨（Iron Body）
变化系
等级：土 8，术士/法师 8
法术成分：言语，姿势，材料/法器
施法时间：1个标准动作
距离：个人
目标：自身
持续时间：1分钟/每等级（可解消）

此法术使你变成有生命的钢铁，从而具有多种强大的抵抗与防御能力。

你获得15/精金的伤害减免。你对目盲、重击、属性伤害、耳聋、疾病、溺水、电、毒、震慑免疫，同时免疫所有影响生理机能及呼吸方面的法术，因为在法术影响期间你已完全没有生理反应和呼吸。你对任意种类的酸和火只受一半伤害。但所有那些能影响铁魔像的特殊攻击也能对你造成伤害。

你在力量上获得+6增强加值，但在敏捷上承受-6减值（最低到1），并且速度减半。你的奥术失败率达到50%并有-8的防具检定减值，就如同身穿全身甲。你不能饮水（因此不能使用药剂）或演奏吹奏乐器。

你的徒手攻击看作武装攻击，伤害如同和你体型对应的木棒（小体形1d4，中体形1d6）。

你的体重增加10倍，这使你在水中如石头般下沉。但你能承受水底的高压和无空气状态——至少在法术持续时间内。

奥术材料：一小块铁块，必须曾是铁魔像、英雄盔甲或是战争机器的一部分。


Iron Body
Transmutation
Level: Earth 8, Sor/Wiz 8
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 min./level (D)

This spell transforms your body into living iron, which grants you several powerful resistances and abilities.

You gain damage reduction 15/adamantine. You are immune to blindness, critical hits, ability score damage, deafness, disease, drowning, electricity, poison, stunning, and all spells or attacks that affect your physiology or respiration, because you have no physiology or respiration while this spell is in effect. You take only half damage from acid and fire of all kinds. However, you also become vulnerable to all special attacks that affect iron golems.

You gain a +6 enhancement bonus to your Strength score, but you take a -6 penalty to Dexterity as well (to a minimum Dexterity score of 1), and your speed is reduced to half normal. You have an arcane spell failure chance of 50% and a -8 armor check penalty, just as if you were clad in full plate armor. You cannot drink (and thus can't use potions) or play wind instruments.

Your unarmed attacks deal damage equal to a club sized for you (1d4 for Small characters or 1d6 for Medium characters), and you are considered armed when making unarmed attacks.

Your weight increases by a factor of ten, causing you to sink in water like a stone. However, you could survive the crushing pressure and lack of air at the bottom of the ocean - at least until the spell duration expires.

Arcane Material Component: A small piece of iron that was once part of either an iron golem, a hero's armor, or a war machine.
]]

pwr_spell_turning_d=[[
以你为目标的法术或类法术能力会弹回施法者身上。对远程接触类法术无效。

可反转总法术等级为7~10，具体数值未知。若剩余数值比目标法术等级低，则按比例反转。

若你和施法攻击者都受此效果的保护，则会产生共鸣场，结果投百分骰决定：
01–70	法术衰竭失效。
71–80	法术对双方均造成全效。
81–97	双方的法术反转均无效1d4分钟。
98–100	双方被抛入另一位面的裂缝中。
]]
--[[
法术反转（Spell Turning）
防护系
等级：机运 7，魔法 7，术士/法师 7
法术成分：言语，姿势，材料/法器
施法时间：一个标准动作
距离：个人
目标：自己
持续时间：直到耗尽或10分钟/等级
以你为目标的法术或类法术能力会弹回施法者身上。反转效果仅对以你为目标的法术有效。效果型和区域法术不受影响，对远程接触类法术亦无效。
可反转的法术等级为7到10（1d4+6）。具体数值由暗投决定。
若剩余反转等级比受到的目标法术的等级低，则该法术只能部分反转。
此时，以该法术等级与剩余反转等级的差为分子，以该法术等级为分母，所得的结果即为该法术生效与被反转的比率。若为伤害性法术，则按此比率受到伤害；若为非伤害性法术，你们受到影响的几率也依此计算。
若你和施法攻击者都受法术反转的保护，则会产生共鸣场，结果要投百分骰决定。
d%	效果
01–70	法术衰竭，无任何效果
71–80	法术完全生效，且对双方造成同样效果
81–97	法术的反转均无效1d4分钟
98–100	双方被抛入另一位面的裂缝中
奥术材料成分：一面小银镜。

Spells and spell-like effects targeted on you are turned back upon the original caster. This effect is ineffective for touch range spells.\n\n7~10 spell levels are affected by the turning. The exact amount is unknown.\n\nWhen you are targeted by a spell of higher level than the amount of spell turning you have left, that spell is proportionally turned.\n\nIf you and a spellcasting attacker are both warded by spell turning effects in operation, a resonating field is created. Roll randomly to determine the result.\n01-70	Spell drains away without effect.\n71-80	Spell affects both of you equally at full effect.\n81-97	Both turning effects are rendered nonfunctional for 1d4 minutes.\n98-100	Both of you go through a rift into another plane.

Spell Turning
Abjuration
Level: Luck 7, Magic 7, Sor/Wiz 7
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: Until expended or 10 min./level
Spells and spell-like effects targeted on you are turned back upon the original caster. The abjuration turns only spells that have you as a target. Effect and area spells are not affected. Spell turning also fails to stop touch range spells. 
From seven to ten (1d4+6) spell levels are affected by the turning. The exact number is rolled secretly.
When you are targeted by a spell of higher level than the amount of spell turning you have left, that spell is partially turned. The subtract the amount of spell turning left from the spell level of the incoming spell, then divide the result by the spell level of the incoming spell to see what fraction of the effect gets through. For damaging spells, you and the caster each take a fraction of the damage. For nondamaging spells, each of you has a proportional chance to be affected.
If you and a spellcasting attacker are both warded by spell turning effects in operation, a resonating field is created.
Roll randomly to determine the result.
d%	Effect
01-70	Spell drains away without effect.
71-80	Spell affects both of you equally at full effect.
81-97	Both turning effects are rendered nonfunctional for 1d4 minutes.
98-100	Both of you go through a rift into another plane.
Arcane Material Component: A small silver mirror.
]]

pwr_insanity_d=[[
]]
