pwr_ethereal_jaunt_d=[[
你进入以太位面，化成灵体。

此效果持续期间，你身处以太位面，一个与正常主物质位面重叠共存的世界。效果结束时，你将返回主物质位面，变回实体。

对于主物质位面而言，灵体不可见也摸不到。而它可看见和听见主物质位面，但一切看上去都是灰色的模糊的。它在主物质位面的视觉与听觉范围为60英尺。

一般而言，灵体生物和实体生物无法攻击对方。而灵体生物或物品之间则如同均为实体。

另外，作为没有实体的生物，灵体可以穿越主物质位面的固体，包括活物。若效果结束时它仍在固体中（如墙体），则会被挤到最近的空地，每经过5英尺遭受1d6点伤害。
]]
--[[
幻化灵体（Ethereal Jaunt）
 变化系
等级：牧师 7，术士/法师 7
法术成分：言语，姿势
施法时间： 一个标准动作
距离：个人
目标：自己
持续时间：1 轮/等级（可解消）
 你和你的装备一起变成灵体。在法术持续时间内，你将身处灵界位面，这是一个与正常物质位面重叠的世界。一旦法术结束，你将变回实体。
 灵体生物是不可见也摸不到的，同时可以向任意方向移动，包括上下，但速度减半。作为没有实体的生物，你可以穿越固体，包括活物。灵体生物可看见和听见主物质位面，但一切看上去都是灰色的模糊的，在主物质位面的视觉与听觉范围为60英尺。
 力场效果和防护系法术对灵体有正常效果。这些效果可由物质位面延伸至以太位面，但反过来不是如此。灵体不能攻击实体生物，施展的法术也只能影响其他灵体。某些实体生物的攻击或效果却可影响灵体。
 灵体生物或物品彼此视为正常物体。
 若法术解除时，你在固体物中（如固体墙），则会从最近的开口处挤出，每经过5英尺受到1d6点伤害。


对于主物质位面而言，灵体生物不可见也摸不到。而灵体生物可看见和听见主物质位面，但一切看上去都是灰色的模糊的。灵体生物在主物质位面的视觉与听觉范围为60英尺。

一般而言，灵体生物和实体生物无法攻击对方。而灵体生物或物品之间则如同均为实体。

另外，作为没有实体的生物，你可以穿越主物质位面的固体，包括活物。若法术解除时，你在固体物中（如固体墙），则会从最近的开口处挤出，每经过5英尺受到1d6点伤害。

力场效果和防护系法术对灵体有正常效果。这些效果可由物质位面延伸至以太位面，但反过来不是如此。

以太位面与主物质位面（经常还有其他位面）共存。从以太位面可以看到主物质位面，但它的影像看起来微弱而不清晰，颜色互相混杂，而物体的边界也会模糊失真。

虽然从以太位面可以看到主物质位面的情形，但对于主物质位面而言，以太位面通常是不可见的。一般来说，以太位面的生物无法攻击主物质位面的生物，反之亦然。对于主物质位面者而言，以太位面的旅行者是不可见的，无实体的，绝对静默的。

An ethereal creature is invisible and insubstantial. However, an ethereal creature can see and hear on the Material Plane, but everything looks gray and ephemeral. Sight and hearing onto the Material Plane are limited to 60 feet.

Normally, ethereal creatures and material creatures can't attack each other. Treat other ethereal creatures and ethereal objects as if they were material.

As an insubstantial creature, you can move through solid objects, including living creatures. If you end the spell and become material while inside a material object (such as a solid wall), you are shunted off to the nearest open space and take 1d6 points of damage per 5 feet that you so travel.

Force effects and abjurations affect an ethereal creature normally. Their effects extend onto the Ethereal Plane from the Material Plane, but not vice versa.

THE ETHEREAL PLANE
The Ethereal Plane is coexistent with the Material Plane and often other planes as well. The Material Plane itself is visible from the Ethereal Plane, but it appears muted and indistinct, its colors blurring into each other and its edges turning fuzzy.

While it is possible to see into the Material Plane from the Ethereal Plane, the Ethereal Plane is usually invisible to those on the Material Plane. Normally, creatures on the Ethereal Plane cannot attack creatures on the Material Plane, and vice versa. A traveler on the Ethereal Plane is invisible, incorporeal, and utterly silent to someone on the Material Plane.


Ethereal Jaunt
 Transmutation
Level: Clr 7, Sor/Wiz 7
Components: V, S
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level (D)
 You become ethereal, along with your equipment. For the duration of the spell, you are in a place called the Ethereal Plane, which overlaps the normal, physical, Material Plane. When the spell expires, you return to material existence.
 An ethereal creature is invisible, insubstantial, and capable of moving in any direction, even up or down, albeit at half normal speed. As an insubstantial creature, you can move through solid objects, including living creatures. An ethereal creature can see and hear on the Material Plane, but everything looks gray and ephemeral. Sight and hearing onto the Material Plane are limited to 60 feet.
 Force effects and abjurations affect an ethereal creature normally. Their effects extend onto the Ethereal Plane from the Material Plane, but not vice versa. An ethereal creature can't attack material creatures, and spells you cast while ethereal affect only other ethereal things. Certain material creatures or objects have attacks or effects that work on the Ethereal Plane.
 Treat other ethereal creatures and ethereal objects as if they were material. 
 If you end the spell and become material while inside a material object (such as a solid wall), you are shunted off to the nearest open space and take 1d6 points of damage per 5 feet that you so travel.
]]

pwr_etherealness_d=[[
类似幻化灵体，不过你可与其他自愿生物手牵手，连同他们的装备一起变成灵体。不算自己，施法者每3施法者等级可多带一个生物进入以太位面。一旦成为灵体，就无需再保持接触。
]]
--[[
 同游灵界（Etherealness）
 变化系
等级：牧师 9，术士/法师 9
距离：接触；见说明
目标：自己，以及每三级可多带一个被接触的生物
持续时间：1 分钟/等级（可解消）
法术抗力：可
和幻化灵体一样，不过你可与其他自愿生物手牵手，连同他们的装备一起变成灵体。不算自己，施法者每3施法者等级可多带一个生物进入以太位面。一旦成为灵体，就无需再保持接触。
一旦持续时间终止，所有生物都会变回实体。

Etherealness
 Transmutation
Level: Clr 9, Sor/Wiz 9
Range: Touch; see text
Targets: You and one other touched creature per three levels
Duration: 1 min./level (D)
Spell Resistance: Yes
This spell functions like ethereal jaunt, except that you and other willing creatures joined by linked hands (along with their equipment) become ethereal. Besides yourself, you can bring one creature per three caster levels to the Ethereal Plane. Once ethereal, the subjects need not stay together.
When the spell expires, all affected creatures on the Ethereal Plane return to material existence.
]]

pwr_mind_blank_d=[[
此法术能保护受术者，使其免疫所有影响心灵的魔法和效果。
]]
--[[
心灵屏障（Mind Blank）
 防护系
等级：保护8，术士/法师8
法术成分：言语，姿势
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个生物
持续时间：24小时
豁免：意志，通过则无效（无害）
法术抗力：（无害）

此法术能保护受术者，使得所有能侦测、影响、感知思想或情绪的魔法或有相同功能的装置，都无法对受术者发生作用。此法术不仅能阻绝所有影响心灵的魔法和效果，也能防止预言系法术或预言系效果的侦测。甚至如果用有限祈愿术（limited wish），神迹术（miracle）和祈愿术（wish）来影响心灵或侦测信息，心灵屏障也可以使其失效。若受术者处在大范围探知法术（如秘法眼（arcane eye））的影响区域中，虽然该探知法术仍然会起作用，但却无法侦测到心灵屏障的受术者。如果是针对受术者而来的探知法术，则完全不会有效。

Mind Blank
 Abjuration
Level: Protection 8, Sor/Wiz 8
Components: V, S
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature
Duration: 24 hours
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

The subject is protected from all devices and spells that detect, influence, or read emotions or thoughts. This spell protects against all mind-affecting spells and effects as well as information gathering by divination spells or effects. Mind blank even foils limited wish, miracle, and wish spells when they are used in such a way as to affect the subject's mind or to gain information about it. In the case of scrying that scans an area the creature is in, such as arcane eye, the spell works but the creature simply isn't detected. Scrying attempts that are targeted specifically at the subject do not work at all.
]]

pwr_time_stop_d=[[
这个法术看上去像是让除你之外所有人的时间都静止了。事实上是你的速度变得非常快，使得其他生物看起来像是僵住，尽管实际上他们在正常行动。

你可以在1d4+1轮（以你的观点）内自由行动：

- 现有的区域效果仍会伤害或影响到你。
- 其他生物不会因你的攻击或法术而受伤；你不能以它们为攻击或法术的目标。

大多数施法者利用这些额外的时间来加强防御，召唤盟友，或逃离战斗。
]]
--[[
时间静止（Time Stop）
 变化系
等级：术士/法师9，诡术9
法术成分：言语
施法时间：1个标准动作
距离：个人
目标：自己
持续时间：1d4+1轮（表面时间）

这个法术看上去像是让除了你以外的其他人都进入时间静止状态。但事实上是你的速度变得非常快，使得其他生物看起来完全静止，尽管他们实际上依然可以正常运动。你可以在1d4+1轮（以你的观点）内自由行动。普通或是魔法火焰、寒冷、毒气等依然会伤害你。时间静止作用期间，其他生物不会因你的攻击或法术而受伤，你不能以那些生物为物理攻击或法术的目标。区域法术持续时间若比时间静止剩下的时间长，则可在时间静止结束后继续生效。大多数施法者利用这些额外的时间来加强防御、召唤盟友，或者逃离战斗。

若物品被其他生物所持有、携带或穿着，则你不能移动或伤害它们，但你可以影响无主物品。

在时间静止的持续时间内，你不可被侦测。在时间静止的效果下你不能进入被反魔场（antimagic field）保护的区域。

Time Stop
 Transmutation
Level: Sor/Wiz 9, Trickery 9
Components: V
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1d4+1 rounds (apparent time); see text

This spell seems to make time cease to flow for everyone but you. In fact, you speed up so greatly that all other creatures seem frozen, though they are actually still moving at their normal speeds. You are free to act for 1d4+1 rounds of apparent time. Normal and magical fire, cold, gas, and the like can still harm you. While the time stop is in effect, other creatures are invulnerable to your attacks and spells; you cannot target such creatures with any attack or spell. A spell that affects an area and has a duration longer than the remaining duration of the time stop have their normal effects on other creatures once the time stop ends. Most spellcasters use the additional time to improve their defenses, summon allies, or flee from combat.

You cannot move or harm items held, carried, or worn by a creature stuck in normal time, but you can affect any item that is not in another creature's possession.

You are undetectable while time stop lasts. You cannot enter an area protected by an antimagic field while under the effect of time stop.
]]

pwr_interposing_hand_d=[[
]]
--[[
护身掌（Interposing Hand）
 塑能系 [力场]
等级：术士/法师 5
法术成分：言语，姿势，器材
施法时间：1个标准动作
距离：中距（100英尺+10英尺/每等级）
效果：10英尺大小的手
持续时间：1轮/每等级（可解消）
豁免：无
法术抗力：可
护身掌能够在你和一个敌人之间创造一只大型魔法手。无论你如何改变位置，也不管你的敌人如何尝试绕过去，这只飘浮的无实体的手也会移动以确保始终处在在你们两者之间，并为你在对抗这个敌人时提供遮掩（+4AC）。没有什么能欺骗这只手，不论黑暗、隐形、变形或是任何隐藏或易容，它会一直跟随着选定的敌人。但它也不会攻击敌人。
护身掌大约长10英尺，五指张开时也大概那么宽。它的生命值和你施法时未受伤的情况下相同，它的AC为20（-1体型，+11天生）。它会和一般生物一样承受伤害，但大多数不造成伤害的法术对它无效。
 这只手永远不会被敌人所借机攻击。它不能穿过力场墙（wall of force），也无法进入反魔场（antimagic field），但它会受到虹光法墙（prismatic wall）与虹光法球（prismatic sphere）的全部效果。这只手的豁免检定与其施法者相同。
解离术（Disintegrate）或是成功的解除魔法（dispel magic）会摧毁这只手。
 体重2,000磅或以下的生物能以半速从这只手边挤过去。体重2,000磅以上的生物的速度不会受此手影响，但攻击依然会受阻。
 选择新目标是一个移动等效动作。
器材：一只软手套。

Interposing Hand
 Evocation [Force]
Level: Sor/Wiz 5
Components: V, S, F
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: 10-ft. hand
Duration: 1 round/level (D)
Saving Throw: None
Spell Resistance: Yes
Interposing hand creates a Large magic hand that appears between you and one opponent. This floating, disembodied hand then moves to remain between the two of you, regardless of where you move or how the opponent tries to get around it, providing cover (+4 AC) for you against that opponent. Nothing can fool the hand - it sticks with the selected opponent in spite of darkness, invisibility, polymorphing, or any other attempt at hiding or disguise. The hand does not pursue an opponent, however.
 An interposing hand is 10 feet long and about that wide with its fingers outstretched. It has as many hit points as you do when you're undamaged, and its AC is 20 (-1 size, +11 natural). It takes damage as a normal creature, but most magical effects that don't cause damage do not affect it.
 The hand never provokes attacks of opportunity from opponents. It cannot push through a wall of force or enter an antimagic field, but it suffers the full effect of a prismatic wall or prismatic sphere. The hand makes saving throws as its caster.
Disintegrate or a successful dispel magic destroys it.
 Any creature weighing 2,000 pounds or less that tries to push past the hand is slowed to half its normal speed. The hand cannot reduce the speed of a creature weighing more than 2,000 pounds, but it still affects the creature's attacks.
 Directing the spell to a new target is a move action.
Focus: A soft glove.
]]

pwr_forceful_hand_d=[[
]]
--[[
飞击掌（Forceful Hand）
 塑能系[力场]
等级：术士/法师 6
法术成分：言语，姿势，器材
 该法术作用类似护身掌（interposing hand），只是飞击掌能够追赶并把选定的对手推开。此攻击视作冲撞，在力量检定上有+14的加值（力量27带来+8，大型+4，冲锋时+2，而它总是可以获得这一项）。这只巨手总是和敌手一起移动来将目标推向所允许的最大距离，它没有速度限制。将此法术指引向新的目标是一个移动动作。
 特别强壮的生物也无法将巨手推离方向，因为随后巨手就会将自己重新定位在该生物和你之间，但是对手可以通过成功的冲撞巨手来将它推向你的方向。
器材：一只皮制或厚布制的结实手套。

Forceful Hand
 Evocation [Force]
Level: Sor/Wiz 6
Components: V, S, F
 This spell functions like interposing hand, except that the forceful hand pursues and pushes away the opponent that you designate. Treat this attack as a bull rush with a +14 bonus on the Strength check (+8 for Strength 27, +4 for being Large, and a +2 bonus for charging, which it always gets). The hand always moves with the opponent to push that target back the full distance allowed, and it has no speed limit. Directing the spell to a new target is a move action.
 A very strong creature could not push the hand out of its way because the latter would instantly reposition itself between the creature and you, but an opponent could push the hand up against you by successfully bull rushing it.
Focus: A sturdy glove made of leather or heavy cloth.
]]

pwr_grasping_hand_d=[[
]]
--[[
擒拿掌（Grasping Hand）
 塑能系[力场]
等级：术士/法师 7，力量7
法术成分：言语，姿势，器材/法器
 该法术类似护身掌（interposing hand），只是巨手还可以擒抱你选择的一个对手。擒拿掌每轮可以获得一次擒抱攻击。
 要接触对方时，它的攻击加值为你的施法者等级加你的智力、感知、或魅力加值（分别对应法师、牧师、和术士），再加上巨手力量值（31）带来的+10，再因为是大体型而-1。它的擒抱加值和之前算法相同，只是大体型带来的是+4修正而非-1。巨手可以抓住但不会伤害被擒抱的生物。
 指引该法术对新的目标是一个移动动作。
擒拿掌也可以像飞击掌（forceful hand）一样冲撞对手，但是在力量检定上有+16加值（力量31带来+10，大型+4，冲锋时+2，而它总是可以获得这一项）。也可以像护身掌一样将自己插入到适当的位置。
 施放这个法术的牧师以他们的神祗来命名此法术。
奥术器材：一只皮手套。

Grasping Hand
 Evocation [Force]
Level: Sor/Wiz 7, Strength 7
Components: V, S, F/DF
 This spell functions like interposing hand, except the hand can also grapple one opponent that you select. The grasping hand gets one grapple attack per round.
 Its attack bonus to make contact equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for wizards, clerics, and sorcerers, respectively), +10 for the hand's Strength score (31), -1 for being Large. Its grapple bonus is this same figure, except with a +4 modifier for being Large instead of -1. The hand holds but does not harm creatures it grapples.
 Directing the spell to a new target is a move action.
 The grasping hand can also bull rush an opponent as forceful hand does, but at a +16 bonus on the Strength check (+10 for Strength 35, +4 for being Large, and a +2 bonus for charging, which it always gets), or interpose itself as interposing hand does.
 Clerics who cast this spell name it for their deities.
Arcane Focus: A leather glove.
]]

pwr_clenched_fist_d=[[
]]
--[[
金刚拳（Clenched Fist）
 塑能系[力场]
等级：术士/法师8，力量8
法术成分：言语，姿势，器材/法器
 该法术类似护身掌（interposing hand），但它会用自己来给你提供防护，推开或击打你所选定的目标。这个漂浮的魔手会以每轮60英尺的速度移动并在同一轮中进行攻击。因为魔手是由你控制，所以它发现隐身和隐蔽的能力与你相同。
 魔手每轮可以攻击一次，它的攻击加值为你的施法者等级加上你的智力调整值（法师）、魅力调整值（术士）或感知调整值（牧师），再加上魔手本身的力量调整值+11（魔手力量33），再因为是大体型而-1。魔手每次攻击造成1d8+11点伤害，任何被击中的目标必须通过一次强韧检定（对抗该法术豁免检定DC）否则将被震慑1轮。命令魔手去选择一个新的目标是一个移动动作。
金刚拳可以如同护身掌一样将自己插入到适当的位置，也可以尝试像飞击掌（forceful hand）一样冲撞对手，但它的力量检定加值为+15。
 施放这个法术的牧师以他们的神祗来命名此法术。
奥术器材：一只皮制手套。

Clenched Fist
 Evocation [Force]
Level: Sor/Wiz 8, Strength 8
Components: V, S, F/DF
 This spell functions like interposing hand, except that the hand can interpose itself, push, or strike one opponent that you select. The floating hand can move as far as 60 feet and can attack in the same round. Since this hand is directed by you, its ability to notice or attack invisible or concealed creatures is no better than yours.
 The hand attacks once per round, and its attack bonus equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for a wizard, cleric, or sorcerer, respectively), +11 for the hand's Strength score (33), -1 for being Large. The hand deals 1d8+11 points of damage on each attack, and any creature struck must make a Fortitude save (against this spell's save DC) or be stunned for 1 round. Directing the spell to a new target is a move action.
 The clenched fist can also interpose itself as interposing hand does, or it can bull rush an opponent as forceful hand does, but at a +15 bonus on the Strength check.
 Clerics who cast this spell name it for their deities.
Arcane Focus: A leather glove.
]]

pwr_crushing_hand_d=[[
]]
--[[
粉碎掌（Crushing Hand）
 塑能系[力场]
等级：术士/法师9，力量9
法术成分：言语、姿势、材料、器材/法器
 该法术类似护身掌（interposing hand），不同的是它能自动遮掩施法者，推开或碾压一个你挑选的目标。
粉碎掌能像擒拿掌（grasping hand）一样擒抱一个生物。它的擒抱加值等于你的施法者等级+你的智力（法师）、感知（牧师）、或者魅力（术士）修正，魔手本身力量加值+12（力量35），大体形+4加值。魔手可以在每次擒抱成功后对目标造成2d6+12点伤害（正常伤害，并非非致命伤）。
粉碎掌可以像护身掌一样掩护你，也可以像飞击掌（forceful hand）一样冲撞对手，不过力量检定加值为+18。
 指引该魔手往新的目标是一个类移动动作。
 施法的牧师以他的神祗来命名此法术。
奥术材料成分：一个鸡蛋壳。
奥术器材：一只蛇皮手套。

Crushing Hand
 Evocation [Force]
Level: Sor/Wiz 9, Strength 9
Components: V, S, M, F/DF
 This spell functions like interposing hand, except that the hand can interpose itself, push, or crush one opponent that you select.
 The crushing hand can grapple an opponent like grasping hand does. Its grapple bonus equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for a wizard, cleric, or sorcerer, respectively), +12 for the hand's Strength score (35), +4 for being Large. The hand deals 2d6+12 points of damage (lethal, not nonlethal) on each successful grapple check against an opponent.
 The crushing hand can also interpose itself as interposing hand does, or it can bull rush an opponent as forceful hand does, but at a +18 bonus.
 Directing the spell to a new target is a move action.
 Clerics who cast this spell name it for their deities.
Arcane Material Component: The shell of an egg.
Arcane Focus: A glove of snakeskin.
]]

pwr_mages_faithful_hound_d=[[
]]
--[[
法师忠犬（Mage’s Faithful Hound）
 咒法系（创造）
等级：术士/法师5
法术成分：言语，姿势，材料
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
效果：魅影守护犬
持续时间：1小时/施法者等级或直到能量散发，之后1轮/施法者每等级；见说明
豁免：无
法术抗力：不可
 你造出一条只有你看得见的魅影守护犬。它会保卫创造地点周围的区域（它不会移动）。如果有小型或更大的生物进入魅影守护犬附近30英尺内，它就会大声开始吠叫。（如果守护犬出现时30英尺范围内已经有生物存在，则这些生物可以在这一区域内自由移动。但如果他们离开此范围又再进来，还是会引发吠叫。）守护犬可以看见隐形生物和灵体生物。它不会理会虚假幻影，但会发现幽影幻象。
 如果入侵者接近守护犬周围5英尺内，它会停止吠叫并展开凶狠的攻击，每轮可以咬一口（+10攻击加值，2D6+3点穿刺伤害）。守护犬拥有隐形生物的战斗优势。
 守护犬处于准备攻击的状态，所以可以在入侵者的回合中咬第一下。在对抗伤害减免时，守护犬的啮咬视为魔法武器。守护犬可以被解除，但不能被攻击。
 未触发前，法术的持续时间是1小时/施法者每等级。然而，一旦守护犬开始吠叫，持续时间就只剩下1轮/施法者每等级。如果你和狗的距离超过100英尺，法术就会终止。
材料成分：一个微型银质哨子，一块骨头和一条线

Mage's Faithful Hound
 Conjuration (Creation)
Level: Sor/Wiz 5
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: Phantom watchdog
Duration: 1 hour/caster level or until discharged, then 1 round/caster level; see text
Saving Throw: None
Spell Resistance: No
 You conjure up a phantom watchdog that is invisible to everyone but yourself. It then guards the area where it was conjured (it does not move). The hound immediately starts barking loudly if any Small or larger creature approaches within 30 feet of it. (Those within 30 feet of the hound when it is conjured may move about in the area, but if they leave and return, they activate the barking.) The hound sees invisible and ethereal creatures. It does not react to figments, but it does react to shadow illusions.
 If an intruder approaches to within 5 feet of the hound, the dog stops barking and delivers a vicious bite (+10 attack bonus, 2d6+3 points of piercing damage) once per round. The dog also gets the bonuses appropriate to an invisible creature.
 The dog is considered ready to bite intruders, so it delivers its first bite on the intruder's turn. Its bite is the equivalent of a magic weapon for the purpose of damage reduction. The hound cannot be attacked, but it can be dispelled.
 The spell lasts for 1 hour per caster level, but once the hound begins barking, it lasts only 1 round per caster level. If you are ever more than 100 feet distant from the hound, the spell ends.
Material Component: A tiny silver whistle, a piece of bone, and a thread.
]]

pwr_feeblemind_c=[[
生物的智力和魅力值都掉到1，不能使用基于智力或魅力的技能，不能施法，不能理解语言，但依然能分清敌我。

医疗术可移除此效果。
]]

pwr_feeblemind_d=[[
如果目标生物在意志豁免中失败，他的智力和魅力值都将掉到1。被影响的生物不能使用基于智力或魅力的技能，不能施法，不能理解语言，但依然能分清敌我。

医疗术可移除此效果。

能施展奥术的生物，例如术士或法师，在他的豁免判定中要受到-4减值。
]]
--[[
弱智术（Feeblemind）
 惑控系（胁迫）[影响心灵]
等级：术士/法师 5
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
目标：一个生物
持续时间：立即
豁免：意志通过则无效；见正文
法术抗力：可
如果目标生物在意志豁免中失败，他的智力和魅力值都将掉到1。被影响的生物不能使用任何基于智力或魅力的技能，不能施法，不能理解语言，也不能连贯的交流。但是他依然知道谁是他的朋友，也能跟随他们行动，甚至可以保护他们。受术者会始终保持这一状态，直到被医疗术（heal）、有限祈愿术（limited wish）、神迹术（miracle）、或祈愿术（wish）来取消掉弱智术效果为止。能施展奥术的生物，例如术士或法师，在他的豁免判定中要受到-4减值。
材料成分：一把粘土、水晶、玻璃、或矿石小球。


Feeblemind
 Enchantment (Compulsion) [Mind-Affecting]
Level: Sor/Wiz 5
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One creature
Duration: Instantaneous
Saving Throw: Will negates; see text
Spell Resistance: Yes
If the target creature fails a Will saving throw, its Intelligence and Charisma scores each drop to 1. The affected creature is unable to use Intelligence- or Charisma-based skills, cast spells, understand language, or communicate coherently. Still, it knows who its friends are and can follow them and even protect them. The subject remains in this state until a heal, limited wish, miracle, or wish spell is used to cancel the effect of the feeblemind. A creature that can cast arcane spells, such as a sorcerer or a wizard, takes a -4 penalty on its saving throw.
Material Component: A handful of clay, crystal, glass, or mineral spheres.
]]

pwr_mind_fog_d=[[
心灵迷雾可以造出一片薄薄的雾气来削弱身处其中生物的心智抵抗力。

雾气中生物的感知检定和意志豁免-10环境减值。意志豁免成功则不受影响，且不用再对同一团雾气做检定。

受影响的生物在雾气中会一直遭受减值，离开后2d6轮恢复正常。

雾气本身很稀薄，不会影响视觉。
]]
--[[
心灵迷雾（Mind Fog）
 惑控系（胁迫）[影响心灵]
等级：吟游诗人5，术士/法师5
法术成分：言语，姿势
施法时间：1个标准动作
距离：中距（100英尺+10英尺/施法者每等级）
效果：半径20英尺，高20英尺的弥漫范围内充满迷雾
持续时间：30分钟+2D6轮；见说明
豁免：意志，通过则无效
法术抗力：可

心灵迷雾可以造出一片薄薄的雾气来削弱身处其中生物的心智抵抗力。雾气中的生物，在进行感知检定和意志豁免时，受到-10的环境减值。（如果生物通过了对雾气的意志检定，将不受影响，并且不用再对同一团雾气再做检定，即使是继续待在雾中也是一样。）受影响的生物只要不离开雾气范围就会一直受到影响，离开后需要2d6轮才能恢复正常。雾气本身不会移动，而且可以持续30分钟（或直到被风吹散为止）。和风（时速11英里以上）在4轮之内吹散云雾。强风（时速21英里以上）可以一轮吹散。

雾气本身很稀薄，不会影响视觉。

Mind Fog
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 5, Sor/Wiz 5
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Fog spreads in 20-ft. radius, 20 ft. high
Duration: 30 minutes and 2d6 rounds; see text
Saving Throw: Will negates
Spell Resistance: Yes

Mind fog produces a bank of thin mist that weakens the mental resistance of those caught in it. Creatures in the mind fog take a -10 competence penalty on Wisdom checks and Will saves. (A creature that successfully saves against the fog is not affected and need not make further saves even if it remains in the fog.) Affected creatures take the penalty as long as they remain in the fog and for 2d6 rounds thereafter. The fog is stationary and lasts for 30 minutes (or until dispersed by wind).

A moderate wind (11+ mph) disperses the fog in four rounds; a strong wind (21+ mph) disperses the fog in 1 round.

The fog is thin and does not significantly hamper vision.
]]

pwr_waves_of_fatigue_d=[[
负能量波使得法术范围内的所有活物疲乏。此法术对已疲乏的生物无效。
]]
--[[
疲乏波（Waves of Fatigue）
 死灵系
等级：术士/法师5
法术成分：言语，姿势
施法时间：1个标准动作
距离：30英尺
区域：锥形爆发范围
持续时间：立即
豁免：无
法术抗力：可
负能量波会使得法术范围内的所有活物疲乏（fatigued）。本法术对已经陷入疲乏的生物无效。

Waves of Fatigue
 Necromancy
Level: Sor/Wiz 5
Components: V, S
Casting Time: 1 standard action
Range: 30 ft.
Area: Cone-shaped burst
Duration: Instantaneous
Saving Throw: No
Spell Resistance: Yes
Waves of negative energy render all living creatures in the spell's area fatigued. This spell has no effect on a creature that is already fatigued.
]]

pwr_goi_l_d=[[
一个散发着微光的固定魔法球体环绕着你，将3级或更低的法术效果排除在外，但不包括施放结界时已生效的法术。任何法术都可穿过或穿出此结界。
]]
--[[
次等法术无效结界（Globe of Invulnerability, Lesser）
 防护系
等级：术士/法师 4
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：10英尺
区域：以你为中心的10英尺球形弥漫范围
持续时间：1轮/每等级（可解消）
豁免：无
法术抗力：不可
 一个散发着微光的固定魔法球体环绕着你，它可以将所有3级或更低的法术效果排除在外。任何这类法术的区域或效果将无法包括次等法术无效结界的区域。这类法术将无法影响结界内部的任何目标。被排斥的效果包括类法术能力和物品产生的法术或类法术效果。但是，任何类型的法术都可以穿过或穿出这个魔法结界。4级或更高等级的法术不受结界影响，那些在施放结界时已经发挥作用的法术也不受影响。结界可以被目标型解除魔法（dispel magic）所解除，但是不会被区域型解除魔法解除。你可以离开然后再返回结界，这样不会有任何惩罚。
 注意，法术的效果不会被中止，除非它们的效果进入了结界。即使这样也只是被压制，而非被解除。
 如果给定的法术在不同职业施展的时候有不同的等级，那么在确定次等法术无效结界是否能阻止它的时候使用和施法者对应的那个等级。
材料成分：一个玻璃或水晶珠，在法术持续时间结束时会粉碎。

Globe of Invulnerability, Lesser
 Abjuration
Level: Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: 10 ft.
Area: 10-ft.-radius spherical emanation, centered on you
Duration: 1 round/level (D)
Saving Throw: None
Spell Resistance: No
 An immobile, faintly shimmering magical sphere surrounds you and excludes all spell effects of 3rd level or lower. The area or effect of any such spells does not include the area of the lesser globe of invulnerability. Such spells fail to affect any target located within the globe. Excluded effects include spell-like abilities and spells or spell-like effects from items. However, any type of spell can be cast through or out of the magical globe. Spells of 4th level and higher are not affected by the globe, nor are spells already in effect when the globe is cast. The globe can be brought down by a targeted dispel magic spell, but not by an area dispel magic. You can leave and return to the globe without penalty.
 Note that spell effects are not disrupted unless their effects enter the globe, and even then they are merely suppressed, not dispelled. 
 If a given spell has more than one level depending on which character class is casting it, use the level appropriate to the caster to determine whether lesser globe of invulnerability stops it.
Material Component: A glass or crystal bead that shatters at the expiration of the spell.
]]

pwr_goi_d=[[
类似次等法术无效结界，只是它还可以排斥4级法术和类法术效果。
]]
--[[
法术无效结界（Globe of Invulnerability）
 防护系
等级：术士/法师 6
该法术功能类似次等法术无效结界，只是它还可以排斥4级法术和类法术效果。

Globe of Invulnerability
 Abjuration
Level: Sor/Wiz 6
This spell functions like lesser globe of invulnerability, except that it also excludes 4th-level spells and spell-like effects.
]]

pwr_stoneskin_d=[[
受术者获得对刀砍斧削的抵抗能力，拥有每5级10/精金的伤害减免。当吸收的伤害值达到10x施法者等级后，法术耗散。
]]
--[[
石肤术（Stoneskin）
 防护系
等级：德鲁伊 5，土 6，术士/法师 4，力量 6
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：接触
目标：被接触的生物
持续时间： 10分钟/等级或直到能量散发
豁免：意志，通过则无效（无害）
法术抗力：可（无害）
受术者获得对刀砍斧削的抵抗能力。受术者获得10/精金的伤害减免（每次受到武器伤害时吸收前10点伤害，但无法吸收精金武器造成的伤害。）当法术吸收的伤害值达到10x施法者等级（最多150点）后，法术效果消失。
材料成分：花岗岩和价值250金币的钻石尘，撒在受术者皮肤上。.

Stoneskin
 Abjuration
Level: Drd 5, Earth 6, Sor/Wiz 4, Strength 6
Components: V, S, M
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 10 min./level or until discharged
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
The warded creature gains resistance to blows, cuts, stabs, and slashes. The subject gains damage reduction 10/adamantine. (It ignores the first 10 points of damage each time it takes damage from a weapon, though an adamantine weapon bypasses the reduction.) Once the spell has prevented a total of 10 points of damage per caster level (maximum 150 points), it is discharged.
Material Component: Granite and 250 gp worth of diamond dust sprinkled on the target's skin.
]]

pwr_black_tentacles_d=[[
]]
--[[
黑触手（Black Tentacles）
 咒法系（创造）
等级：术士/法师 4
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每施法者等级）
区域：20英尺半径扩散
持续时间：1轮/每等级（可解消）
豁免：无
法术抗力：不可
 这个法术产生一片强韧的黑触手，每条长10英尺。这些涌动的触手看上去是从任何脚下的表面冒出，从泥土中，地板上，以及水面。它们紧紧抓住并缠住进入这片区域的生物，以强大的力量困住它们，之后碾碎它们。
 进入法术区域内的所有生物都必须进行一个擒抱检定，和触手的擒抱检定对抗。这些触手视作大型生物的一部分，基本攻击加值等于你的施法者等级，力量值为19。因此，它的擒抱检定调整值等于你的施法者等级+8。这些触手免疫所有类型伤害。一旦触手擒抱住一个敌手，它们会在你的回合中每轮做一次擒抱检定来产生1d6+4点钝击伤害。触手会一致挤压敌手，直到法术结束或敌手脱逃。
 任何进入法术区域的生物会立刻被触手攻击。尽管没有被触手擒抱住的生物可以移出这个区域，但是只能以正常速度的一半移动。
材料成分：一片巨章鱼或巨乌贼的触手。

Black Tentacles
 Conjuration (Creation)
Level: Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Area: 20-ft.-radius spread
Duration: 1 round/level (D)
Saving Throw: None
Spell Resistance: No
 This spell conjures a field of rubbery black tentacles, each 10 feet long. These waving members seem to spring forth from the earth, floor, or whatever surface is underfoot - including water. They grasp and entwine around creatures that enter the area, holding them fast and crushing them with great strength.
 Every creature within the area of the spell must make a grapple check, opposed by the grapple check of the tentacles. Treat the tentacles attacking a particular target as a Large creature with a base attack bonus equal to your caster level and a Strength score of 19. Thus, its grapple check modifier is equal to your caster level +8. The tentacles are immune to all types of damage.
 Once the tentacles grapple an opponent, they may make a grapple check each round on your turn to deal 1d6+4 points of bludgeoning damage. The tentacles continue to crush the opponent until the spell ends or the opponent escapes.
 Any creature that enters the area of the spell is immediately attacked by the tentacles. Even creatures who aren't grappling with the tentacles may move through the area at only half normal speed.
Material Component: A piece of tentacle from a giant octopus or a giant squid.
]]

pwr_dimension_door_d=[[
]]
--[[
任意门（Dimension Door）
 咒法系（传送）
等级：吟游诗人 4，术士/法师 4，旅行 4
法术成分：言语
施法时间： 一个标准动作
距离：远距 （400英尺+40英尺/等级）
目标：你和你接触到的物品，或其他被接触的自愿生物。
持续时间：立即
豁免检定：无，以及意志通过则无效（物体）
法术抗力：不可与可（物体）
 你可瞬间将自己传送到法术距离内的任何地方。你总是可以到达你想到达的位置——不管你是看到那地方还是仅仅声明了方向。使用完此法术后，直到下一轮之前不能再做任何动作。你可以携带不超过你最大负载能力的物品，每三级施法者等级可以带一个自愿的中体型或小体型生物（携带不超过其最大负载能力的装备、物品）或相当于此的生物。一个大型生物视作两个中型生物，一个超大型生物视作两个大型生物。被传送的生物之间必须相互接触，并且它们中至少有一个与你接触。
 若你传送到一个由固体占据的位置，你和随你旅行的每个生物都受到1d6点伤害，并被挤到100英尺内的固体表面的随机开放空间开口处。
 若100英尺内没有空地，你和随你旅行的生物都会受到额外的2d6点伤害，并被随机挤到1000英尺内的空地。若1000英尺内没有空地，你和随你旅行的生物都受到额外的4d6点伤害，并且施法失败。

Dimension Door
 Conjuration (Teleportation)
Level: Brd 4, Sor/Wiz 4, Travel 4
Components: V
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Target: You and touched objects or other touched willing creatures
Duration: Instantaneous
Saving Throw: None and Will negates (object)
Spell Resistance: No and Yes (object)
 You instantly transfer yourself from your current location to any other spot within range. You always arrive at exactly the spot desired - whether by simply visualizing the area or by stating direction. After using this spell, you can't take any other actions until your next turn. You can bring along objects as long as their weight doesn't exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you.
 If you arrive in a place that is already occupied by a solid body, you and each creature traveling with you take 1d6 points of damage and are shunted to a random open space on a suitable surface within 100 feet of the intended location.
 If there is no free space within 100 feet, you and each creature traveling with you take an additional 2d6 points of damage and are shunted to a free space within 1,000 feet. If there is no free space within 1,000 feet, you and each creature travelling with you take an additional 4d6 points of damage and the spell simply fails.
]]

pwr_obscuring_mist_d=[[
]]
--[[
隐雾术（Obscuring Mist）
 咒法系（创造）
等级：风1，牧师1，德鲁伊1，术士/法师1，水1
法术成分：言语，姿势
施法时间：1个标准动作
距离：20英尺
效果：以你为中心扩散出高20英尺，半径20英尺的云雾。
持续时间：1分钟/施法者每等级
豁免：无
法术抗力：不可
 一团雾气从你四周升起，雾气出现后就不再移动。雾气遮蔽了所有的视线，任何生物都无法看见5英尺外的东西（即使具有黑暗视觉也一样）。距离5英尺的生物有隐蔽效果（进行攻击会有20%的失手率），更远的生物则有全隐蔽效果（50%失手率，并且攻击者无法以视觉确定对方的位置）。
 和风（时速11英里以上），例如由造风术（gust of wind）产生的风，可以在4轮之内吹散云雾。强风（时速21英里以上）可以一轮吹散。火球术（fireball）、焰击术（flame strike）或类似的法术可以将爆炸范围或火焰范围内的雾气烧光。火墙术（wall of fire）则可以把它能造成伤害的范围内的雾气烧光。
 此法术在水中无效。

Obscuring Mist
 Conjuration (Creation)
Level: Air 1, Clr 1, Drd 1, Sor/Wiz 1, Water 1
Components: V, S
Casting Time: 1 standard action
Range: 20 ft.
Effect: Cloud spreads in 20-ft. radius from you, 20 ft. high
Duration: 1 min./level
Saving Throw: None
Spell Resistance: No
 A misty vapor arises around you. It is stationary once created. The vapor obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target).
 A moderate wind (11+ mph), such as from a gust of wind spell, disperses the fog in 4 rounds. A strong wind (21+ mph) disperses the fog in 1 round. A fireball, flame strike, or similar spell burns away the fog in the explosive or fiery spell's area. A wall of fire burns away the fog in the area into which it deals damage.
 This spell does not function underwater.
]]

pwr_fog_cloud_d=[[
浓雾遮住了5英尺外的视觉。5英尺内的生物具有隐蔽（20%失手率）。更远的生物具有全隐蔽（50%失手率，并且攻击者不能用视觉来定位目标）。火焰伤害类法术可将其影响范围内的雾气烧掉。
]]-- 隐雾术和云雾术都生成浓雾 虽仅隐雾术提到可被火烧 但二者应该都适用
--[[
云雾术（Fog Cloud）
 咒法系（创造）
等级：德鲁伊 2，术士/法师 2，水 2
法术成分：言语，姿势
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
效果：20英尺半径扩散，20英尺高的雾
持续时间：10分钟/每等级
豁免：无
法术抗力：不可
 一道雾墙从你指定点翻腾着向外涌出。这道雾遮住了所有5英尺以外的视觉，包括黑暗视觉。在5英尺以内的生物具有隐蔽（攻击有20%失手率）。更远的生物具有全隐蔽（50%的失手率，并且攻击者不能用视觉来定位目标）。
 常风（时速超过11英里）可以在4轮内吹散雾气；强风（时速超过21英里）可以在1轮内吹散。
 这个法术在水下没有作用。

Fog Cloud
 Conjuration (Creation)
Level: Drd 2, Sor/Wiz 2, Water 2
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft. level)
Effect: Fog spreads in 20-ft. radius, 20 ft. high
Duration: 10 min./level
Saving Throw: None
Spell Resistance: No
 A bank of fog billows out from the point you designate. The fog obscures all sight, including darkvision, beyond 5 feet. A creature within 5 feet has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker can't use sight to locate the target).
 A moderate wind (11+ mph) disperses the fog in 4 rounds; a strong wind (21+ mph) disperses the fog in 1 round.
 The spell does not function underwater.
]]

pwr_solid_fog_d=[[
这团雾遮住了5英尺外的视觉。5英尺内的生物具有隐蔽（20%失手率）。更远的生物具有全隐蔽（50%失手率，并且攻击者不能用视觉来定位目标）。区域内生物速度降到5英尺且不能5尺快步，近战攻击和伤害检定-2减值，而远程武器攻击则被彻底阻止。
]]
--[[
重雾术（Solid Fog）
 咒法系（创造）
等级：术士/法师 4
法术成分：言语，姿势，材料
持续时间：1分钟/等级
法术抗力：不可
 与云雾术（fog cloud） 类似，不过除了遮蔽视线外，重雾会使得任何穿越它的生物速度降到5英尺，不论它的正常速度是多少，同时在近战攻击检定和近战伤害上获得-2的减值。雾气还可阻止远程攻击（魔法射线和类似效果除外）。掉进重雾区域的生物或物体会减速，因此每经过10尺雾气，它所受到的坠落伤害就会减少1d6点。在重雾中，生物不能进行5尺快步。
 与普通雾气不同，只有烈风（时速31英里以上）才能吹散它，并且需花费1轮时间。
重雾术可以用魔法恒定术（permanency）来永久化。被大风吹散的永久化重雾在10分钟后会重新形成。
材料成分：一撮干燥的豌豆粉末，掺以动物蹄粉末。

Solid Fog
 Conjuration (Creation)
Level: Sor/Wiz 4
Components: V, S, M
Duration: 1 min./level
Spell Resistance: No
 This spell functions like fog cloud, but in addition to obscuring sight, the solid fog is so thick that any creature attempting to move through it progresses at a speed of 5 feet, regardless of its normal speed, and it takes a -2 penalty on all melee attack and melee damage rolls. The vapors prevent effective ranged weapon attacks (except for magic rays and the like). A creature or object that falls into solid fog is slowed, so that each 10 feet of vapor that it passes through reduces falling damage by 1d6. A creature can't take a 5-foot step while in solid fog.
 However, unlike normal fog, only a severe wind (31+ mph) disperses these vapors, and it does so in 1 round.
Solid fog can be made permanent with a permanency spell. A permanent solid fog dispersed by wind reforms in 10 minutes.
Material Component: A pinch of dried, powdered peas combined with powdered animal hoof.
]]

pwr_stinking_cloud_d=[[
]]
--[[
臭云术（Stinking Cloud）
 咒法系（创造）
等级：术士/法师 3
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
效果：扩散出半径20英尺，高20英尺的云
持续时间：1轮/等级
豁免：强韧，通过则无效
法术抗力：不可
 和云雾术（fog cloud）一样，臭云术会造出一团云雾，不过这云雾令人作呕。被云雾笼罩的活物会反胃（nauseated）。只要生物还在这团云雾中，那么效果会一直持续，离开云雾后还会持续1d4+1轮。（每个生物分别投骰。）任何通过强韧豁免后仍留在云雾中的生物，每轮都需重投豁免。
臭云术可以用魔法恒定术（permanency）来永久化。被风吹散的永久化臭云术会在十分钟后重组。
材料成分：一个臭鸡蛋或几根臭菘草叶子。

Stinking Cloud
 Conjuration (Creation)
Level: Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Cloud spreads in 20-ft. radius, 20 ft. high
Duration: 1 round/level
Saving Throw: Fortitude negates; see text
Spell Resistance: No
Stinking cloud creates a bank of fog like that created by fog cloud, except that the vapors are nauseating. Living creatures in the cloud become nauseated. This condition lasts as long as the creature is in the cloud and for 1d4+1 rounds after it leaves. (Roll separately for each nauseated character.) Any creature that succeeds on its save but remains in the cloud must continue to save each round on your turn.
Stinking cloud can be made permanent with a permanency spell. A permanent stinking cloud dispersed by wind reforms in 10 minutes.
Material Component: A rotten egg or several skunk cabbage leaves.
]]

pwr_fire_cloud_d="焚云术造出一股充满白热灰烬的沸腾烟云。每轮在你的回合中炙热的灰烬对身处其中的所有生物造成每4级1d6点火焰伤害。目标每轮做反射检定，成功则只受一半伤害。"
--[[
焚云术（Incendiary Cloud）
 咒法 (创造) [火]
等级：火8，术士/法师8
法术成分：言语，姿势
施法时间：1个标准动作
距离：中距（100英尺+10英尺/每等级）
效果：扩散出宽20英尺高20英尺的云
持续时间：一轮/级别
豁免：反射，通过则减半，见下文
法术抗力：不可

焚云术造出一股充满白热灰烬的沸腾烟云。该云雾就如云雾术（fog cloud）一样阻碍视线。此外，在你的回合中每轮炙热的灰烬对身处其中的物品造成4d6点火伤害。目标每轮做反射检定，成功的话只受一半伤害。

如同死云术（cloudkill）一样，该云雾以每轮十尺的速度移开你。每一轮都要以云雾新的源发点开始计算新的扩散范围，源发点的距离为每轮远离施法时的起点10英尺。通过专注精神，你可以指引云雾（实际上是它的源发点）以至多每轮60英尺的速度移动。云雾任何超出最大法术距离的部分都会无害的消散，从而减少剩余部分的扩散区域。

如同云雾术一样，风能吹散云雾，而且该法术不能在水下施展。

Incendiary Cloud
 Conjuration (Creation) [Fire]
Level: Fire 8, Sor/Wiz 8
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Effect: Cloud spreads in 20-ft. radius, 20 ft. high
Duration: 1 round/level
Saving Throw: Reflex half; see text
Spell Resistance: No

An incendiary cloud spell creates a cloud of roiling smoke shot through with white-hot embers. The smoke obscures all sight as a fog cloud does. In addition, the white-hot embers within the cloud deal 4d6 points of fire damage to everything within the cloud on your turn each round. All targets can make Reflex saves each round to take half damage.

As with a cloudkill spell, the smoke moves away from you at 10 feet per round. Figure out the smoke's new spread each round based on its new point of origin, which is 10 feet farther away from where you were when you cast the spell. By concentrating, you can make the cloud (actually its point of origin) move as much as 60 feet each round. Any portion of the cloud that would extend beyond your maximum range dissipates harmlessly, reducing the remainder's spread thereafter.

As with fog cloud, wind disperses the smoke, and the spell can't be cast underwater.
]]

pwr_confusion_d=[[
]]
--[[
困惑术（Confusion）
惑控系（胁迫）[影响心灵]
等级：吟游诗人3，术士/法师4，诡术4
法术成分：言语，姿势，材料/法器
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
目标：半径15英尺内的所有生物
持续时间：1轮/每等级
豁免检定：意志，通过则无效
法术抗力：可
此法术让目标变得困惑（confused）起来，让他们不能独自下决心该做什么。
在每个受术者每一轮开始前投骰查表来决定该轮内他将会做什么。
百分骰	行为
01-10	用近战或远程武器攻击施法者 (或者在无法攻击的时候靠近施法者)。
11-20	行为正常。
21-50	不做任何事情但毫无条理的胡言乱语。
51-70	以最快的速度远离施法者。
71-100	攻击最接近的生物 (在这里，魔宠将被认为是受术者身体的一部分)。
困惑中的生物无法完成要做的事情时将什么也不会做，只能胡言乱语。攻击困惑中的生物不会有什么特别优势。困惑中的生物被攻击后将自动在下回合反击攻击者，只要那时候他依然处于困惑状态。注意，除了已经准备攻击的生物（要么是困惑生物上一轮的目标，要么是刚攻击过困惑生物的生物），困惑生物将不会对其他生物进行借机攻击。
奥术材料：三个为一组的坚果壳。

Confusion
Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 3, Sor/Wiz 4, Trickery 4
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Targets: All creatures in a 15-ft. radius burst
Duration: 1 round/level
Saving Throw: Will negates
Spell Resistance: Yes
This spell causes the targets to become confused, making them unable to independently determine what they will do.
Roll on the following table at the beginning of each subject's turn each round to see what the subject does in that round.
d%	Behavior
01-10	Attack caster with melee or ranged weapons (or close with caster if attack is not possible).
11-20	Act normally.
21-50	Do nothing but babble incoherently.
51-70	Flee away from caster at top possible speed.
71-100	Attack nearest creature (for this purpose, a familiar counts as part of the subject's self).
A confused character who can't carry out the indicated action does nothing but babble incoherently. Attackers are not at any special advantage when attacking a confused character. Any confused character who is attacked automatically attacks its attackers on its next turn, as long as it is still confused when its turn comes. Note that a confused character will not make attacks of opportunity against any creature that it is not already devoted to attacking (either because of its most recent action or because it has just been attacked).
Arcane Material Component: A set of three nut shells.
]]

pwr_good_hope_d=[[
这个法术给受术者持续灌输以强有力的希望。每个受影响的生物在豁免判定，攻击判定，属性检定，技能检定，武器伤害判定上均获得+2士气加值。
]]
--[[
强大希望（Good Hope）
 惑控系（胁迫）[影响心灵]
等级：吟游诗人 3
法术成分：言语，姿势
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
目标：每等级一个活物，任意两者之间距离不得超过30英尺
持续时间：1分钟/每等级
豁免：意志，通过则无效（无害）
法术抗力：可（无害）
这个法术给受术者持续灌输以强有力的希望。每个受影响的生物在豁免判定，攻击判定，属性检定，技能检定，武器伤害判定上均获得+2士气加值。
强大希望反制并解除极度绝望（crushing despair）。

Good Hope
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 3
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Targets: One living creature/level, no two of which may be more than 30 ft. apart
Duration: 1 min./level
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
This spell instills powerful hope in the subjects. Each affected creature gains a +2 morale bonus on saving throws, attack rolls, ability checks, skill checks, and weapon damage rolls.
Good hope counters and dispels crushing despair.
]]

pwr_crushing_despair_d=[[
一股无形的、使人因绝望而悲伤至极的锥状能量在受影响的区域内爆发。每个受影响的生物以下检定将受到-2减值：攻击骰，豁免，属性检定，技能检定，和武器伤害骰。
]]
--[[
极度绝望（Crushing Despair）
 惑控系（胁迫）[影响心灵]
等级：吟游诗人3，术士/法师4
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：30英尺
范围：锥状爆发
持续时间：1分钟/每等级
豁免检定：意志，通过则无效
法术抗力：可
一股无形的、使人因绝望而悲伤至极的锥状能量在受影响的区域内爆发。每个受影响的生物以下检定将受到-2减值：攻击骰，豁免，属性检定，技能检定，和武器伤害骰。
极度绝望可以反制或解除强大希望（good hope）。
材料成分：一小瓶眼泪。-- 极度绝望

Crushing Despair
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 3, Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: 30 ft.
Area: Cone-shaped burst
Duration: 1 min./level
Saving Throw: Will negates
Spell Resistance: Yes
An invisible cone of despair causes great sadness in the subjects. Each affected creature takes a -2 penalty on attack rolls, saving throws, ability checks, skill checks, and weapon damage rolls.
Crushing despair counters and dispels good hope.
Material Component: A vial of tears.
]]

pwr_fire_shield_f=[[
你身上环绕着火焰，触感温暖。你被正常触及的近战攻击命中时，攻击者会受到1d6+每施法者等级1点的火焰伤害。基于寒冷的攻击对你仅造成一半的伤害。若此攻击可通过反射豁免来减半伤害，则当豁免成功时，你将不受伤害。
]]

pwr_fire_shield_c=[[
你身上环绕着火焰，触感寒冷。你被正常触及的近战攻击命中时，攻击者会受到1d6+每施法者等级1点的寒冷伤害。基于火焰的攻击对你仅造成一半的伤害。若此攻击可通过反射豁免来减半伤害，则当豁免成功时，你将不受伤害。
]]

pwr_fire_shield_d=[[
]]
--[[
火焰护盾（Fire Shield）
 塑能系[火或寒冷]
等级：火 5，术士/法师 4，太阳 4
法术成分：言语，姿势，材料/法器
施法时间：一个标准动作
距离：个人
目标：你自己
持续时间：1轮/每等级（可解消）
 这个法术将火焰环绕在你的身上，并且对所有在近战中攻击你的生物造成伤害。这种火焰同时还在基于寒冷的攻击或基于火的攻击（由你选择）中保护你。
 任何用它肢体或手持的武器攻击到你的人依然造成正常伤害，但是同时攻击者会受到1d6+每施法者等级1点的伤害。该伤害或者是寒冷伤害（如果护盾防护的是基于火的攻击），或者是火伤害（如果护盾防护的是基于寒冷的攻击）。如果攻击者有法术抗力，那么它可以应用在该效果上。使用较长触及范围武器攻击的生物在攻击你时不会受到这个伤害。
 当施展该法术时，你看起来是自焚了，但是火焰很薄也很纤细，只能提供正常火把一半的光照（10英尺）。火焰的颜色是随机的（各有50%机会），如果是寒冷护盾（chill shield），那么是蓝色或绿色，如果是温暖护盾（warm shield），那么是紫罗兰色或蓝色。每种功效的特殊能力见下。
温暖护盾（Warm Shield）：火焰的触感是温暖的。基于寒冷的攻击只能对你造成一半的伤害。如果这类攻击允许通过反射豁免来减半伤害，那么当豁免成功时，你将不受伤害。
寒冷护盾（Chill Shield）：火焰的触感是寒冷的。基于火的攻击只能对你造成一半的伤害。如果这类攻击允许通过反射豁免来减半伤害，那么当豁免成功时，你将不受伤害。
奥术材料成分：温暖护盾需要一小块磷；寒冷护盾需要一只活的萤火虫或其幼虫，或者四只死萤火虫的尾部。

Fire Shield
 Evocation [Fire or Cold]
Level: Fire 5, Sor/Wiz 4, Sun 4
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level (D)
 This spell wreathes you in flame and causes damage to each creature that attacks you in melee. The flames also protect you from either cold-based or fire-based attacks (your choice).
 Any creature striking you with its body or a handheld weapon deals normal damage, but at the same time the attacker takes 1d6 points of damage +1 point per caster level (maximum +15). This damage is either cold damage (if the shield protects against fire-based attacks) or fire damage (if the shield protects against cold-based attacks). If the attacker has spell resistance, it applies to this effect. Creatures wielding weapons with exceptional reach are not subject to this damage if they attack you.
 When casting this spell, you appear to immolate yourself, but the flames are thin and wispy, giving off light equal to only half the illumination of a normal torch (10 feet). The color of the flames is determined randomly (50% chance of either color) - blue or green if the chill shield is cast, violet or blue if the warm shield is employed. The special powers of each version are as follows.
Warm Shield: The flames are warm to the touch. You take only half damage from cold-based attacks. If such an attack allows a Reflex save for half damage, you take no damage on a successful save.
Chill Shield: The flames are cool to the touch. You take only half damage from fire-based attacks. If such an attack allows a Reflex save for half damage, you take no damage on a successful save.
Arcane Material Component: A bit of phosphorus for the warm shield; a live firefly or glowworm or the tail portions of four dead ones for the chill shield.
]]

pwr_resilient_sphere_d=[[
一个微微发亮的固定球形力场围绕着你。没有东西能穿过或伤害到它，除了解除魔法或解离术能摧毁它但不会伤害到你。
]]
--[[
弹力法球（Resilient Sphere）
 塑能系 [力场]
等级：术士/法师 4
法术成分：言语，姿势，材料
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
效果：直径1英尺/等级的球形，以一个生物为中心
持续时间：1分钟/等级（可解消）
豁免：反射通过则无效
法术抗力：可
 一个微微发亮的球形力场围绕着一个生物，前提是此力场的直径能够容纳该生物。在法术持续时间内此力场始终包围着它的目标。除了抹消权杖（rod of cancellation）、否定权杖（rod of negation）、解离术（disintegrate）或者目标型解除魔法（dispel magic）之外此力场球不会受到任何类型的伤害。以上效果会摧毁此力场球并且不会伤害到其中的生物。无论向内还是向外，没有任何东西能够穿越该力场球，进出都不可以，但其中的生物可以正常呼吸。
 该生物可以行动，但是此力场球不会被它之外或之内的生物以物理方式移动。
材料成分： 一块半球形的纯净水晶和一块形状相配的半球形树胶。

Resilient Sphere
 Evocation [Force]
Level: Sor/Wiz 4
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: 1-ft.-diameter/level sphere, centered around a creature
Duration: 1 min./level (D)
Saving Throw: Reflex negates
Spell Resistance: Yes
 A globe of shimmering force encloses a creature, provided the creature is small enough to fit within the diameter of the sphere. The sphere contains its subject for the spell's duration. The sphere is not subject to damage of any sort except from a rod of cancellation, a rod of negation, a disintegrate spell, or a targeted dispel magic spell. These effects destroy the sphere without harm to the subject. Nothing can pass through the sphere, inside or out, though the subject can breathe normally.
 The subject may struggle, but the sphere cannot be physically moved either by people outside it or by the struggles of those within.
Material Component: A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.
]]

pwr_phantasmal_killer_d=[[
你操弄法术受体的潜意识中的恐惧，将这恐惧塑造成一个其神志中能看见的魅影幻觉：一只最恐怖的野兽。该幻觉是法术受体所能想象的最可怕的生物。只有法术受体可以看见这个魅影杀手。而你只能看见一个模糊的外形。

法术受体首先可以做一次意志豁免以判断所见的影像是虚假的。如果此次检定失败，则魅影幻觉接触受体，而受体此时必须做一次强韧豁免。若强韧豁免失败，则死于恐惧。即使强韧豁免成功，受体也将承受每2级1d6点伤害。
]]
--[[
魅影杀手（Phantasmal Killer）
 幻术系（魅影幻觉） [恐惧，影响心灵]
等级：术士/法师4
法术成分：言语，姿势
施法时间：1个标准动作
距离：中距（100英尺+10英尺/每等级）
目标：一个活体生物
持续时间：立即
豁免：意志通过则不相信（如果发生交互），之后强韧部分生效；详见正文
法术抗力：可
你操弄法术受体的潜意识中的恐惧，将这恐惧塑造成一个其神志中能看见的魅影幻觉：一只最恐怖的野兽。该幻觉是法术受体所能想象的最可怕的生物。只有法术受体可以看见这个魅影杀手。而你只能看见一个模糊的外形。法术受体首先可以做一次意志豁免以判断所见的影像是虚假的。如果此次检定失败，则魅影幻觉接触受体，而受体此时必须做一次强韧豁免。若强韧豁免失败，则死于恐惧。即使强韧豁免成功，受体也将承受3d6点伤害。
如果法术受体佩戴了心灵感应头盔（helm of telepathy），并在遭受魅影杀手攻击时成功地通过了第一次意志豁免，则野兽可以转而攻击你。你必须通过意志检定，否则你就会变成魅影杀手的目标并要承受它致命的恐惧攻击。

Phantasmal Killer
 Illusion (Phantasm) [Fear, Mind-Affecting]
Level: Sor/Wiz 4
Components: V, S
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Target: One living creature
Duration: Instantaneous
Saving Throw: Will disbelief (if interacted with), then Fortitude partial; see text
Spell Resistance: Yes
You create a phantasmal image of the most fearsome creature imaginable to the subject simply by forming the fears of the subject's subconscious mind into something that its conscious mind can visualize: this most horrible beast. Only the spell's subject can see the phantasmal killer. You see only a vague shape. The target first gets a Will save to recognize the image as unreal. If that save fails, the phantasm touches the subject, and the subject must succeed on a Fortitude save or die from fear. Even if the Fortitude save is successful, the subject takes 3d6 points of damage.
If the subject of a phantasmal killer attack succeeds in disbelieving and is wearing a helm of telepathy, the beast can be turned upon you. You must then disbelieve it or become subject to its deadly fear attack.
]]

pwr_weird_d=[[
与魅影杀手，但可影响多个生物。

若受术者通过强韧检定，仍会受到每6级1d6点伤害，并震慑1轮。受术者的力量还会受到1d4点暂时伤害。
]]
--[[
怪影杀手（Weird）
 幻术系（魅影幻觉）[恐惧，影响心灵]
等级：术士/法师9
目标：任意数量生物，其中任意两者间距不得超过30英尺
与魅影杀手（phantasmal killer）相同，但可影响多个生物。只有受术者能看到攻击他们的魅影生物，但你可看到魅影的阴影轮廓。
若受术者通过强韧检定，仍会受到3d6点伤害，并震慑1轮。受术者的力量还会受到1d4点暂时伤害。

Weird
 Illusion (Phantasm) [Fear, Mind-Affecting]
Level: Sor/Wiz 9
Targets: Any number of creatures, no two of which can be more than 30 ft. apart
This spell functions like phantasmal killer, except it can affect more than one creature. Only the affected creatures see the phantasmal creatures attacking them, though you see the attackers as shadowy shapes.
If a subject's Fortitude save succeeds, it still takes 3d6 points of damage and is stunned for 1 round. The subject also takes 1d4 points of temporary Strength damage.
]]

pwr_sleet_storm_d=[[
降下的冰雨遮蔽了所有视线，并且使得地面结冻。区域内生物需进行敏捷检定，成功可半速移动，失败则本轮无法移动，若失败5以上或者更多则跌倒。
]]
--[[
雪风暴（Sleet Storm）
 咒法系（创造）[寒冷]
等级：德鲁伊 3，术士/法师 3
法术成分：言语，姿势，材料/法器
施法时间：一个标准动作
距离：远距（400英尺+40英尺/每等级）
区域：柱状区域（半径40英尺，高20英尺）
持续时间：1轮/等级
豁免：无
法术抗力：不可
 降下的冰雨遮蔽了所有视线（包括黑暗视觉），并且使得地面结冻。生物若要进入该区域或在区域内移动，需通过DC=10的平衡检定才能以半速移动。失败意味着无法移动，若失败5或者更多则会跌倒（参见平衡技能说明）。
 冰雨会熄灭火炬和小火。
奥术材料成分： 一撮灰尘和几滴水。

Sleet Storm
 Conjuration (Creation) [Cold]
Level: Drd 3, Sor/Wiz 3
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Long (400 ft. + 40 ft./level)
Area: Cylinder (40-ft. radius, 20 ft. high)
Duration: 1 round/level
Saving Throw: None
Spell Resistance: No
 Driving sleet blocks all sight (even darkvision) within it and causes the ground in the area to be icy. A creature can walk within or through the area of sleet at half normal speed with a DC 10 Balance check. Failure means it can't move in that round, while failure by 5 or more means it falls (see the Balance skill for details).
 The sleet extinguishes torches and small fires.
Arcane Material Component: A pinch of dust and a few drops of water.
]]

pwr_rage2_d=[[
每个受影响的生物在力量和体质上得到+2士气加值，意志豁免得到+1士气加值，防御受到-2减值。

此效果其他部分与野蛮人的狂暴技能相同，除了在狂暴结束时目标生物不会疲乏。
]]
