pwr_displacement_d=[[
受术者出现在其实际位置的大约2英尺远处。这使得他如同全隐蔽一般，攻击者有50%的失手率。
]]
--[[
移位术（Displacement）
 幻术系（五官幻觉）
等级：吟游诗人 3，术士/法师 3
法术成分：言语，材料
施法时间： 一个标准动作
距离：接触
目标：接触到的生物
持续时间：1 轮/等级（可解消）
