法术抗力：可（无害）
受术者出现在其实际位置的大约2英尺远处。这使得他如同全隐蔽一般，攻击者有50%的失手率。但与全隐蔽不同，敌人仍可以受术者为目标。真知术（True seeing）可揭露受术者的真正位置。
材料成分：一小条皮革，卷成环状。

Displacement
 Illusion (Glamer)
Level: Brd 3, Sor/Wiz 3
Components: V, M
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 1 round/level (D)
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
The subject of this spell appears to be about 2 feet away from its true location. The creature benefits from a 50% miss chance as if it had total concealment. However, unlike actual total concealment, displacement does not prevent enemies from targeting the creature normally. True seeing reveals its true location.
Material Component: A small strip of leather twisted into a loop.
]]

pwr_ray_of_exhaustion_d=[[
一条黑色的射线从你的手指射出。你必须进行一次成功的远程接触攻击以击中一个目标。

目标立刻变为力竭状态。一次成功的强韧豁免意味着该生物只会变为疲乏。

一个已经处于疲乏状态的生物将变为力竭。

此法术对已力竭的生物无效。

与正常的力竭或疲乏不同，此效果在此法术持续时间结束后终止。
]]
--[[
力竭射线（Ray of Exhaustion）
 死灵系
等级：术士/法师 3
法术成分：言语，姿势，材料
施法时间：1个标准动作
距离：近距（25英尺+5英尺/每2等级）
效果：射线
持续时间：1分钟/等级
豁免：强韧通过则部分有效；见正文
法术抗力：可
一条黑色的射线从你的手指射出。你必须进行一次成功的远程接触攻击以击中一个目标。
在法术持续时间内，目标立刻变为力竭（exhausted）状态。一次成功的强韧豁免意味着该生物只会变为疲乏（fatigued）。
一个已经处于疲乏状态的生物将变为力竭。
此法术对于已经力竭的生物没有效果。与正常的力竭或疲乏不同，此效果在此法术持续时间结束后终止。
材料成分：一滴汗。

Ray of Exhaustion
 Necromancy
Level: Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Effect: Ray
Duration: 1 min./level
Saving Throw: Fortitude partial; see text
Spell Resistance: Yes
A black ray projects from your pointing finger. You must succeed on a ranged touch attack with the ray to strike a target.
The subject is immediately exhausted for the spell's duration. A successful Fortitude save means the creature is only fatigued.
A character that is already fatigued instead becomes exhausted.
This spell has no effect on a creature that is already exhausted. Unlike normal exhaustion or fatigue, the effect ends as soon as the spell's duration expires.
Material Component: A drop of sweat.
]]

pwr_vampiric_touch_d=[[
你必须成功通过一次近战接触攻击。你的接触会造成每2级1d6点伤害。你获得等同于此伤害的暂时生命值。但获得的生命值不能超过受害者的目前生命值+10点。
]]
--[[
吸血鬼之触（Vampiric Touch）
 死灵系
等级：术士/法师3
法术成分：言语，姿势
施法时间：1个标准动作
距离：接触
目标：被接触的生物
持续时间：立即/1小时，见下文
豁免：无
法术抗力：可
你必须成功通过一次近战接触攻击。如果成功，那么你的接触会造成每两个施法者等级1d6点伤害（最大10d6）。你获得等同于此伤害的暂时生命值。但获得的生命值不能超过受害者的目前生命值+10点，因为这已经足以杀死对方。暂时生命值会在1小时后消失。

Vampiric Touch
 Necromancy
Level: Sor/Wiz 3
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous/1 hour; see text
Saving Throw: None
Spell Resistance: Yes
You must succeed on a melee touch attack. Your touch deals 1d6 points of damage per two caster levels (maximum 10d6). You gain temporary hit points equal to the damage you deal. However, you can't gain more than the subject's current hit points +10, which is enough to kill the subject. The temporary hit points disappear 1 hour later.
]]

pwr_blink_d=[[
你在主物质位面和以太位面之间来回“闪烁”，看起来像在快速随机地闪入闪出真实世界。

物理攻击对你有50%几率失手。你的攻击有20%几率失手，但此时你视为隐形生物，在攻击上有+2加值，同时忽略目标防御上的敏捷加值。

单独目标型法术对你有50%几率失败。你的法术有20%几率失败。

区域攻击和跌落仅对你造成一半伤害。

你能看到并攻击到灵体生物。

你的移动速度降至四分之三。

你能穿过固体物体，但每穿5英尺你有50%几率被弹出到最近的开放空间，而且每弹过5英尺你会受到1d6点伤害。
]]
--[[
闪现术（Blink）
 变化系
等级：吟游诗人 3，术士/法师 3
法术成分：言语，姿势
施法时间：一个标准动作
距离：个人
目标：你自己
持续时间：1轮/每等级（可解消）
 你在主物质位面和以太位面之间来回“闪烁”。看起来你就像在非常快而乱的闪入闪出真实世界。
闪现术带来以下几种效果。
 对你的物理攻击有50%失手率，盲斗专长对此无效，因为你是灵化状态，而不仅仅是隐形。如果该攻击能攻击到灵体生物，那么该失手率会降到20%（隐蔽）。如果攻击者能看到隐形生物，那么该失手率也会仅有20%。（又能看到又能攻击到灵体生物的攻击者没有失手率。）同样的，你自己的攻击也有20%失手率，这是由于有时正在攻击的时候你正好处在灵化状态。
 当你处在闪现术下时，任何针对你的单独目标型法术都有50%机会失败，除非你的攻击者可以瞄准隐形灵体生物。由于启动法术的时候你有可能处在灵界，而在灵界时法术通常不会影响主物质界，因此你自己的法术也有20%的机会失败。
 当处在闪现术下时，区域攻击仅会对你造成一半伤害（但是对那些延伸到灵界的法术来说，伤害是全部的）。你攻击时是作为隐形生物（攻击投骰上有+2加值），同时忽视目标的所有AC上的敏捷加值。
 在跌落时，你只会受到一半伤害，因为你只是在物化的时候才算跌落。
 当处在闪现术下时，你可以穿过（但无法看透）固体物体。每穿过5英尺固体物质你就有50%机会物质化。如果这种情况发生了，你将会被弹出到最近的开放空间，每这样穿过5英尺距离，你就会受到1d6点伤害。你只能以四分之三的速度移动（因为在灵界的移动是半速，而你有一半时间在那里，另一半时间是物质化的）。
 因为你有一半时间在灵界，因此你能看到甚至攻击到灵体生物。你和灵体生物之间的交互和你与物质生物交互的方式类似。
 灵体生物是不可见的虚体，而且能向任意方向移动，甚至向上和向下。作为虚体生物，你可以穿过固体物品，甚至活的生物。
 灵体生物能看到和听到主物质界，但是所有事情看上都是灰蒙蒙的，虚无缥缈的。对主物质界的视觉和听觉范围只有60英尺。
 力场效果和防护系效果可以正常影响你。这些效果从主物质界延伸到灵界，但是反过来不可。灵体生物不能攻击物质化生物，在灵化时你施展的法术只能影响到其它灵化事物。特定的物质化生物或物品有能对灵界攻击或影响的能力。此时视其它灵化生物或物品为物质化的。

Blink
 Transmutation
Level: Brd 3, Sor/Wiz 3
Components: V, S
Casting Time: 1 standard action
Range: Personal
Target: You
Duration: 1 round/level (D)
 You \"blink\" back and forth between the Material Plane and the Ethereal Plane. You look as though you're winking in and out of reality very quickly and at random.
Blinking has several effects, as follows.
 Physical attacks against you have a 50% miss chance, and the Blind-Fight feat doesn't help opponents, since you're ethereal and not merely invisible. If the attack is capable of striking ethereal creatures, the miss chance is only 20% (for concealment).
 If the attacker can see invisible creatures, the miss chance is also only 20%. (For an attacker who can both see and strike ethereal creatures, there is no miss chance.) Likewise, your own attacks have a 20% miss chance, since you sometimes go ethereal just as you are about to strike.
 Any individually targeted spell has a 50% chance to fail against you while you're blinking unless your attacker can target invisible, ethereal creatures. Your own spells have a 20% chance to activate just as you go ethereal, in which case they typically do not affect the Material Plane.
 While blinking, you take only half damage from area attacks (but full damage from those that extend onto the Ethereal Plane). You strike as an invisible creature (with a +2 bonus on attack rolls), denying your target any Dexterity bonus to AC.
 You take only half damage from falling, since you fall only while you are material.
 While blinking, you can step through (but not see through) solid objects. For each 5 feet of solid material you walk through, there is a 50% chance that you become material. If this occurs, you are shunted off to the nearest open space and take 1d6 points of damage per 5 feet so traveled. You can move at only three-quarters speed (because movement on the Ethereal Plane is at half speed, and you spend about half your time there and half your time material.)
 Since you spend about half your time on the Ethereal Plane, you can see and even attack ethereal creatures. You interact with ethereal creatures roughly the same way you interact with material ones.
 An ethereal creature is invisible, incorporeal, and capable of moving in any direction, even up or down. As an incorporeal creature, you can move through solid objects, including living creatures.
 An ethereal creature can see and hear the Material Plane, but everything looks gray and insubstantial. Sight and hearing on the Material Plane are limited to 60 feet.
 Force effects and abjurations affect you normally. Their effects extend onto the Ethereal Plane from the Material Plane, but not vice versa. An ethereal creature can't attack material creatures, and spells you cast while ethereal affect only other ethereal things. Certain material creatures or objects have attacks or effects that work on the Ethereal Plane. Treat other ethereal creatures and objects as material.
]]

pwr_color_spray_d=[[
]]
--[[
七彩喷射（Color Spray）
 幻术系（心灵幻觉）[影响心灵]
等级：术士/法师1
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：15英尺
影响区域：锥状爆发
持续时间：立即；见说明
豁免检定：意志，通过则无效
法术抗力：可
 一道斑斓炫目的光芒由你手中呈锥状散射而出，被覆盖其中的生物会被震慑，有可能会导致目盲，甚至不省人事昏迷倒地。
 效果因每个生物的HD不同而异。
2HD或以下：该生物会昏迷、目盲和震慑2d4轮，然后目盲和震慑1d4轮，最后被震慑1轮（只有活物才会昏迷倒地）。
3或4HD：该生物会目盲和震慑1d4轮，然后再被震慑1轮。
5HD或以上：该生物被震慑1轮。
 无视觉的生物不受“七彩喷射”影响。
材料成分：一撮染色粉末或沙子，包含红、黄、蓝三种颜色。

Color Spray
 Illusion (Pattern) [Mind-Affecting]
Level: Sor/Wiz 1
Components: V, S, M
Casting Time: 1 standard action
Range: 15 ft.
Area: Cone-shaped burst
Duration: Instantaneous; see text
Saving Throw: Will negates
Spell Resistance: Yes
 A vivid cone of clashing colors springs forth from your hand, causing creatures to become stunned, perhaps also blinded, and possibly knocking them unconscious.
 Each creature within the cone is affected according to its Hit Dice.
2 HD or less: The creature is unconscious, blinded, and stunned for 2d4 rounds, then blinded and stunned for 1d4 rounds, and then stunned for 1 round. (Only living creatures are knocked unconscious.)
3 or 4 HD: The creature is blinded and stunned for 1d4 rounds, then stunned for 1 round.
5 or more HD: The creature is stunned for 1 round.
 Sightless creatures are not affected by color spray.
Material Component: A pinch each of powder or sand that is colored red, yellow, and blue.
]]

