防护能量伤害能提供暂时的对一种能量的免疫力，能量类型由你在施法时指定（强酸，寒冷，电击，火焰，或音波）。当这个法术吸收了每施法者等级12点的能量伤害时（在10级时达到最多120点），法术耗散。
注意：防护能量伤害覆盖（而非叠加）了抵抗能量伤害（resist energy）。如果一个人被防护能量伤害和抵抗能量伤害所同时防护，那么防护能量伤害会吸收伤害，直到它的能力消失。

