--[[
疫病术（Contagion）
死灵系[邪恶]
等级：牧师3，破坏3，德鲁伊3，术士/法师4
法术成分：言语，姿势
施法时间：一个标准动作
距离：接触
目标：接触到的活物
持续时间：立即
豁免检定：强韧，通过则无效
法术抗力：可

此法术可以传染下列表格中的疾病，并立即发病（无潜伏期）。

下列注明为病发时的豁免检定DC（第一次豁免判定使用对抗疫病术的正常豁免DC）。
疾病	DC	伤害
失明症（Blinding sickness）	16	1d4 力量 1
失心疯（Cackle fever）		16	1d6 感知
腐热症（Filth fever）		12	1d3 敏捷和1d3体质
脑热症（Mindfire）			12	1d4 智力
红肿症（Red ache）			15	1d6 力量
颤栗症（Shakes）			13	1d8 敏捷
恶心症（Slimy doom）		14	1d4 体质
1 每当受害者因为失明症损失2点或更多的力量时，他或她必须作另一次的强韧豁免检定（用失明症豁免DC），失败则永久目盲。-- 用感染疾病时的豁免检定

Contagion
Necromancy [Evil]
Level: Clr 3, Destruction 3, Drd 3, Sor/Wiz 4
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous
Saving Throw: Fortitude negates
Spell Resistance: Yes

The subject contracts a disease selected from the table below, which strikes immediately (no incubation period).

The DC noted is for the subsequent saves (use contagion's normal save DC for the initial saving throw).
Disease				DC	Damage
Blinding sickness	16	1d4 Str 1
Cackle fever		16	1d6 Wis
Filth fever			12	1d3 Dex and 1d3 Con
Mindfire			12	1d4 Int
Red ache			15	1d6 Str
Shakes				13	1d8 Dex
Slimy doom			14	1d4 Con
1 Each time a victim takes 2 or more points of Strength damage from blinding sickness, he or she must make another Fortitude save (using the disease's save DC) or be permanently blinded.

疾病（DISEASE）
当一个人物被脏污的攻击所伤，或接触到带有疾病源的物品，或吃下被疾病污染的食物和饮水，他必须立刻进行一次强韧检定。如果成功，疾病没产生效果--他的免疫系统击退了传染病。如果失败，在潜伏期后他将受到伤害，之后每过一天他都要进行一次成功的强韧检定来避免再次伤害。连续两次豁免检定成功表明他击败了疾病并恢复健康，不再受伤害。
这些强韧豁免检定可以秘密进行，让玩家无法得知疾病是否得到控制。

疾病描述：
疾病有许多症状，并可经由一些传染源传播。一些典型疾病的特性在表“疾病”中作了概括说明，定义见下文。
疾病：疾病名称用斜体印出的属于超自然能力。其它的属于特异能力。
感染方式：疾病传播的方法--摄入（ingested）、吸入（inhaled）、伤口（injury）或接触（contact）。要注意有些伤口性的疾病可以通过一个很小的伤口传播，甚至是一个跳蚤咬的伤口，而大部分的吸入性疾病也可通过摄入而被感染（反之亦然）。
DC：用来预防感染（假设该人物已经被感染了）、避免每次的重复伤害、恢复健康的强韧检定难度等级。
潜伏期：伤害开始前的一段时间。
伤害：在潜伏期结束后以及之后的每天人物将承受的属性伤害。

疾病的种类：疾病包括以下类型：
失明症（Blinding Sickness）：通过被污染的水传播。
失心热症（Cackle Fever）：症状包括高烧，意识模糊，以及经常发出阵阵狂笑。也称为“狂喊症（the shrieks）”。
热魔症（Demon Fever）：经由老鬼婆（night hags）传染。能导致永久的属性吸取。
寒魔症（Devil Chills）：经由巴霸魔（barbazu）和深狱炼魔（pit fiends）传染。必须经过三次成功的豁免检定才能恢复健康，而不是通常的两次。
腐热症（Filth Fever）：经由凶暴鼠（dire rat）与食腐兽（otyughs）传染。当伤口处于肮脏的环境中时也会感染。
脑热症（Mindfire）：患者感到脑袋焦炽般的烧热。导致昏迷。
腐尸症（Mummy Rot）：经由木乃伊传染。成功的豁免检定也不会使感染者恢复健康（但仍能避免伤害）。
红肿症（Red Ache）：患者肤色转红、肿胀、发热。
颤栗症（The Shakes）：患者会不由自主的抽搐发颤和痉挛。
胶质症（Slimy Doom）：患者会由内到外逐渐变成有感染性的粘稠物。能导致永久的属性吸取。

表：疾病
疾病		感染方式	DC	潜伏期	伤害
失明症		摄入		16	1d3天	1d4 力量1
失心热症	吸入		16	1天		1d6 感知
热魔症		伤口		18	1天		1d6 体质2
寒魔症3		伤口		14	1d4天	1d4 力量
腐热症		伤口		12	1d3天	1d3 敏捷, 1d3 体质
脑热症		吸入		12	1天		1d4 智力
腐尸症4		接触		20	1天		1d6 体质
红肿症		伤口		15	1d3天	1d6 力量
颤栗症		接触		13	1天		1d8 敏捷
胶质症		接触		14	1天		1d4 体质2
1 当人物受到2或更高的伤害时，他必须做一次额外的强韧检定，失败则永久目盲。
2 当伤害发作时，他必须成功通过一次额外的强韧豁免，否则受到1点的永久属性吸取而非原来的属性伤害。
3 必须经过三次成功的豁免检定才能恢复健康。
4 成功的豁免检定也不会使感染者恢复健康。只有魔法医疗才能治愈。

治疗疾病
可以使用医疗（Heal）技能照看患者。在每一次患者进行豁免检定时，医护者同时进行一次医疗技能判定。如果医疗技能判定结果较高，患者可以采用医疗技能判定结果代替自己的豁免检定结果来对抗疾病效果。患者必须处于医疗者的照料下，并且必须之前休息了至少8小时。
属性伤害造成的属性值丢失会以每天一点的速率回复，即使人物依然在染病中也是这样。这意味着患有轻微疾病的人物可以抵抗住疾病而不会积累伤害。

DISEASE
When a character is injured by a contaminated attack touches an item smeared with diseased matter, or consumes disease-tainted food or drink, he must make an immediate Fortitude saving throw. If he succeeds, the disease has no effect—his immune system fought off the infection. If he fails, he takes damage after an incubation period. Once per day afterward, he must make a successful Fortitude saving throw to avoid repeated damage. Two successful saving throws in a row indicate that he has fought off the disease and recovers, taking no more damage.
These Fortitude saving throws can be rolled secretly so that the player doesn’t know whether the disease has taken hold.

Disease Descriptions
Diseases have various symptoms and are spread through a number of vectors. The characteristics of several typical diseases are summarized on Table: Diseases and defined below.
Disease: Diseases whose names are printed in italic in the table are supernatural in nature. The others are extraordinary.
Infection: The disease’s method of delivery—ingested, inhaled, via injury, or contact. Keep in mind that some injury diseases may be transmitted by as small an injury as a flea bite and that most inhaled diseases can also be ingested (and vice versa).
DC: The Difficulty Class for the Fortitude saving throws to prevent infection (if the character has been infected), to prevent each instance of repeated damage, and to recover from the disease.
Incubation Period: The time before damage begins.
Damage: The ability damage the character takes after incubation and each day afterward.

Types of Diseases: Typical diseases include the following:
Blinding Sickness: Spread in tainted water.
Cackle Fever: Symptoms include high fever, disorientation, and frequent bouts of hideous laughter. Also known as “the shrieks”.
Demon Fever: Night hags spread it. Can cause permanent ability drain.
Devil Chills: Barbazu and pit fiends spread it. It takes three, not two, successful saves in a row to recover from devil chills.
Filth Fever: Dire rats and otyughs spread it. Those injured while in filthy surroundings might also catch it.
Mindfire: Feels like your brain is burning. Causes stupor.
Mummy Rot: Spread by mummies. Successful saving throws do not allow the character to recover (though they do prevent damage normally).
Red Ache: Skin turns red, bloated, and warm to the touch.
The Shakes: Causes involuntary twitches, tremors, and fits.
Slimy Doom: Victim turns into infectious goo from the inside out. Can cause permanent ability drain.

Table: Diseases
Disease 			Infection	DC	Incubation	Damage
Blinding sickness	Ingested	16	1d3 days	1d4 Str1
Cackle fever		Inhaled		16	1 day		1d6 Wis
Demon fever			Injury		18	1 day		1d6 Con2
Devil chills3		Injury		14	1d4 days	1d4 Str
Filth fever			Injury		12	1d3 days	1d3 Dex, 1d3 Con
Mindfire			Inhaled		12	1 day		1d4 Int
Mummy rot4			Contact		20	1 day		1d6 Con
Red ache			Injury		15	1d3 days	1d6 Str
Shakes				Contact		13	1 day		1d8 Dex
Slimy doom			Contact		14	1 day		1d4 Con2
1 Each time the victim takes 2 or more damage from the disease, he must make another Fortitude save or be permanently blinded.
2 When damaged, character must succeed on another saving throw or 1 point of damage is permanent drain instead.
3 The victim must make three successful Fortitude saving throws in a row to recover from devil chills.
4 Successful saves do not allow the character to recover. Only magical healing can save the character.

Healing a Disease
Use of the Heal skill can help a diseased character. Every time a diseased character makes a saving throw against disease effects, the healer makes a check. The diseased character can use the healer’s result in place of his saving throw if the Heal check result is higher. The diseased character must be in the healer’s care and must have spent the previous 8 hours resting.
Characters recover points lost to ability score damage at a rate of 1 per day per ability damaged, and this rule applies even while a disease is in progress. That means that a character with a minor disease might be able to withstand it without accumulating any damage.
]]

pwr_remove_disease_d=[[
移除疾病治愈目标所患的所有疾病。

注意：由于本法术的持续时间为立即，它不能预防目标将来受到同样的疾病感染。
]]
--[[
移除疾病（Remove Disease）
 咒法系（医疗）
等级：牧师 3，德鲁伊 3，巡林客 3
法术成分：言语，姿势
施法时间：1个标准动作
距离：接触
目标：接触的生物
持续时间：立即
豁免：强韧通过则无效（无害）
法术抗力：可（无害）

移除疾病治愈目标所患的所有疾病。本法术也能杀死寄生虫，包括绿色黏怪（green slime）等。某些特殊的疾病不能被本法术消除，或者只能被某一等级以上的施法者抵消。

注意：由于本法术的持续时间为立即，它不能预防目标将来受到同样的疾病感染。

Remove Disease
 Conjuration (Healing)
Level: Clr 3, Drd 3, Rgr 3
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Fortitude negates (harmless)
Spell Resistance: Yes (harmless)

Remove disease cures all diseases that the subject is suffering from. The spell also kills parasites, including green slime and others. Certain special diseases may not be countered by this spell or may be countered only by a caster of a certain level or higher.

Note: Since the spell's duration is instantaneous, it does not prevent reinfection after a new exposure to the same disease at a later date.
]]

pwr_bestow_curse_d=[[
你对目标降下诅咒。

在下列效果中选择1种：
* 一项属性值-6（最低1）。
* 攻击、豁免、属性和技能检定-4减值。
* 每一轮目标50%几率正常行动；否则它无法进行动作。
]]
--[[
降咒（Bestow Curse）
 死灵系
等级：牧师 3，术士/法师 4
法术成分：言语，姿势
施法时间：一个标准动作
距离：接触
目标：接触的生物
持续时间：永久
豁免：意志，通过则无效
法术抗力：可

你对目标下了诅咒。在以下三种效果中选择一种。
* 一项属性值-6（最低1）。
* 攻击投骰、豁免、属性检定、技能检定上受到-4惩罚。
* 每一轮里目标只有50%机会正常行动；另外50%机会它无法进行动作。

你也可以创造出你自己的诅咒，但是不能比上面这些更强。

由此法术产生的诅咒不能被解除，但是可以被破除结界（break enchantment）、有限祈愿术（limited wish）、神迹术（miracle）、移除诅咒（remove curse）、或祈愿术（wish）所移除。

降咒反制移除诅咒（remove curse）。

Bestow Curse
 Necromancy
Level: Clr 3, Sor/Wiz 4
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: Permanent
Saving Throw: Will negates
Spell Resistance: Yes

You place a curse on the subject. Choose one of the following three effects.

* -6 decrease to an ability score (minimum 1).
* -4 penalty on attack rolls, saves, ability checks, and skill checks.
* Each turn, the target has a 50% chance to act normally; otherwise, it takes no action.

You may also invent your own curse, but it should be no more powerful than those described above.

The curse bestowed by this spell cannot be dispelled, but it can be removed with a break enchantment, limited wish, miracle, remove curse, or wish spell.

Bestow curse counters remove curse.
]]

pwr_remove_curse_d=[[
移除诅咒能立刻移除一个生物身上的所有诅咒。
]]
--[[
移除诅咒（Remove Curse）
 防护系
等级：吟游诗人 3，牧师 3，圣武士 3，术士/法师 4
法术成分：言语，姿势
施法时间：1个标准动作
距离：接触
目标：接触的生物或物品
持续时间：立即
豁免：意志通过则无效（无害）
法术抗力：可（无害）

移除诅咒即刻移除一个物品或生物上的所有诅咒。移除诅咒不会消除来自于一面受诅咒的盾牌、武器、或一件铠甲的诅咒，但是本法术可以使受到这些诅咒物品折磨的生物可以卸下并摆脱它。某些特殊的诅咒不能被本法术消除，或者只能被某一等级以上的施法者抵消。

移除诅咒反制并解除降咒（bestow curse）。

Remove Curse
 Abjuration
Level: Brd 3, Clr 3, Pal 3, Sor/Wiz 4
Components: V, S
Casting Time: 1 standard action
Range: Touch
Target: Creature or item touched
Duration: Instantaneous
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

Remove curse instantaneously removes all curses on an object or a creature. Remove curse does not remove the curse from a cursed shield, weapon, or suit of armor, although the spell typically enables the creature afflicted with any such cursed item to remove and get rid of it. Certain special curses may not be countered by this spell or may be countered only by a caster of a certain level or higher.

Remove curse counters and dispels bestow curse.
]]

pwr_dominate_person_d=[[
]]
--[[
支配人类（Dominate Person）
 惑控系（胁迫） [影响心灵]
等级：吟游诗人 4，术士/法师 5
法术成分：言语，姿势
施法时间： 1轮
距离：近距（25英尺+5英尺/2等级）
目标：一个类人生物
持续时间： 1天/等级
豁免检定：意志，通过则无效
法术抗力：可
 你可以通过你和目标心智之间的心灵连接来控制任何类人生物的行动。如果你和目标有共通语言，你可以强迫目标在能力范围内依你的想法行动。若没有共通语言，你只能用基本命令，如“过来”，“过去”，“战斗”，“站住”。你知道受术者的感受，但不会直接得知他的感官知觉，他也无法与你以心灵感应交流。
 一旦你给被支配生物下了指令，他就会全力以赴去完成命令，除了日常生存必需活动（如吃饭、睡觉等）外不会分心做其它事。由于有这种活动限制，因此只需通过DC15的察言观色检定（而非25）就可看出此生物的行动是被惑控系法术所控制的（见察言观色的技能说明）
 对被支配的生物改变指示或下达新的命令相当于指引法术，因此是一个移动动作。
 通过专注于法术（标准动作）你可以完全感受到该生物的感官知觉，但它依旧不能与你交流，你也不可通过它的眼睛视物，所以这不如你实地观察，但你仍然可以对当地发生的一切相当了解。
 当受术者意图抗拒控制，或强迫对方进行违背天性的行为时，受术者必须重新进行豁免检定并且有+2加值。明显的自杀命令不会被执行。一旦控制建立起来，只要你和受术者在同一位面，其有效距离就没有限制。你不需要看着受术者来控制他。
 你每天都要花一轮时间来专注这个法术，否则受术者就可以通过豁免检定来摆脱控制。
 当受术者被防护邪恶（Protection from evil）之类的法术保护时，可阻止你对其下令或使用心灵连接，但是不能阻止或解除已建立的支配关系。

你被施法者控制，被迫按其想法行动。
You are controlled by the caster and forced to perform as he desire.

Dominate Person
 Enchantment (Compulsion) [Mind-Affecting]
Level: Brd 4, Sor/Wiz 5
Components: V, S
Casting Time: 1 round
Range: Close (25 ft. + 5 ft./2 levels)
Target: One humanoid
Duration: One day/level
Saving Throw: Will negates
Spell Resistance: Yes
 You can control the actions of any humanoid creature through a telepathic link that you establish with the subject's mind.
 If you and the subject have a common language, you can generally force the subject to perform as you desire, within the limits of its abilities. If no common language exists, you can communicate only basic commands, such as "Come here," "Go there," "Fight," and "Stand still." You know what the subject is experiencing, but you do not receive direct sensory input from it, nor can it communicate with you telepathically.
 Once you have given a dominated creature a command, it continues to attempt to carry out that command to the exclusion of all other activities except those necessary for day-to-day survival (such as sleeping, eating, and so forth). Because of this limited range of activity, a Sense Motive check against DC 15 (rather than DC 25) can determine that the subject's behavior is being influenced by an enchantment effect (see the Sense Motive skill description).
 Changing your instructions or giving a dominated creature a new command is the equivalent of redirecting a spell, so it is a move action.
 By concentrating fully on the spell (a standard action), you can receive full sensory input as interpreted by the mind of the subject, though it still can't communicate with you. You can't actually see through the subject's eyes, so it's not as good as being there yourself, but you still get a good idea of what's going on.
 Subjects resist this control, and any subject forced to take actions against its nature receives a new saving throw with a +2 bonus. Obviously self-destructive orders are not carried out. Once control is established, the range at which it can be exercised is unlimited, as long as you and the subject are on the same plane. You need not see the subject to control it.
 If you don't spend at least 1 round concentrating on the spell each day, the subject receives a new saving throw to throw off the domination.
Protection from evil or a similar spell can prevent you from exercising control or using the telepathic link while the subject is so warded, but such an effect neither prevents the establishment of domination nor dispels it.
]]

pwr_dominate_animal_d=[[
]]
--[[
支配动物（Dominate Animal）
 惑控系（胁迫） [影响心灵]
等级：动物 3，德鲁伊 3
法术成分：言语，姿势
施法时间： 1轮
距离：近距（25英尺+5英尺/2等级）
目标：一个动物
持续时间：1 轮/等级
豁免检定：意志，通过则无效
法术抗力：可
 你可以迷住一只动物，并对它下达简单指令如“攻击”，“跑”，“取来”。自杀或自残的指令（包括攻击体型比被支配动物大两级或更多的生物）会被忽视。
支配动物会在你和受术生物之间建立心灵连接。只要动物待在法术有效距离内就可以接受无声的心灵指引。控制它时，你不需要看见它。你无法直接得知它的感官知觉，但可以知道它的感受。由于它受你自己的智能指引，因此它可以做一些超出它正常理解范围的事情。你不需要维持专注来控制它，除非你要它做一些它平常不会做的事。改变指令或发出新的命令相当于指引一个法术，因此是个移动动作。

Dominate Animal
 Enchantment (Compulsion) [Mind-Affecting]
Level: Animal 3, Drd 3
Components: V, S
Casting Time: 1 round
Range: Close (25 ft. + 5 ft./2 levels)
Target: One animal
Duration: 1 round/level
Saving Throw: Will negates
Spell Resistance: Yes
 You can enchant an animal and direct it with simple commands such as "Attack," "Run," and "Fetch." Suicidal or self-destructive commands (including an order to attack a creature two or more size categories larger than the dominated animal) are simply ignored.
Dominate animal establishes a mental link between you and the subject creature. The animal can be directed by silent mental command as long as it remains in range. You need not see the creature to control it. You do not receive direct sensory input from the creature, but you know what it is experiencing. Because you are directing the animal with your own intelligence, it may be able to undertake actions normally beyond its own comprehension. You need not concentrate exclusively on controlling the creature unless you are trying to direct it to do something it normally couldn't do. Changing your instructions or giving a dominated creature a new command is the equivalent of redirecting a spell, so it is a move action.
]]

