持续时间： 1 轮/每等级
豁免：无
法术抗力：可
你将神之恩宠带给你自己和你的盟友，同时将厌恶带给你的敌人。你和你的每个盟友在攻击、武器伤害、豁免和技能检定上都获得+1幸运加值，同时你的每个敌人都会在这类检定上受到-1减值。

