pwr_shield_other_d=[[
此法术在施法者和受术者之间形成某种神秘的联结，使得受术者遭受的部分伤害可以转移到施法者身上。

受术者的防御等级+1偏斜加值，豁免+1抗力加值，所受任何生命值伤害均减半，另一半则由施法者承受。

一旦施法者和受术者之间的距离超出施法距离，则法术结束。
]]
--[[
护卫他人（Shield Other）
 防护系
等级：牧师 2，圣武士 2，保护 2
法术成分：言语，姿势，器材
施法时间：一个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个生物
持续时间：1小时/等级（可解消）
豁免：意志，通过则无效（无害）
法术抗力：可（无害）
此法术在你和受术者之间形成某种神秘的联结，使得他遭受的部分伤害可以转移到你身上。受术者的AC获得+1偏斜加值，豁免检定获得+1抗力加值。另外受术者所受的任何造成生命值损失的伤害均减半（包括由特殊能力造成的），剩下的部分则由施法者承受。不减少生命值的伤害，比如魅惑、暂时性属性伤害、吸取等级及死亡效果则不受影响。若受术者的生命值因体质降低而减少，施法者亦不受影响。法术结束后，施法者不再承受受术者所受伤害，但已吸收的伤害也不会转回受术者身上。
 一旦你和受术者之间的距离超出施法距离，则法术结束。
器材成分：一对白金戒指（每只至少50金币），分别戴在你和受术者身上。

Shield Other
 Abjuration
Level: Clr 2, Pal 2, Protection 2
Components: V, S, F
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature
Duration: 1 hour/level (D)
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)
This spell wards the subject and creates a mystic connection between you and the subject so that some of its wounds are transferred to you. The subject gains a +1 deflection bonus to AC and a +1 resistance bonus on saves. Additionally, the subject takes only half damage from all wounds and attacks (including that dealt by special abilities) that deal hit point damage. The amount of damage not taken by the warded creature is taken by you. Forms of harm that do not involve hit points, such as charm effects, temporary ability damage, level draining, and death effects, are not affected. If the subject suffers a reduction of hit points from a lowered Constitution score, the reduction is not split with you because it is not hit point damage. When the spell ends, subsequent damage is no longer divided between the subject and you, but damage already split is not reassigned to the subject.
If you and the subject of the spell move out of range of each other, the spell ends.
Focus: A pair of platinum rings (worth at least 50 gp each) worn by both you and the warded creature.
]]

pwr_dismissal_d=[[
此法术可将一个跨位面生物强行送回它的原属位面（意志检定DC = 法术豁免检定DC - 生物的等级 + 你的施法者等级）。

若法术成功，此生物立即被送走，但有20%几率将它送至其原属位面以外的位面。
]]
--[[
驱逐术（Dismissal）
 防护系
等级：牧师 4，术士/法师 5
法术成分：言语，姿势，法器
施法时间： 一个标准动作
距离：近距（25英尺+5英尺/2等级）
目标：一个跨位面生物
持续时间：立即
豁免检定：意志，通过则无效；见说明
法术抗力：可

此法术可将一个跨位面生物强行送回它的原属位面，前提是它意志检定失败（DC=法术豁免检定DC-生物的HD+你的施法者等级）。若法术成功，生物立即被送走，但有20%的几率将生物送至其原属位面以外的位面。

Dismissal
 Abjuration
Level: Clr 4, Sor/Wiz 5
Components: V, S, DF
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One extraplanar creature
Duration: Instantaneous
Saving Throw: Will negates; see text
Spell Resistance: Yes

This spell forces an extraplanar creature back to its proper plane if it fails a special Will save (DC = spell's save DC - creature's HD + your caster level). If the spell is successful, the creature is instantly whisked away, but there is a 20% chance of actually sending the subject to a plane other than its own.
]]

pwr_banishment_d=[[
放逐术是驱逐术的强力版本。它可以强迫多个跨位面生物离开你的原属位面，最多可放逐总等级=你的施法者等级x2的生物。
]]
--[[
放逐术（Banishment）
 防护系
等级：牧师 6，术士/法师 7
法术成分：言语，姿势，器材
施法时间：一个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个或多个跨位面生物，任意两者之间不得超过30英尺
持续时间：立即
豁免：意志，通过则无效
法术抗力：可

放逐术是驱逐术（dismissal）的强力版本。它可以强迫跨位面生物离开你的原属位面。最多可以有HD两倍于你施法者等级的生物被放逐。

如果在施法的时候有目标仇恨、恐惧或其它对立的物品或物质存在，你可以增大法术成功的机会。每一件这类物品或物质会让你在超越目标法术抗力（如果有）时的施法者等级检定上获得+1加值，而法术豁免DC增加2。

某些稀有的物品在这些加值上会比普通物品强一倍（即每件物品对抗法术抗力的施法者等级检定提供+2加值，豁免DC增加4）。

奥术器材：任何令目标不适的物品（可选的，见上文）。

Banishment
 Abjuration
Level: Clr 6, Sor/Wiz 7
Components: V, S, F
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: One or more extraplanar creatures, no two of which can be more than 30 ft. apart
Duration: Instantaneous
Saving Throw: Will negates
Spell Resistance: Yes

A banishment spell is a more powerful version of the dismissal spell. It enables you to force extraplanar creatures out of your home plane. As many as 2 Hit Dice of creatures per caster level can be banished.

You can improve the spell's chance of success by presenting at least one object or substance that the target hates, fears, or otherwise opposes. For each such object or substance, you gain a +1 bonus on your caster level check to overcome the target's spell resistance (if any), the saving throw DC increases by 2.

Certain rare items might work twice as well as a normal item for the purpose of the bonuses (each providing a +2 bonus on the caster level check against spell resistance and increasing the save DC by 4).

Arcane Focus: Any item that is distasteful to the subject (optional, see above).
]]

pwr_freedom_of_movement_d=[[
受术者在通常会妨碍行动的魔法影响下，如麻痹，缓慢术，蛛网术等，也可正常移动和攻击，且对抗或脱离擒抱时自动成功。
]]
--[[
行动自如（Freedom of Movement）
 防护系
等级：吟游诗人 4，牧师 4，德鲁伊 4，机运 4，巡林客 4
法术成分：言语，姿势，材料，法器
施法时间：一个标准动作
距离：个人或接触
目标：你自己或接触的生物
持续时间：10分钟/每等级
豁免：意志，通过则无效（无害）
法术抗力：可（无害）

该法术持续时间内，你或你所触摸的生物即便处在通常会妨碍移动的魔法影响下也可正常的移动和攻击，例如麻痹，重雾术（solid fog），缓慢术（slow），蛛网术（web）。受术者在任何用来抗拒擒抱的擒抱检定时总是自动成功，同样在用来脱离擒抱或压制的擒抱检定或脱逃术检定时也是如此。

该法术还允许受术者在水下正常移动和攻击，甚至使用剑斧类挥砍武器或链枷、战锤、硬头锤等钝击类武器也可如此，只要该武器是手持而非投掷即可。但是行动自如不能让你在水中呼吸。

材料成分：围绕在胳膊或类似肢体上的一根皮带。

Freedom of Movement
 Abjuration
Level: Brd 4, Clr 4, Drd 4, Luck 4, Rgr 4
Components: V, S, M, DF
Casting Time: 1 standard action
Range: Personal or touch
Target: You or creature touched
Duration: 10 min./level
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

This spell enables you or a creature you touch to move and attack normally for the duration of the spell, even under the influence of magic that usually impedes movement, such as paralysis, solid fog, slow, and web. The subject automatically succeeds on any grapple check made to resist a grapple attempt, as well as on grapple checks or Escape Artist checks made to escape a grapple or a pin.

The spell also allows the subject to move and attack normally while underwater, even with slashing weapons such as axes and swords or with bludgeoning weapons such as flails, hammers, and maces, provided that the weapon is wielded in the hand rather than hurled. The freedom of movement spell does not, however, allow water breathing.

Material Component: A leather thong, bound around the arm or a similar appendage.
]]

pwr_haste_d=[[
受术者的移动和动作速度远快于平时。

动作的加快会带来以下效果：
- 全力攻击时额外攻击一次。
- 移动速度+30英尺增强加值，最高为正常速度x2。
- 攻击检定+1加值，防御和反射检定+1闪避加值。

多个加速术的效果不叠加。加速术可解除缓慢术。
]]
--[[
加速术（Haste）
 变化系
等级：吟游诗人 3，术士/法师3
法术成分：言语，姿势，材料
施法时间：1个标准动作
距离：近距（25英尺+ 5英尺/每2等级）
目标：彼此相距不超过30英尺的每级别一个生物
持续时间：1轮/级别
豁免：强韧，通过则无效（无害）
法术抗力：可（无害）

受术者的移动和动作速度远快于平时。动作的加快会带来以下效果。

当作全力攻击时，加速后的生物会获得一次额外的攻击机会，该次攻击可以使用任何正在持用的武器做出。这次攻击使用该生物全部的基本攻击加值，附加任何符合该情况的调整值。（该效果无法与类似能力叠加，例如追击（speed）武器，也不会真的带来额外的动作，因此你也无法利用这效果每轮多行动或施法一次。）

加速的生物在攻击上有+1的加值，并且在AC和反射检定上有+1的闪避加值。当你失去你AC的敏捷加值时，你失去该闪避加值。

被加速生物的所有移动方式（包括地面移动、掘地、攀爬、飞行、游泳）上速度会增加30英尺，最高达到受术者该移动方式正常速度的两倍。增加的速度是增强加值，同时也会按正常方式影响该生物的跳跃距离。

多个加速术无法叠加。加速术会反制或解除缓慢术（slow）。

法术材料：一片甘草的根。

Haste
 Transmutation
Level: Brd 3, Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: One creature/level, no two of which can be more than 30 ft. apart
Duration: 1 round/level
Saving Throw: Fortitude negates (harmless)
Spell Resistance: Yes (harmless)

The transmuted creatures move and act more quickly than normal. This extra speed has several effects.

When making a full attack action, a hasted creature may make one extra attack with any weapon he is holding. The attack is made using the creature's full base attack bonus, plus any modifiers appropriate to the situation. (This effect is not cumulative with similar effects, such as that provided by a weapon of speed, nor does it actually grant an extra action, so you can't use it to cast a second spell or otherwise take an extra action in the round.)

A hasted creature gains a +1 bonus on attack rolls and a +1 dodge bonus to AC and Reflex saves. Any condition that makes you lose your Dexterity bonus to Armor Class (if any) also makes you lose dodge bonuses.

All of the hasted creature's modes of movement (including land movement, burrow, climb, fly, and swim) increase by 30 feet, to a maximum of twice the subject's normal speed using that form of movement. This increase counts as an enhancement bonus, and it affects the creature's jumping distance as normal for increased speed.

Multiple haste effects don't stack. Haste dispels and counters slow.

Material Component: A shaving of licorice root.
]]

pwr_slow_d=[[
受术者的移动和攻击均变得相当缓慢。

- 每轮只能做一个移动或标准动作。
- 只能半速移动。
- 攻击检定、防御、反射豁免-1减值。

多个缓慢术的效果不叠加。缓慢术可解除加速术。
]]
--[[
缓慢术（Slow）
 变化系
等级：吟游诗人 3，术士/法师 3
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：1个生物/等级，每两个生物之间相距不超过30英尺
持续时间：1轮/等级
豁免：意志，通过则无效
法术抗力：可

受术者的移动、攻击均变得相当缓慢。

缓慢生物每轮只能做一个移动动作或一个标准动作，但不能都作（也不能做整轮动作）。

另外他在攻击检定、AC、反射豁免上得到-1的减值。

他只能以半速移动（以5尺为单位，四舍五入），他的跳跃距离和其他情况下一样会因为速度的降低而受到影响。

缓慢术的效果不叠加。缓慢术可反制和解除加速术（haste）。
材料成分：一滴糖浆。

Slow
 Transmutation
Level: Brd 3, Sor/Wiz 3
Components: V, S, M
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Targets: One creature/level, no two of which can be more than 30 ft. apart
Duration: 1 round/level
Saving Throw: Will negates
Spell Resistance: Yes

An affected creature moves and attacks at a drastically slowed rate. A slowed creature can take only a single move action or standard action each turn, but not both (nor may it take full-round actions). Additionally, it takes a -1 penalty on attack rolls, AC, and Reflex saves. A slowed creature moves at half its normal speed (round down to the next 5-foot increment), which affects the creature's jumping distance as normal for decreased speed.

Multiple slow effects don't stack. Slow counters and dispels haste.

Material Component: A drop of molasses.
]]

pwr_delay_poison_d=[[
受术者暂时对毒物免疫。

原本在其体内的任何毒素，或在法术持续期间中的毒都不会影响受术者，直到法术结束。

减缓毒发不会治疗毒物已经造成的任何伤害。
]]
--[[
减缓毒发（Delay Poison）
 咒法系（医疗）
等级：吟游诗人 2，牧师 2，德鲁伊 2，圣武士 2，巡林客1
法术成分：言语，姿势，法器
施法时间： 一个标准动作
距离：接触
目标：接触到的生物
持续时间： 1小时/等级
豁免检定：强韧，通过则无效 （无害）
法术抗力：可（无害）

受术者暂时对毒物免疫。原本在体内的任何毒素，或在法术持续期间中的毒都不会影响受术者，直到法术过期。减缓毒发不会治疗毒物已经造成的任何伤害。

Delay Poison
 Conjuration (Healing)
Level: Brd 2, Clr 2, Drd 2, Pal 2, Rgr 1
Components: V, S, DF
Casting Time: 1 standard action
Range: Touch
Target: Creature touched
Duration: 1 hour/level
Saving Throw: Fortitude negates (harmless)
Spell Resistance: Yes (harmless)

The subject becomes temporarily immune to poison. Any poison in its system or any poison to which it is exposed during the spell's duration does not affect the subject until the spell's duration has expired. Delay poison does not cure any damage that poison may have already done.
]]

pwr_neutralize_poison_d=[[
中和生物身上任何种类的毒性，目标不再遭受该毒素的附加效果，暂时效果也会终止。

在法术持续时间内，目标免疫任何毒素（无需对毒素做豁免检定）。

此法术无法治愈已存在的立即伤害，如生命值伤害，暂时属性伤害，或无法自行复原的效果。
]]
--[[
中和毒性（Neutralize Poison）
 咒法系（医疗）
等级：吟游诗人4，牧师4，德鲁伊3，圣武士4，巡林客3
法术成分：言语，姿势，材料/法器
施法时间：1个标准动作
距离：接触
目标：接触到的单一生物，或体积至多1立方英尺/每等级的物品
持续时间：10分钟/每等级
豁免：意志，通过则无效（无害，物品）
法术抗力：可（无害，物品）

你可以中和你接触到的目标生物或物品身上的任何种类的毒性。此法术生效后，中毒生物不会再因为该毒素而受影响，该毒素造成的暂时效果也可以恢复。但此法术无法治愈已经存在的立即伤害，如：生命值伤害，暂时属性伤害，或任何无法自行复原的效果。

在法术持续时间内，目标生物对任何毒素都免疫。与减缓毒发（delay poison）不同的是，此法术并不是延迟毒发的时刻到该法术持续时间结束——目标生物在法术持续时间内不需要对毒素做任何豁免检定。

如果施法者愿意，此法术也可以在法术持续时间内中和有毒生物体内或物品上的毒性。

奥术材料成分：一块木炭

Neutralize Poison
 Conjuration (Healing)
Level: Brd 4, Clr 4, Drd 3, Pal 4, Rgr 3
Components: V, S, M/DF
Casting Time: 1 standard action
Range: Touch
Target: Creature or object of up to 1 cu. ft./level touched
Duration: 10 min./level
Saving Throw: Will negates (harmless, object)
Spell Resistance: Yes (harmless, object)

You detoxify any sort of venom in the creature or object touched. A poisoned creature suffers no additional effects from the poison, and any temporary effects are ended, but the spell does not reverse instantaneous effects, such as hit point damage, temporary ability damage, or effects that don't go away on their own.

The creature is immune to any poison it is exposed to during the duration of the spell. Unlike with delay poison, such effects aren't postponed until after the duration - the creature need not make any saves against poison effects applied to it during the length of the spell.

This spell can instead neutralize the poison in a poisonous creature or object for the duration of the spell, at the caster's option.

Arcane Material Component: A bit of charcoal.
]]

pwr_poison_d=[[
如同一些自然界有毒性的掠食者一样，你通过一次成功的近战接触攻击向目标体内注入一种剧毒，造成2d6点暂时体质伤害。此伤害可通过成功的强韧豁免（DC=10+1/2你的施法者等级+你的感知调整值）来抵消。
]]
--[[
毒击术（Poison）
 死灵系
等级：牧师 4，德鲁伊 3
法术成分：言语，姿势，法器
施法时间：1个标准动作
距离：接触
目标：接触到的活体生物
持续时间：立即；见正文
豁免：强韧通过则无效；见正文
法术抗力：有
如同一些自然界有毒性的掠食者一样，你通过一次成功的近战接触攻击向目标体内注入一种剧毒。这种毒立即造成1d10点暂时体质伤害，并且1分钟后再造成1d10点暂时体质伤害。每一次的伤害都可以通过成功的强韧豁免（DC=10+1/2你的施法者等级+你的感知调整值）来抵消。

Poison
 Necromancy
Level: Clr 4, Drd 3
Components: V, S, DF
Casting Time: 1 standard action
Range: Touch
Target: Living creature touched
Duration: Instantaneous; see text
Saving Throw: Fortitude negates; see text
Spell Resistance: Yes
Calling upon the venomous powers of natural predators, you infect the subject with a horrible poison by making a successful melee touch attack. The poison deals 1d10 points of temporary Constitution damage immediately and another 1d10 points of temporary Constitution damage 1 minute later. Each instance of damage can be negated by a Fortitude save (DC 10 + 1/2 your caster level + your Wis modifier).
]]

pwr_command_d=[[
]]
--[[
命令术（Command）
 惑控系（胁迫）[依赖于语言，影响心灵]
等级：牧师1
法术成分：言语
施法时间：一个标准动作
距离：近距（25英尺+5英尺/每2等级）
目标：一个活物
持续时间：1轮
豁免检定：意志，通过则无效
法术抗力：可
 你对受术者下达单字的命令，他将尽其所能在最早的时候去完成它。你可以从下列选项中挑选。
来（Approach）：在他的回合内，受术者将尽全力的迅速直接向你靠近。受术者将什么也不做仅仅是朝你靠近，这期间可能会造成别人对其借机攻击。
掉（Drop）：在他的回合内，受术者会将手里的所有东西都扔掉，在他下一轮之前都将不会捡起来。
倒（Fall）：在他的回合内，受术者会躺倒在地。在俯卧中他可以继续正常行动，但是要受到对应的惩罚。
逃（Flee）：在他的回合内，受术者将尽全力的迅速远离你。受术者将什么也不做仅仅是离开，这期间可能会造成别人对其借机攻击。
停（Halt）：受术者将原地不动1轮。他将不能做任何动作，但并非无助状态。
 如果受术者在他接下来的回合内无法完成你所下达的命令，该法术自动失效。

命令：来				在你的回合中，你将尽可能迅速直接地走向此效果的施法者，其他什么也不做。
命令：逃				在你的回合中，你将尽可能迅速直接地远离此效果的施法者，其他什么也不做。
命令：停				在你的回合中，你将原地不动1轮，不能做任何动作，但并非无助。
命令：倒				在你的回合中，你将躺倒在地1轮。俯卧中你能正常行动，但要受到相应的惩罚。
命令：掉				在你的回合中，你将扔掉手中所有物品，直到你的下一回合之前都不会捡起来。
Command: Approach		On your turn, you may do nothing but move toward the caster as quickly and directly as possible for 1 round.
Command: Flee			On your turn, you may do nothing but move away from the caster as quickly as possible for 1 round.
Command: Halt			On your turn, you stand in place for 1 round. You may not take any actions but are not considered helpless.
Command: Fall			On your turn, you fall to the ground and remains prone for 1 round. You may act normally while prone but take any appropriate penalties.
Command: Drop			On your turn, you drop whatever you are holding. You can't pick up any dropped item until your next turn.

Command
 Enchantment (Compulsion) [Language-Dependent, Mind-Affecting]
Level: Clr 1
Components: V
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One living creature
Duration: 1 round
Saving Throw: Will negates
Spell Resistance: Yes
 You give the subject a single command, which it obeys to the best of its ability at its earliest opportunity. You may select from the following options.
Approach: On its turn, the subject moves toward you as quickly and directly as possible for 1 round. The creature may do nothing but move during its turn, and it provokes attacks of opportunity for this movement as normal.
Drop: On its turn, the subject drops whatever it is holding. It can't pick up any dropped item until its next turn.
Fall: On its turn, the subject falls to the ground and remains prone for 1 round. It may act normally while prone but takes any appropriate penalties.
Flee: On its turn, the subject moves away from you as quickly as possible for 1 round. It may do nothing but move during its turn, and it provokes attacks of opportunity for this movement as normal.
Halt: The subject stands in place for 1 round. It may not take any actions but is not considered helpless.
 If the subject can't carry out your command on its next turn, the spell automatically fails.
]]

pwr_greater_command_d=[[
]]
--[[
高等命令术（Command, Greater）
 惑控系（胁迫）[依赖于语言，影响心灵]
等级：牧师5
目标：1个生物/每等级，任意两个生物的间距不超过30英尺
持续时间：1轮/每等级
 该法术作用与命令术类似，不同的是该法术可以影响的生物是每等级1个，而且时间超过1轮。在第一个命令后的每个命令动作开始前，生物都可以重新通过意志豁免来打消法术影响。每个生物收到的命令必须一样。

Command, Greater
 Enchantment (Compulsion) [Language-Dependent, Mind-Affecting]
Level: Clr 5
Targets: One creature/level, no two of which can be more than 30 ft. apart
Duration: 1 round/level
 This spell functions like command, except that up to one creature per level may be affected, and the activities continue beyond 1 round. At the start of each commanded creature's action after the first, it gets another Will save to attempt to break free from the spell. Each creature must receive the same command.
]]

pwr_disrupting_weapon_d=[[
此法术可使受术者手中的近战武器成为不死生物杀手。

战斗中被他近战击中的不死生物，只要其等级≤你的施法者等级，并且非精英或首领，则必须通过意志检定（对抗此法术强度），失败则被摧毁。

法术抗力对摧毁效果无效。
]]
--[[
毁灭武器（Disrupting Weapon）
 变化系
等级：牧师 5
法术成分：言语，姿势
施法时间： 一个标准动作
距离：接触
目标：一件近战武器
持续时间：1 轮/等级
豁免检定：意志，通过则无效（无害，物体）； 见说明
法术抗力：可（无害，物体）

此法术可使一件近战武器成为不死生物杀手。战斗中被此武器击中的任何不死生物，只要其HD等于或低于你施法者等级就必须通过意志检定，否则会被摧毁。法术抗力对摧毁效果无效。

Disrupting Weapon
 Transmutation
Level: Clr 5
Components: V, S
Casting Time: 1 standard action
Range: Touch
Targets: One melee weapon
Duration: 1 round/level
Saving Throw: Will negates (harmless, object); see text
Spell Resistance: Yes (harmless, object)

This spell makes a melee weapon deadly to undead. Any undead creature with HD equal to or less than your caster level must succeed on a Will save or be destroyed utterly if struck in combat with this weapon. Spell resistance does not apply against the destruction effect.
]]

pwr_flame_strike_d=[[
焰击术产生一道垂直的圣火柱，轰鸣着从天而降。法术造成每级1d6点伤害。此伤害一半是火焰伤害，另一半则直接源自神力，因此抵抗火焰攻击的方式无法对这一部分起作用。
]]
--[[
焰击术（Flame Strike）
 塑能系[火]
等级：牧师 5，德鲁伊 4，太阳 5，战争 5
法术成分：言语，姿势，法器
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
