持续时间：立即
豁免：反射减半
法术抗力：可
焰击术产生一道垂直的圣火柱，轰鸣着从天而降。法术造成每施法者等级1d6的伤害（最多15d6）。这伤害一半是火伤害，但另一半是直接源自神力，因此抵抗火攻击的方式无法对这一部分起作用。

Flame Strike
 Evocation [Fire]
Level: Clr 5, Drd 4, Sun 5, War 5
Components: V, S, DF
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
