pwr_circle_of_death_d=[[
死亡法阵让活物的生命之火燃尽，从而瞬间杀死它们。

该法术能杀死等级总和不超过每施法者等级1d4的生物。目标等级须比你的施法者等级低至少3级。

等级最低的将首先被影响，等级相同时，则从最靠近法术爆发中心点的生物开始影响。
]]
--[[
死亡法阵（Circle of Death）
 死灵系[死亡]
等级：术士/法师6
法术成分：言语，姿势，材料
施法时间：一个标准动作
距离：中距（100英尺+10英尺/每等级）
范围：受术中心点半径40尺爆发范围内的活物。
持续时间：立即
豁免检定：强韧，通过则无效
法术抗力：可
死亡法阵让活物的生命之火燃尽，从而瞬间杀死它们。
这个法术杀死生命骰数总和为每施法者等级1d4的生物（最大20d4）。生命骰数最小的将首先被影响，生命骰数相同时，由最靠近法术爆发中心点的生物开始影响。生命骰数等于或者大于9的生物不会受到法术波及。多余出来不足以影响生物的生命骰数将被浪费。
材料：一颗价值不少于500金币的黑珍珠所磨制成的粉末。

Circle of Death
 Necromancy [Death]
Level: Sor/Wiz 6
Components: V, S, M
Casting Time: 1 standard action
Range: Medium (100 ft. + 10 ft./level)
Area: Several living creatures within a 40-ft.-radius burst
Duration: Instantaneous
Saving Throw: Fortitude negates
Spell Resistance: Yes
A circle of death snuffs out the life force of living creatures, killing them instantly.
The spell slays 1d4 HD worth of living creatures per caster level (maximum 20d4). Creatures with the fewest HD are affected first; among creatures with equal HD, those who are closest to the burst's point of origin are affected first. No creature of 9 or more HD can be affected, and Hit Dice that are not sufficient to affect a creature are wasted.
Material Component: The powder of a crushed black pearl with a minimum value of 500 gp.
]]

pwr_undeath_to_death_d=[[
类似死亡法阵，但针对不死生物。同样，目标等级须比你的施法者等级低至少3级。
]]
--[[
亡灵归亡（Undeath to Death）
 死灵系
等级：牧师6，术士/法师6
法术成分：言语，姿势，材料/法器
区域：40英尺半径爆发范围内的不死生物
豁免：意志，通过则无效
此法术作用类似死亡法阵（circle of death），但本法术如上述提到的一样摧毁不死生物。
材料成分：价值至少500金币的钻石粉末。

Undeath to Death
 Necromancy
Level: Clr 6, Sor/Wiz 6
Components: V, S, M/DF
Area: Several undead creatures within a 40-ft.-radius burst
Saving Throw: Will negates
This spell functions like circle of death, except that it destroys undead creatures as noted above.
Material Component: The powder of a crushed diamond worth at least 500 gp.
]]

pwr_lesser_restoration_d=[[
次等复原术能解除所有对目标的一项属性值造成减值的魔法效果，或治疗1d4点目标的一项属性所受暂时属性伤害。

它也能清除角色的疲乏效果，或由力竭恢复到疲乏。
]]
--[[
次等复原术（Restoration, Lesser）
 咒法系（医疗）
等级：牧师 2，德鲁伊2，圣武士 1
法术成分：言语，姿势
施法时间：3轮
距离：接触
目标：接触到的生物
持续时间：立即
豁免：意志通过则无效（无害）
法术抗力：可（无害）

次等复原术能解除所有对目标属性值的造成减值的魔法效果，或治疗1d4点目标的一项属性所受到的暂时属性伤害。它也能清除角色的疲乏效果，或使之由力竭状态恢复到疲乏状态。它不能回复永久属性吸取。

Restoration, Lesser
 Conjuration (Healing)
Level: Clr 2, Drd 2, Pal 1
Components: V, S
Casting Time: 3 rounds
Range: Touch
Target: Creature touched
Duration: Instantaneous
Saving Throw: Will negates (harmless)
Spell Resistance: Yes (harmless)

Lesser restoration dispels any magical effects reducing one of the subject's ability scores or cures 1d4 points of temporary ability damage to one of the subject's ability scores. It also eliminates any fatigue suffered by the character, and improves an exhausted condition to fatigued. It does not restore permanent ability drain.
]]

pwr_restoration_d=[[
类似次等复原术，但此法术还能消除负向等级。

复原术能治疗目标受到的所有暂时属性伤害，并完全回复一项属性被永久吸取的属性值。

同时它还能消除目标受到的任何疲乏或力竭效果。
]]
--[[
复原术（Restoration）
 咒法系（医疗）
等级：牧师 4，圣武士 4
法术成分：言语，姿势，材料

本法术效果类似次等复原术（lesser restoration），只是它还能消除负向等级，并回复目标生物被吸取的一个经验等级。只有该生物失去此等级的时间不超过每施法者等级一天，此被吸取的经验等级才能回复。一个被复原术回复等级的角色的经验值为达到其之前经验等级所需要的最低经验值。

复原术能治疗目标受到的所有暂时属性伤害，并完全回复某个单独的属性上被永久吸取的属性值（如果多于一个属性被吸取，你可以从中选择一个属性回复）。它同时还能消除目标受到的任何疲乏或力竭效果。

复原术不会回复因死亡造成的等级或体质属性的损失。

材料成分：撒在目标身上的价值100金币的钻石粉。

Restoration
 Conjuration (Healing)
Level: Clr 4, Pal 4
Components: V, S, M

This spell functions like lesser restoration, except that it also dispels negative levels and restores one experience level to a creature who has had a level drained. The drained level is restored only if the time since the creature lost the level is equal to or less than one day per caster level. A character who has a level restored by restoration has exactly the minimum number of experience points necessary to restore him or her to his or her previous level.

Restoration cures all temporary ability damage, and it restores all points permanently drained from a single ability score (your choice if more than one is drained). It also eliminates any fatigue or exhaustion suffered by the target.

Restoration does not restore levels or Constitution points lost due to death.

Material Component: Diamond dust worth 100 gp that is sprinkled over the target.
]]

pwr_greater_restoration_d=[[
类似次等复原术，但此法术还能消除负向等级。

高等复原术能解除所有会造成属性减值的魔法效果，治疗所有暂时属性伤害，并回复所有被吸取的属性值。

同时它还能消除目标受到的任何疲乏或力竭效果，以及所有形式的疯狂、困惑和类似的精神效果。
]]
--[[
高等复原术（Restoration, Greater）
 咒法系（医疗）
等级：牧师 7
法术成分：言语，姿势，经验值
施法时间：10分钟

本法术效果类似次等复原术（lesser restoration），只是它能消除被医治生物的所有负向等级。它还能回复目标生物被吸取的经验等级，使之回复到之前达到过的最高等级。只有该生物失去此等级的时间不超过每施法等级一周，此被吸取的经验等级才能回复。

高等复原术也能解除所有能对生物造成的属性减值的魔法效果，治疗目标受到的所有暂时属性伤害，并回复所有被吸取的属性值。它同时还能消除目标受到的任何疲乏或力竭效果，并且它还能移除所有形式的疯狂、困惑（confusion）、以及类似的精神效果。高等复原术不会回复因死亡造成的等级或体质属性的损失。

消耗经验值：500点经验值。

Restoration, Greater
 Conjuration (Healing)
Level: Clr 7
Components: V, S, XP
Casting Time: 10 minutes

This spell functions like lesser restoration, except that it dispels all negative levels afflicting the healed creature. This effect also reverses level drains by a force or creature, restoring the creature to the highest level it had previously attained. The drained levels are restored only if the time since the creature lost the level is no more than one week per caster level.

Greater restoration also dispels all magical effects penalizing the creature's abilities, cures all temporary ability damage, and restores all points permanently drained from all ability scores. It also eliminates fatigue and exhaustion, and removes all forms of insanity, confusion, and similar mental effects. Greater restoration does not restore levels or Constitution points lost due to death.

XP Cost: 500 XP.
]]

pwr_destruction_d=[[
此法术可瞬间杀死目标并摧毁遗体（但不包括其装备、物品）。若目标通过强韧检定，则受到每3级2d6点伤害。
]]
--[[
灰飞烟灭（Destruction）
 死灵系[死亡]
等级：牧师 7，死亡 7
法术成分：言语，姿势，器材
施法时间： 一个标准动作
距离：近距（25英尺+5英尺/2等级）
目标：一个生物
持续时间：立即
豁免检定：强韧，通过则效果减半
法术抗力：是
此法术可在瞬间杀死目标并摧毁遗体（但不包括其装备、物品）。若目标通过强韧检定，则受到10d6点伤害。对于检定失败的生物，要复活只能通过完全复生术（true resurrection），措辞严谨的祈愿术（wish）外加复生术（resurrection），或者神迹术（miracle）。
器材：刻有诅咒韵文的特制银圣徽（或邪徽）（价值500金币）。

Destruction
 Necromancy [Death]
Level: Clr 7, Death 7
Components: V, S, F
Casting Time: 1 standard action
Range: Close (25 ft. + 5 ft./2 levels)
Target: One creature
Duration: Instantaneous
Saving Throw: Fortitude partial
Spell Resistance: Yes
This spell instantly slays the subject and consumes its remains (but not its equipment and possessions) utterly. If the target's Fortitude saving throw succeeds, it instead takes 10d6 points of damage. The only way to restore life to a character who has failed to save against this spell is to use true resurrection, a carefully worded wish spell followed by resurrection, or miracle.
Focus: A special holy (or unholy) symbol of silver marked with verses of anathema (cost 500 gp).
]]

pwr_repulsion_d=[[
一个隐形的移动魔法场包围着你并阻挡其它生物接近你。

场内或试图进入的任何生物必须进行一次豁免检定，失败则效果持续时间内不能朝你移动。
]]
--[[
排斥术（Repulsion）
 防护系
等级：牧师 7，保护 7，术士/法师 6
法术成分：言语，姿势，器材/法器
施法时间：1个标准动作
距离：至多10英尺/等级
区域：以你为中心的至多半径10英尺/等级弥漫区域
持续时间： 1轮/等级（可解消）
豁免：意志通过则无效
法术抗力：可
 一个隐形的移动魔法场包围着你并阻挡其它生物接近你。你在施法时决定魔法场的大小（受到你的施法等级限制）。任何魔法场内或试图进入的生物都必须进行一次豁免检定。如果失败，在法术持续时间内它不能朝你移动。试图离开的生物的行动不会受到影响。
 它们可以与其他生物战斗、对你施展法术或使用远程武器攻击你。如果你向一个受影响的生物靠近，不会发生任何事。（该生物不会被强迫退后。）如果你进入生物的触及范围，那么它可以自由使用近战武器攻击你。如果一个被驱离的生物远离你之后重新试图接近你，如果它仍在法术区域内它仍然无法接近你。
 奥术器材：一对小铁棍，上面有两个犬科动物的小雕像，一黑一白，总价值50金币。

Repulsion
 Abjuration
Level: Clr 7, Protection 7, Sor/Wiz 6
Components: V, S, F/DF
Casting Time: 1 standard action
Range: Up to 10 ft./level
Area: Up to 10-ft.-radius/level emanation centered on you
Duration: 1 round/level (D)
Saving Throw: Will negates
Spell Resistance: Yes
 An invisible, mobile field surrounds you and prevents creatures from approaching you. You decide how big the field is at the time of casting (to the limit your level allows). Any creature within or entering the field must attempt a save. If it fails, it becomes unable to move toward you for the duration of the spell. Repelled creatures' actions are not otherwise restricted.
 They can fight other creatures and can cast spells and attack you with ranged weapons. If you move closer to an affected creature, nothing happens. (The creature is not forced back.) The creature is free to make melee attacks against you if you come within reach. If a repelled creature moves away from you and then tries to turn back toward you, it cannot move any closer if it is still within the spell's area.
Arcane Focus: A pair of small iron bars attached to two small canine statuettes, one black and one white, the whole array worth 50 gp.
]]

pwr_antimagic_field_d=[[
一道隐形屏障围绕着你，并随你移动。此屏障会压制其区域内所有法术或魔法效果，包括魔法物品，并使召唤生物消失（反魔场移开后在原地重新出现）。
]]
--[[
反魔场（Antimagic Field）
 防护系
等级：牧师 8，魔法 6，保护6，术士/法师 6
法术成分：言语，姿势，材料/法器
施法时间：一个标准动作
距离：10英尺
区域：以你为中心的10英尺半径弥漫区域
持续时间：10分钟/每等级（可解消）
豁免：无
法术抗力：见正文
 一道隐形屏障围绕着你，并随你移动。在这屏障之内的空间里大部分魔法效果都无法进入，包括法术、类法术能力、超自然能力。同时，它也阻止了所有范围内的魔法物品和法术的运转。
反魔场压制了在范围内使用、带入范围内、或者对区域内施展的所有法术或魔法效果，但并不是解除它。在反魔场内的时间计入被压制法术的持续时间内。
 所有种类的召唤生物，以及虚体不死生物在进入反魔场区域时会消失不见。当反魔场移开后它们又会在原地重新出现。消失的时间计入维持生物的咒语持续时间。如果你对一个已经被召唤生物占据的空间施展反魔场，该生物又具有法术抗力，那么你必须做一个施法者等级检定（1d20+施法者等级）来对抗该生物的法术抗力，从而让它消失。（持续时间为立即的咒法系法术其效果不会受到反魔场影响，因为该咒术本身并不存在于效果，这只是它的结果。）
 普通生物可以进入这一区域，也可以正常的射击。而且，就算一把魔法剑在这区域内没有魔法能力，它依然是把剑（而且是精制品剑）。对魔像和其它构装体来说，它们在制造过程中灌注了魔法，之后就靠自己维持，反魔场队它们无效（除非它们是被召唤来的，这种情况下将它们视作其它召唤生物）。类似地，元素、实体不死生物、异界生物也不受影响，除非它们是被召唤来的。当然，这些生物的类法术能力和超自然能力暂时会被反魔场无效化。解除魔法（Dispel magic）不会移除反魔场。
 共享同一空间的两个或多个反魔场不会互相影响。某些法术，例如力场墙（wall of force），虹光法球（prismatic sphere），虹光法墙（prismatic wall）不受反魔场影响（见对应法术说明）。神器和神祗不会被类似此法术的凡间法术所影响。
 如果生物比屏障占据的空间还要大，那么所有在屏障外的部分都不受影响。
奥术材料成分：一撮铁粉或铁屑。

Antimagic Field
 Abjuration
Level: Clr 8, Magic 6, Protection 6, Sor/Wiz 6
Components: V, S, M/DF
Casting Time: 1 standard action
Range: 10 ft.
Area: 10-ft.-radius emanation, centered on you
Duration: 10 min./level (D)
Saving Throw: None
Spell Resistance: See text
 An invisible barrier surrounds you and moves with you. The space within this barrier is impervious to most magical effects, including spells, spell-like abilities, and supernatural abilities. Likewise, it prevents the functioning of any magic items or spells within its confines.
 An antimagic field suppresses any spell or magical effect used within, brought into, or cast into the area, but does not dispel it. Time spent within an antimagic field counts against the suppressed spell's duration.
 Summoned creatures of any type and incorporeal undead wink out if they enter an antimagic field. They reappear in the same spot once the field goes away. Time spent winked out counts normally against the duration of the conjuration that is maintaining the creature. If you cast antimagic field in an area occupied by a summoned creature that has spell resistance, you must make a caster level check (1d20 + caster level) against the creature's spell resistance to make it wink out. (The effects of instantaneous conjurations are not affected by an antimagic field because the conjuration itself is no longer in effect, only its result.)
 A normal creature can enter the area, as can normal missiles. Furthermore, while a magic sword does not function magically within the area, it is still a sword (and a masterwork sword at that). The spell has no effect on golems and other constructs that are imbued with magic during their creation process and are thereafter self-supporting (unless they have been summoned, in which case they are treated like any other summoned creatures). Elementals, corporeal undead, and outsiders are likewise unaffected unless summoned. These creatures' spell-like or supernatural abilities, however, may be temporarily nullified by the field. Dispel magic does not remove the field.
 Two or more antimagic fields sharing any of the same space have no effect on each other. Certain spells, such as wall of force, prismatic sphere, and prismatic wall, remain unaffected by antimagic field (see the individual spell descriptions). Artifacts and deities are unaffected by mortal magic such as this. 
 Should a creature be larger than the area enclosed by the barrier, any part of it that lies outside the barrier is unaffected by the field.
Arcane Material Component: A pinch of powdered iron or iron filings.
]]

pwr_protection_from_evil_d=[[
一道魔法屏障围绕着你，并随你移动。它能让你在邪恶生物和召唤生物的攻击中获得防护，还可压制精神控制。\n\n- 对抗邪恶生物发起的攻击或效果时，你的防御等级+2偏斜加值，豁免检定+2抗性加值。\n\n- 压制你身上的精神控制效果。\n\n- 阻止邪恶召唤生物的天生武器攻击。召唤生物可用法术抗力来突破此防护。如果你对被阻拦的生物进行攻击，则此针对召唤生物的防护终止。
]]

pwr_protection_from_chaos_d=[[
类似防护邪恶，但针对善良生物。
]]

pwr_protection_from_good_d=[[
类似防护邪恶，但针对混乱生物。
