pwr_holy_aura_d=[[
一道辉煌圣洁的光辉环绕着你，保护你免受打击，抵抗邪恶生物的法术，并让攻击你的邪恶生物目盲。\n\n- 你在防御上获得+4偏斜加值，在豁免上获得+4抵抗加值。\n\n- 对抗邪恶法术和邪恶生物施放的法术时，你获得法术抗力25。\n\n- 阻挡心灵影响效果。\n\n- 被邪恶生物近战攻击命中时，攻击者目盲（强韧通过则无效，对抗此法术的豁免DC）。
