[pwr_ch_bleed				]={n=		"流血重击"				,d="使用锐器造成重击时，附加每回合5点流血伤害，持续3回合，伤害可叠加。强韧抵抗。流血状态可通过任何治愈方式来终止。"..ch_1_eff},
[pwr_ch_bleed2				]={n=			"精通流血重击"		,d="流血重击的伤害值提升到10。"},
[pwr_ch_cripple				]={n=		"致残重击"				,d="造成重击时，目标减速1回合。强韧抵抗。"..ch_1_eff},
[pwr_ch_cripple2			]={n=			"精通致残重击"		,d="类似致残重击，但效果为禁足。"},
[pwr_ch_stun				]={n=		"昏迷重击"				,d="使用钝器造成重击时，目标昏迷1回合。强韧抵抗。"..ch_1_eff},
[pwr_ch_2_effs				]={n=		"重击掌握"				,d="造成重击时，能触发2种重击效果。无此专长时，只能触发1种重击效果，即使有多个重击效果专长。"},
-- shd/amr
[pwr_shd_use1				]={n="擅长盾牌"						,d="使用盾牌（塔盾除外）时，攻击无减值。\n\n<b>通常：</b>当你使用不擅长的盾牌时，攻击将承受盾牌的防具攻击减值。"},
[pwr_shd_use2				]={n=	"擅长塔盾"					,d="类似擅长盾牌，但针对塔盾。"},
[pwr_shd_def1				]={n=	"专攻盾牌"					,d="盾牌提供的防御等级和反射豁免+1加值。"},
[pwr_shd_def2				]={n=		"高等专攻盾牌"			,d="专攻盾牌的加值再+1。"},
[pwr_amr_use1				]={n="擅长轻型盔甲"					,d="穿著轻型盔甲时无攻击减值。\n\n<b>通常：</b>当人物穿著非擅长的盔甲类型时，攻击将承受盔甲的防具攻击减值。"},
[pwr_amr_use2				]={n=	"擅长中型盔甲"				,d="类似擅长轻型盔甲，但针对中型盔甲。"},
[pwr_amr_use3				]={n=		"擅长重型盔甲"			,d="类似擅长轻型盔甲，但针对重型盔甲。"},
-- melee
[pwr_cleave					]={n=	"顺势斩"						,d="如果你对某个目标造成足以使之倒下的伤害（典型的情况是杀死它），你可以立即对攻击范围内的另一目标发动一次额外的近战攻击。\n\n此攻击使用的武器和加值，与放倒上个目标的攻击相同。本能力每轮可使用一次。"	},-- 近战杀死目标后，顺势向另一目标发动一次额外的攻击。When facing multiple enemies, if your melee attack kills one, you get a free attack on another.		-- 如：将对手的生命值打到0以下，或杀死对方 typically by dropping it to below 0 hit points or killing it	在进行这次额外攻击前，你不可做五尺快步。You cannot take a 5-foot step before making this extra attack. 	特殊：战士可以选本专长作为其战士奖励专长。Special: A fighter may select Cleave as one of his fighter bonus feats.
[pwr_cleave_x				]={n=		"大顺势斩"				,d="每轮顺势斩次数不限。"},
[pwr_cleave_ko				]={n=		"精通顺势斩"				,d="击倒也可引发顺势斩。"},
[pwr_atk_m_tgt2				]={n=		"横扫攻击"				,d="对攻击范围内的两个相邻生物发动一次近战攻击。所有攻击基于你最高基本攻击加值，但有-2减值。"..use_a},
[pwr_atk_m_tgt2_1			]={n=			"精通横扫攻击"		,d="免除横扫攻击的惩罚。"},
[pwr_atk_m_tgt2_2			]={n=				"高等横扫攻击"	,d="横扫攻击可攻击三个相邻生物。"},
[pwr_atk_m_tgtx				]={n="旋风攻击"						,d="对攻击范围内的所有生物发动一次近战攻击。"..use_b},
[pwr_del_2					]={n="无用能力"						,d="你已忘记为何习得此无用能力。或许去导师那里重训忘掉它会更好。"},
[pwr_charge1				]={n="精通冲锋"						,d="冲锋时攻击和伤害检定+2加值。\n\n无此专长时，加值为1。"},
[pwr_charge2				]={n="高等冲锋"						,d="精通冲锋的加值再+2。"},
[pwr_ao_dex					]={n="战斗反射"						,d="可额外进行数量等于敏捷加值的借机攻击，且措手不及时也可进行借机攻击。"},-- 正常：没有本项专长的人物每轮只能有一次借机攻击，并且在措手不及时不能进行借机攻击。特殊：本专长不能使游荡者在一轮中多次使用乘势攻击能力。战士可以选本专长作为其战士奖励专长。武僧可以选战斗反射作为其在2级时的奖励专长。Normal: A character without this feat can make only one attack of opportunity per round and can’t make attacks of opportunity while flat-footed. Special: The Combat Reflexes feat does not allow a rogue to use her opportunist ability more than once per round. A fighter may select Combat Reflexes as one of his fighter bonus feats. A monk may select Combat Reflexes as a bonus feat at 2nd level.
[pwr_dex_wpn				]={n="武器娴熟"						,d="当使用适合你的体型的轻武器、细剑、鞭子或刺链时，你可以在攻击检定中使用你的敏捷调整值代替力量调整值。若你持用盾牌，其防具检定减值将应用于你的攻击检定。\n\n天生武器永远视为轻型武器。"},
-- skl z_skl_bns
[pwr_s2_athletic			]={n="竞技		",d="攀爬、游泳检定+2加值。"},
[pwr_s2_acrobatic			]={n="杂耍		",d="跳跃、翻滚检定+2加值。"},
[pwr_s2_agile				]={n="灵活		",d="平衡、脱逃术检定+2加值。"},
[pwr_s2_deft_hands			]={n="熟练手法	",d="绳技、手上功夫检定+2加值。"},
[pwr_s2_stealthy			]={n="隐秘		",d="躲藏、潜行检定+2加值。"},
[pwr_s2_animal_affinity		]={n="动物亲和	",d="骑术、驯养动物检定+2加值。"},
[pwr_s2_nimble_fingers		]={n="灵巧手指	",d="开锁、解除装置检定+2加值。"},
[pwr_s2_diligent			]={n="细致		",d="估价、解读文书检定+2加值。"},
[pwr_s2_deceitful			]={n="欺诈		",d="易容、伪造文书检定+2加值。"},
[pwr_s2_magical_aptitude	]={n="魔法天赋	",d="辨识法术、使用魔法装置检定+2加值。"},
[pwr_s2_investigator		]={n="调查员		",d="搜索、搜集信息检定+2加值。"},
[pwr_s2_alertness			]={n="警觉		",d="侦察、聆听检定+2加值。\n\n特殊：只要魔宠在臂展范围内（相邻或同一格内），其主人便可获得警觉专长的好处。"},
[pwr_s2_self_sufficient		]={n="自救		",d="医疗、生存检定+2加值。"},
[pwr_s2_negotiator			]={n="谈判专家	",d="察言观色、交涉检定+2加值。"},
[pwr_s2_persuasive			]={n="说服者		",d="威吓、唬骗检定+2加值。"},
