[pwr_imm_m					]={n="魔法免疫"		,d="免疫各种法术伤害（易伤类型除外）和效果。"},
[pwr_er_50p					]={n="能量抵抗"		,d="仅受一半任意能量类型的伤害。"},
[pwr_aura5_atk2				]={n="强击光环"		,d="光环提供者近距范围内的队友的攻击检定+2加值。"},
[pwr_aura5_dmg2				]={n="凶残光环"		,d="光环提供者近距范围内的队友的伤害检定+2加值。"},
[pwr_aura5_heal5			]={n="治愈光环"		,d="光环提供者近距范围内的队友每回合恢复5点生命。"},
[pwr_aura1_fire5			]={n="炽焰光环"		,d="光环提供者邻接范围内的敌人每回合受到5点火焰伤害。"},
[pwr_aura1_toxic5			]={n="尸毒光环"		,d="光环提供者邻接范围内的敌人每回合受到5点毒素伤害。"},
[pwr_aura5_fear				]={n="恐惧光环"		,d="光环提供者邻接范围内的敌人每回合需进行恐惧检定，失败则逃跑。"},
[pwr_pack_atk				]={n="群殴乱斗"		,d="从每一个与目标邻接且拥有此专长的队友获得+1攻击检定加值。"},
[pwr_pack_dmg				]={n="群体攻击"		,d="对邻接两名以上拥有此专长的队友的敌人进行攻击时，伤害检定+5加值。"},
[pwr_rend					]={n="撕扯"			,d="如果两次爪抓都命中目标，就能抓住对手的身体并撕裂血肉，额外造成2d6+1.5倍力量调整值的伤害。"},
[pwr_rend_co				]={n="协同撕扯"		,d="和拥有此专长的队友同时邻接一个敌人时，只需一次爪抓命中就可以进行撕扯。"},
[pwr_blood_tgt1				]={n="嗜血"			,d="攻击重伤目标时，攻击检定+1加值，伤害检定+2加值。"},
[pwr_blood_tgt2				]={n="极度嗜血"		,d="攻击重伤目标时，攻击检定+2加值，伤害检定+5加值。"},
[pwr_blood_rage				]={n="血怒"			,d="重伤时，进入血怒状态：攻击检定+2加值，伤害检定+5加值，防御等级-2减值。"},
[pwr_blood_rage2			]={n="极度血怒"		,d="一旦受伤，即进入血怒状态：攻击检定+2加值，伤害检定+5加值，防御等级-2减值；重伤时，进入极度血怒状态：伤害检定加值变为+10。"},
[pwr_imbue_arrow			]={n="注魔箭"		,d="远程武器攻击时，附加1d6点伤害（随机元素伤害类型）。"},
[pwr_tox					]={n="用毒"			,d="擅长在武器上涂抹毒药，每次命中都可能使目标中毒。"},
[pwr_tox_drow				]={n="淬毒"			,d="被卓尔的淬毒武器击中的目标必须成功通过基础DC13的强韧豁免，否则将昏迷。\n\n1分钟后，昏迷的目标必须再次成功通过一个同样DC的强韧豁免，否则将继续昏迷2d4小时。\n\n一个典型的卓尔一般携带1D4-1剂卓尔毒。卓尔一般在箭矢上淬毒，但有时也会将其涂抹在近战武器上。但要注意的是，卓尔并没有在用毒时使自己免除中毒危险的特殊能力。该毒素并非魔法效果，卓尔和其他精灵都会受到影响。"},
[pwr_hit_down				]={n="蛮力击倒"		,d="近战命中时，自动触发击倒检定。"},
[pwr_charge_ex1				]={n="猛烈冲锋"		,d="冲锋时，伤害检定+5加值，自动触发击倒检定。"},
[pwr_charge_ex2				]={n="暴烈冲锋"		,d="冲锋时，伤害检定+10加值，自动触发强力击退检定：目标被击退2格，并倒地。"},
[pwr_grap_dmg1				]={n="紧勒"			,d="被擒抱者每回合受到5点伤害。"},
[pwr_grap_dmg2				]={n="熊碾"			,d="被擒抱者每回合受到10点伤害。"},
[pwr_grap_sting1			]={n="钉刺"			,d="被擒抱者每回合受到5点伤害。"},
[pwr_grap_sting2			]={n="巨型钉刺"		,d="被擒抱者每回合受到10点伤害。"},
[pwr_grap_suck				]={n="吸血"			,d="被擒抱者每回合受到5点伤害；擒抱者回复5点生命。"},
[pwr_dead_tox				]={n="尸毒"			,d="死亡时，邻接生物会被感染尸毒。"},
[pwr_x2_atk					]={n="连击"			,d="使用单一武器攻击时，会连续攻击两次。"},
[pwr_phalanx2				]={n="步兵方阵"		,d="和至少一个拥有此专长的队友邻接时，防御等级+2加值。"},
[pwr_crowd_ac				]={n="人群掩蔽"		,d="邻接一个生物时，防御等级和反射豁免检定+2加值；邻接两个以上生物时，防御等级和反射豁免检定+4加值。"},
[pwr_ao_ac2					]={n="灵敏反应"		,d="对抗借机攻击时，防御等级+2加值。"},
[pwr_shift_hard				]={n="优雅步伐"		,d="快步时，无视困难地形。"},
[pwr_mov_no_ao				]={n="游击战术"		,d="移动不引发借机攻击。"},
[pwr_web_mov				]={n=s_web_mov		,d=s_web_mov_d},
[pwr_swamper				]={n="沼泽居民"		,d="无视油腻区域。"},
[pwr_all_eyes				]={n="全域视野"		,d="不会被夹击。"},
[pwr_trance					]={n="恍惚"			,d="每回合只能进行一个动作。"},
[pwr_fey_blood				]={n="精灵免疫"		,d="免疫魔法睡眠或类似效果；对抗恐惧/魅惑等影响心灵类法术或效果时+2种族加值。"},
[pwr_cha_spl				]={n="龙脉魔法"		,d="魅力施法：能以魅力代替智力（自动取高），作为施法属性。"},
[pwr_con_spl				]={n="疤痕巫术"		,d="体质施法：能以体质代替智力（自动取高），作为施法属性。\n\n通过自残形体，刻烙疤痕的手段取悦自己的庇护主，借此获得魔力。"},
[pwr_ghoul_bite				]={n="食尸鬼之咬"		,d="近战攻击昏迷目标时，伤害检定+10加值。"},
[pwr_cha_hp					]={n="超凡生命"		,d="能以魅力代替体质（自动取高），应用于生命值计算。"},
[pwr_str_hp					]={n="人工生命"		,d="能以力量代替体质（自动取高），应用于生命值计算。"},
[pwr_avg_atk				]={n="保守攻击"		,d="保守的攻击方式，伤害稳定但无重击。"},
[pwr_liz_shock				]={n="电击"			,d="向目标发出一道闪电，造成电击伤害。"},
[pwr_pack_shock				]={n="群体放电"		,d="回合开始时，若与其他拥有此能力的生物邻接，则自动对近距范围内的所有生物进行电击。放电群体越大，伤害越高。"},
[pwr_tox_arrow				]={n="毒液喷射"		,d="向目标喷射毒液，造成毒素伤害，并且中毒。"},
[pwr_tox_fog				]={n="毒雾"			,d="生成一片毒气区域，使其中生物中毒。"},
[pwr_tox_erupt				]={n="毒液喷发"		,d="近距离爆发攻击，造成毒素伤害，并且中毒。"},
[pwr_spit_f					]={n="火焰吐息"		,d="近距离喷射攻击，造成火焰伤害。"},
[pwr_spit_a					]={n="强酸吐息"		,d="近距离喷射攻击，造成强酸伤害。"},
[pwr_heal_cw				]={n="维修"			,d="修理发条机械，使其恢复生命值。"},
[pwr_web_a0					]={n="蛛网"			,d="向目标投掷蛛网，使其无法移动。"},
[pwr_shd_bash				]={n="盾击"			,d="用盾牌猛击对手，使其昏迷。"},
[pwr_down_a1				]={n="震地"			,d="猛力震动地面，使所有邻接生物倒地。"},
[pwr_polym					]={n="变形术"		,d="将目标变成只会随机移动的小动物。"},
[pwr_turn					]={n="驱散"			,d="引导正能量驱逐不死生物，使其远离驱散者。\n\n圣武士驱散亡灵时等同于低3级的牧师。\n\n<c=fc_b>每天使用次数：3 + 魅力调整值。</c>"},
[pwr_fear					]={n="恐惧术"		,d="使范围内的所有敌人因恐惧而逃跑。"},-- 废
[pwr_mad					]={n="发狂"			,d="使目标陷入疯狂状态，行为不受控制，不分敌我的攻击最近目标。"},
[pwr_charm					]={n="魅惑"			,d="使敌人成为你的队友。"},
[pwr_eye_ctrl				]={n="支配凝视"		,d="使敌人完全受你控制。"},
[pwr_eye_stone				]={n="石化凝视"		,d="将目标变成石头。"},
[pwr_sum_spiders			]={n="召唤巨蜘蛛"	,d="召唤两只巨蜘蛛为你战斗。"},
-- skl acts
[pwr_intimidate				]={n="威吓"			,d="用你的威吓检定对抗目标的等级检定，成功则目标战栗至少1轮。\n\n战栗的角色在攻击和豁免上都会受到-2减值。"},
[pwr_feint					]={n="虚招"			,d="用你的唬骗检定对抗目标的察言观色检定，成功则目标在你对他的下次近战攻击中将失去防御上的敏捷加值。\n\n这次攻击必须在你下回合结束前做出。"},
[pwr_treat_wounds			]={n="急救"			,d="进行一次难度15的医疗检定，成功则目标恢复其最大生命值的1/4或更多。\n\n<c=to>同一生物在一场战斗中最多只能接受1次这种治疗。</c>"},
[pwr_treat_bleeding			]={n="止血"			,d="进行一次难度15的医疗检定，成功则目标停止出血。"},
[pwr_treat_poison			]={n="驱毒"			,d="进行一次难度15的医疗检定，成功则目标解除中毒。"},
[pwr_improved_feint			]={n="精通虚招"		,d="以移动动作而非标准动作使用虚招。"},
-- misc
[pwr_dfl_arw				]={n="拨挡飞箭"		,d="每轮一次，当正常状况下你会被某远程武器击中时，你可以挡开该武器而不受任何伤害。\n\n你必须至少空着一只手，非措手不及状态，且能察觉到此攻击。"},-- 一般专长	敏捷13，精通徒手击打。	拨挡远程武器不算是一个动作。特别大的远程武器和法术效果产生的远程攻击无法被拨挡。特殊：武僧可以在2级时选择本专长作为奖励专长，即使未满足先决条件。战士可以选择本专长作为其战士奖励专长。
[pwr_snt_arw				]={n="抓取飞箭"		,d="你可以在使用拨挡飞箭专长时抓住箭矢而非仅仅挡开它，投掷武器则立即被掷回原攻击者（不会触发借机攻击）。\n\n<c=o>此能力作为开关能力开启时，抓住投掷武器后也留着备用。</c>"},-- 敏捷15，拨挡飞箭，精通徒手攻击。	战士可以选择本专长作为战士的奖励专长。
[pwr_stunning_fist			]={n="震慑拳"		,d=pwr_stunning_fist_d},
[pwr_improved_stunning_fist	]={n="精通震慑拳"		,d="震慑拳强韧检定+2加值。\n\n特殊：可多次获得此专长，效果叠加。"},-- Epic 敏捷19，感知19，精通徒手攻击，震慑拳。
[pwr_ch_mle_dmg				]={n="毁灭重击"		,d=pwr_ch_mle_dmg_d},
[pwr_sa_1x					]={n="精通偷袭"		,d="你的偷袭更为致命，偷袭伤害+1d6点。\n\n特殊：可多次获得此专长，效果叠加。"},-- Epic 偷袭+8d6。Sneak attack +8d6.
[pwr_rage_fear				]={n="恐怖狂暴"		,d=pwr_rage_fear_d},
-- mnk 17 + 2
[pwr_unarmed_strike			]={n="徒手击打"	,d=pwr_unarmed_strike_d},
[pwr_flurry_of_blows		]={n="疾风连击"	,d=pwr_flurry_of_blows_d},
[pwr_ac_bonus				]={n="防御加值"	,d=pwr_ac_bonus_d},
[pwr_fast_movement_monk		]={n="快速移动"	,d="武僧拥有更快速的移动能力，其速度每3级+2增强加值（3级时+2，6级时+4...，30级时+20达到顶峰）。\n\n当穿着盔甲、持用盾牌、中载或重载时，将失去此额外速度。"},-- 史诗 21级+70英尺 24级+80英尺。。。
[pwr_still_mind				]={n="心如止水"	,d="武僧的冥思修行使其更能抵抗影响心灵的攻击，在对抗惑控系法术和效果时，豁免检定+2加值。"},
[pwr_ki_atk					]={n="斗气击"	,d=pwr_ki_atk_d},
[pwr_slow_fall				]={n="轻身坠"	,d="武僧能利用身旁的墙壁减缓坠落的速度。计算坠落高度时，每武僧等级减5尺。20级起可无伤坠落。"},
[pwr_purity_of_body			]={n="百病不侵"	,d="武僧能控制身体的免疫系统，免疫所有疾病，除了超自然或魔法造成的。"},--（如腐尸症、兽化症等）
[pwr_wholeness_of_body		]={n="混元体"	,d="武僧具有自我疗伤的能力。\n\n每日治疗点数：等级 x 2，可分多次使用。"},
[pwr_diamond_body			]={n="金刚体"	,d="武僧能控制身体的新陈代谢系统，免疫所有毒素。"},
[pwr_abundant_step			]={n="遁术"		,d="每日一次，武僧能如魔法般在空间内瞬移。"},-- ，如同施展次元门法术（施法者等级=武僧等级/2）
[pwr_diamond_soul			]={n="金刚魂"	,d="武僧获得法术抗力，数值为武僧等级+10。"},-- 要对此武僧使用魔法，施法者必须在施法者等级检定（1d20+施法者等级）中得到和武僧法术抗力相等或更高的结果。
[pwr_quivering_palm			]={n="渗透劲"	,d=pwr_quivering_palm_d},
[pwr_timeless_body			]={n="不老身躯"	,d="不再因年龄而遭受属性减值，也不会因魔法效果而变老。但之前的属性减值将保留，角色也仍会老死。"},-- 属性加值仍然可以获得，	武僧不再因年龄而遭受属性减值，也不会因魔法效果而变老。但之前的属性减值将保留，武僧也仍会老死。	A monk no longer takes penalties to her ability scores for aging and cannot be magically aged. Any such penalties that she has already taken, however, remain in place. The monk still dies of old age when her time is up.
[pwr_tongue_monk			]={n="天语通"	,d="武僧能与任何活物交谈。"},
[pwr_empty_body				]={n="空灵体"	,d=pwr_empty_body_d},
[pwr_perfect_self			]={n="超凡入圣"	,d="武僧的修练臻于完美，成为魔法生物。\n\n武僧获得伤害减免10/魔法。在考虑法术或魔法效果时，武僧被视为异界生物，而非凡俗种族。比如魅惑人类便对其无效，但武僧仍可被复活。"},-- 永远被视为异界生物（或外界生物）而不是原来的类人生物（或者武僧本来的生物类型）。	获得了10/魔法武器的伤害减免能力	当被非魔法武器或不具有类似的伤害减免能力（见伤害减免，《地下城主指南》291 页）的生物以天生武器攻击时，武僧可忽视攻击的前10点伤害（可以立即再生）。	，如同他还属于之前的生物类型一样，这点与其他异界生物不同
-- misc
[pwr_flurry_of_blows_r		]={n="远程疾风连击"	,d="类似正常近战疾风连击，使用特殊武僧武器手里剑从远处施展疾风连击。"},
[pwr_quivering_palm_kill	]={n="渗透劲：意念杀"	,d="武僧可尝试用意念杀死中了他的渗透劲的生物。成功则目标立即死亡，失败则此渗透劲失效。"},
[pwr_end_act				]={n="终止动作"		,d="你可以自由地终止某些进行中的动作或效果。"},
[pwr_end_spl				]={n="解消能力"		,d="某些法术或能力生效后，其施法者可以随时将之解消掉。"},

[pwr_test					]={n="测试"		,d="测试"},
}


s_dominated	="被支配"	s_dominated_d	="你被施法者控制，被迫按其想法行动。"-- 仅用于命令：xx描述前置
-- z_cond
conds_text={
[cond_rsv_1				]={n="保留状态1"		,d="暂无描述。"},
[cond_rsv_2				]={n="保留状态2"		,d="暂无描述。"},
[cond_rsv_3				]={n="保留状态3"		,d="暂无描述。"},
[cond_rsv_4				]={n="保留状态4"		,d="暂无描述。"},
[cond_rsv_5				]={n="保留状态5"		,d="暂无描述。"},
[cond_rsv_6				]={n="保留状态6"		,d="暂无描述。"},
[cond_rsv_7				]={n="保留状态7"		,d="暂无描述。"},
[cond_rsv_8				]={n="保留状态8"		,d="暂无描述。"},
[cond_rsv_9				]={n="保留状态9"		,d="暂无描述。"},

[cond_burn				]={n="燃烧"			,d="回合开始时，受到指定点数的火焰伤害。"},
[cond_corrode			]={n="腐蚀"			,d="回合开始时，受到指定点数的强酸伤害。"},
[cond_tox				]={n="中毒"			,d="回合开始时，受到指定点数的毒素伤害。"},
[cond_bleed				]={n="流血"			,d="回合开始时，受到指定点数的流血伤害。"},
[cond_hr				]={n="再生"			,d="回合开始时，恢复指定点数的生命值。"},

[cond_thp				]={n="暂时生命值"	,d="某些效果可以让角色获得暂时生命值。当角色获得暂时生命值时，这些生命值记在他的实际总生命值中。当这些暂时生命值消失时，角色的生命值将会降到他的实际总生命值。如果角色的生命值被降低到比他实际总生命值低，所有的暂时生命值都将失去，角色的总生命值不会降低。\n\n当暂时生命值失去后，它们不能象真实生命值那样被恢复，即使魔法也不行。\n\n增加体质值和实际生命值：增加角色的体质值，甚至是暂时性增加，都将会给他更多的生命值（有效生命值增加），但是这些生命值不是暂时生命值。它们不会像暂时生命值那样优先失去。"},
[cond_def				]={n="标准防御"		,d="专注于防御，直到下回合开始。"},
[cond_def_full			]={n="全力防御"		,d="全力以赴地进行防御，直到下回合开始。"},
[cond_fgt_def			]={n=s_fgt_def		,d=s_fgt_def_d},

[cond_dazzled			]={n="目眩"			,d="角色因为眼睛受到严重刺激而无法很好地视物。目眩的角色在攻击、搜索检定上受到-1减值。"},-- 和侦察
[cond_blinded			]={n="目盲"			,d="角色看不见东西。\n\n- 攻击有50%失手率（对手视为全隐蔽）。\n- 防御-2减值，并失去其上的敏捷加值。\n- 速度减半。\n- 搜索和大多数基于力量和敏捷的技能检定-4减值。\n- 所有依靠视力的检定和活动自动失败。"},-- 所有依靠视力的检定和活动（例如阅读和侦察检定）自动失败。一些长时间目盲的人物会习惯于此并克服某些缺点。
[cond_deafened			]={n="耳聋"			,d="角色听不见东西。\n\n- 先攻检定-4减值。\n- 聆听检定自动失败。\n- 施展具有语言成分的法术有20%几率失败。"},-- 一些长时间耳聋的人物会习惯于此并克服某些缺点。
[cond_fatigued			]={n="疲乏"			,d="角色的力量和敏捷-2减值，而且无法冲锋。疲乏的角色做出正常情况下会导致疲乏状态的行为时会变为力竭状态。"},-- 无法奔跑或冲锋	在8小时完全休息后，疲乏的人物就不再疲乏。
[cond_exhausted			]={n="力竭"			,d="角色的力量和敏捷-6减值，而且速度减半。"},-- 在1小时完全的休息之后，力竭的人物将变得疲乏。
[cond_sickened			]={n="恶心"			,d="角色遭受突如起来的痛苦及热病，攻击，伤害，豁免，技能和属性检定-2减值。"},
[cond_nauseated			]={n="反胃"			,d="强烈的胃部痛苦使得角色无法攻击、施法或其他任何需要集中注意力的动作，每轮只能做一个移动动作。"},-- 施法、专注以维持法术
[cond_staggered			]={n="恍惚"			,d="恍惚的角色每轮只能做一个移动或标准动作。"},-- 所受非致命伤害与其生命值相同则恍惚。如果当前生命值超过了所受非致命伤害，那么人物不再处于恍惚状态。非致命伤害值超过了生命值的则会陷入昏迷。	（不能二者都做，也不能做整轮动作）
[cond_dazed				]={n="晕眩"			,d="晕眩的角色无法行动，但防御上并无惩罚。"},-- 角色无法正常行动。晕眩状态通常持续1轮。
[cond_flat_footed		]={n="措手不及"		,d="战斗开始后未开始行动的角色尚不能正常应对当前形势，防御失去敏捷加值且无法借机攻击。"},
[cond_surprise			]={n="被突袭"		,d="被敌人突袭后，战斗开始的首个回合无法行动。"},

[cond_shaken			]={n="战栗"			,d="攻击、豁免、技能和属性检定-2减值。"},-- 战栗不如惊惧和恐慌那么激烈。
[cond_frightened		]={n="惊惧"			,d="惊惧的生物会尽力逃离恐惧源头。若无法逃离则可能战斗。\n\n此外，攻击、豁免、技能和属性检定-2减值。"},-- 惊惧的人物会用特殊能力逃离，包括使用法术；实际上如果只能用特殊能力逃离，那么人物就必须用那种方式逃离。惊惧类似于战栗，除了生物只要有可能就必须逃离。恐慌是一种更激烈的恐惧状态。
[cond_panicked			]={n="恐慌"			,d="恐慌的生物会扔掉手中物品，尽力逃离恐惧源头。它不能做任何其他动作。\n\n此外，豁免、技能和属性检定-2减值。"},-- ，同样也会避开任何其它遭遇的危险，但路线随机	恐慌的人物会用特殊能力逃跑，包括使用法术；实际上如果只能用特殊能力逃跑，那么人物就必须用那种方式逃跑。		如果被逼至绝路，它会陷入畏缩状态。	恐慌是比惊惧和战栗更激烈的恐惧状态。
[cond_cowering			]={n="畏缩"			,d="被吓住以至于无法行动，防御-2减值，并失去其上的敏捷加值。"},-- 角色被吓住以至于无法做动作。畏缩的角色在防御等级上有-2减值，并失去其上的敏捷加值（如果有的话）。

[cond_dmg_str			]={n="力量伤害"		,d="力量暂时降低。角色力量为0时，无助，倒地。"},-- 属性伤害	人物在一项或多项属性上暂时失去点数。除非注明要用其他方法治疗，否则失去的点数以每天1点的速率回升。力量为0意味着人物无力的躺在地上。敏捷为0意味着人物麻痹。体质为0意味着人物死亡。智力、感知、魅力为0意味着人物昏迷。属性伤害与属性值上的减值不同，后者会随着状态的消失而消失。
[cond_dmg_dex			]={n="敏捷伤害"		,d="敏捷暂时降低。角色敏捷为0时，麻痹。"},
[cond_dmg_con			]={n="体质伤害"		,d="体质暂时降低。角色体质为0时，死亡。"},
[cond_dmg_int			]={n="智力伤害"		,d="智力暂时降低。角色智力为0时，昏迷。"},
[cond_dmg_wis			]={n="感知伤害"		,d="感知暂时降低。角色感知为0时，昏迷。"},
[cond_dmg_cha			]={n="魅力伤害"		,d="魅力暂时降低。角色魅力为0时，昏迷。"},
[cond_drn_str			]={n="力量吸取"		,d="力量永久降低。角色力量为0时，无助，倒地。"},-- 属性吸取
[cond_drn_dex			]={n="敏捷吸取"		,d="敏捷永久降低。角色敏捷为0时，麻痹。"},
[cond_drn_con			]={n="体质吸取"		,d="体质永久降低。角色体质为0时，死亡。"},
[cond_drn_int			]={n="智力吸取"		,d="智力永久降低。角色智力为0时，昏迷。"},
[cond_drn_wis			]={n="感知吸取"		,d="感知永久降低。角色感知为0时，昏迷。"},
[cond_drn_cha			]={n="魅力吸取"		,d="魅力永久降低。角色魅力为0时，昏迷。"},
[cond_dmg_phy			]={n="体能属性伤害"	,d="体能属性暂时降低。"},
[cond_dmg_mtl			]={n="心灵属性伤害"	,d="心灵属性暂时降低。"},
[cond_dmg_all			]={n="所有属性伤害"	,d="所有属性暂时降低。"},
[cond_drn_phy			]={n="体能属性吸取"	,d="体能属性永久降低。"},
[cond_drn_mtl			]={n="心灵属性吸取"	,d="心灵属性永久降低。"},
[cond_drn_all			]={n="所有属性吸取"	,d="所有属性永久降低。"},
[cond_energy_drained	]={n="能量吸取		",d="角色获得一个或多个负向等级。若负向等级数大于等于角色等级，角色死亡。每个负向等级给予下列惩罚：攻击、豁免、技能和属性检定-1减值；生命值-5；有效等级-1（用来决定法术或特殊能力的强度、持续时间、DC和其它细节）；施法者从可施展的最高法术等级上失去一个法术或一个法术栏位。"},--，这些负向等级有可能会使他等级永久下降

[cond_hf_mov			]={n="迟缓"			,d="移动速度减半，无法冲锋。"},
[cond_no_mov			]={n="禁足"			,d="无法移动。"},
[cond_prone				]={n="俯卧"			,d="倒地时移动速度减半，近战攻击和防御-4，远程防御+4，不能使用弩以外的远程武器。起立需耗费一个移动动作，并且会引发借机攻击。"},
[cond_entangled			]={n="纠缠"			,d="人物被缠绕住。被纠缠会使移动受到限制，但除非被绑在固定的物体上或被相反的力道拉住，否则移动不会被完全阻止。被纠缠的人物只能以正常速度的一半移动，无法奔跑或冲锋，所有攻击掷骰上有-2减值，并在敏捷上有-4减值。纠缠中的角色想施法则必须通过专注检定（DC 15+法术等级），否则失去法术。"},

[cond_grapper			]={n="擒抱"			,d="专注于压制被擒抱者，无法做其他动作，无威胁区域，失去防御上的敏捷加值。"},-- 与一个或更多的进攻者从事于短兵相接的角斗。一个擒抱中的人物仅能做一些有限的动作。他没有任何威胁区域，并对于没有和他进行擒抱的对手来说，他失去了在AC上的敏捷加值。
[cond_grap				]={n="被擒抱"		,d="被压制而无法行动。回合开始时，会自动尝试挣脱。"},
[cond_pinned			]={n="压制"			,d="在擒抱中被固定住无法行动（但不是无助）。"},
[cond_stunned			]={n="震慑"			,d="被震慑住的生物手中物品会掉落，无法行动，防御-2减值，并失去其上的敏捷加值。"},
[cond_helpless			]={n="无助"			,d="无法动弹，无法行动。"},-- 被麻痹、定身、束缚、睡眠中、昏迷、或其它完全暴露于敌手掌控之中的状态。无助的目标的敏捷当作0（调整值为-5）。对无助的目标进行近身攻击有+4奖励（相当于攻击俯卧中的对手）。远程攻击没有特殊奖励。游荡者可以偷袭无助的目标。敌人可以用近战武器对无助的目标做一次致命一击（coup de grace），这是一个整轮动作。如果敌人和目标紧邻，那么也可以用弓和弩做致命一击。攻击者自动命中，并认为是重击（游荡者在做出致命一击时还能获得偷袭伤害值）。如果目标从这次攻击中幸存，他必须进行一次成功的强韧豁免检定（DC 10+伤害值）否则死亡。做致命一击会引发借机攻击。免疫重击的生物不会受到重击伤害，也不需要进行成功的强韧检定来避免被致命一击杀死。
[cond_unconscious		]={n="昏迷"			,d="陷入昏迷，无法行动。"},-- 生物被击倒并陷入无助状态。若人物当前生命值在-1到-9之间，或非致命伤害超过其当前生命值，则该人物陷入昏迷。
[cond_paralyzed			]={n="麻痹"			,d="僵在原地，无法行动。"},-- 被麻痹的人物被钉在原地不能移动或做其他行动。被麻痹的人物其有效敏捷值和有效力量值为0，而且处于无助状态，但他可以进行纯粹的心理活动。有翅膀的生物在飞的时候被麻痹，他们将无法舞动翅膀并掉下来。游泳的人被麻痹后无法游泳并有可能遭受淹溺。其它生物可以穿过被麻痹的人物占据的区域，无论是盟友还是敌人。但是被麻痹的人物所占据的每个方格都记作两个方格。
[cond_stone				]={n="石化"			,d="变为石头并视作昏迷。"},-- 被石化的人物变为石头并视作昏迷。如果被石化的人物被打碎或打破，但是在被解除石化时那些破损的部份接在了身体上，那么他将不受伤害。如果石化的身体被解除石化时是不完整的，肉体将同样的不完整，并会有相应永久性生命值丧失和（或）人物变的衰弱。
[cond_sleep				]={n="睡眠"			,d=pwr_sleep_d},
[cond_turn				]={n="被驱散"		,d="受到驱散亡灵效果的影响，自动逃离驱散者。"},-- 受到驱散亡灵效果的影响。被驱散的不死生物会用其最好最快的方法逃离10轮（1分钟）。如果无法逃离，则处于畏缩状态。

[cond_disabled			]={n="瘫痪"			,d="人物的生命值为0，或拥有负值的生命值但已稳定并神智清醒，这些情况为瘫痪状态。瘫痪人物每轮只能做一个移动动作或一个标准动作（不能两者都做，也不能进行全回合动作）。他只能以正常速度的一半移动。做移动动作不会招致更多的伤害，但是进行任何标准动作（或其他任何DM认为是费力的事，包括一些即时动作，例如施展瞬发法术等）会在动作完成后受到1点伤害。除非这个动作增加了瘫痪人物的生命值，否则他的生命值将降为负数并因而进入濒死状态。有着负数生命值的瘫痪人物如果能受到帮助，他的生命值会自然回升。否则，每天他有10%的几率开始自然回复生命值（从那天开始），如果没能自然回复，他将继续失去1点生命值。如果没有援助的瘫痪人物生命值开始自然回升，他就不再有继续降低生命值的危险（即使当前生命值仍是负数）。"},
[cond_dying				]={n="濒死"			,d="濒死的人物处于昏迷状态并接近死亡。其当前的生命值为-1至-9。濒死的人物无法做动作并且昏迷。在每轮结束（从生命值降到0以下的那一轮开始），人物掷一个百分骰决定是否伤势稳定。他有10%的几率进入稳定状态。如果没能稳定，生命值将降低1点。如果生命值降到-10，他就死亡。"},
[cond_stable			]={n="稳定"			,d="曾处于濒死状态但目前已经不再继续损失生命值，同时生命值依然为负数的人物是稳定状态。这类人物不再处于濒死状态，但仍旧昏迷。如果其他人利用急救措施（例如医疗技能或魔法治疗）使濒死人物稳定下来，他就不会继续丢失生命值。他每小时有10%的机会清醒并进入瘫痪状态（尽管他的生命值可能是负的）。如果人物并没有受到别人的帮助而是靠自己稳定下来的话，他仍然有丢失生命值的危险。他每小时有10%的机会清醒并进入瘫痪状态，否则就将失去1点生命值。"},
[cond_dead				]={n="死亡"			,d="人物的生命值降到-10，体质降到0，或被法术及效果彻底杀死。人物的灵魂离开身体。死亡人物无法得益于正常或魔法的治疗，但能通过魔法复活。除非用魔法保护，否则尸体会正常腐烂，但是使死亡人物复活的法术会使人物完全康复或回到死亡时的状态（取决于使用的魔法或设备）。无论使用什么手段，被复活的人物都不用担心诸如尸僵、腐烂和其它影响尸体的效果。"},
[cond_fascinated		]={n="迷魂"			,d="处在迷魂状态的人物被超自然能力或法术弄得神志恍惚。人物会静静的站着或坐着，除了专心于产生迷魂的效果外什么都不做，直到效果结束。在基于感应的技能检定上（例如聆听和侦察检定）有-4减值。任何潜在的威胁，如敌对生物的接近，将允许被迷魂的生物进行一次新的豁免检定来对抗迷魂效果。任何明显的威胁,例如其他人拔出武器、施展法术或以远程武器瞄准被迷魂的生物，都会自动地打破效果。被迷魂生物的同伴可以通过一个标准动作摇晃他来使他摆脱迷魂状态。"},
[cond_confused			]={n="困惑"			,d="困惑的人物的行动在他的回合开始时通过百分率决定：01-10，用肉搏或远程武器攻击施法者（如果无法攻击就向施法者靠近）；11-20，正常行动；21-50，除了毫无条理的说胡话外什么都不做；51-70，以最快的速度逃离施法者；71-100，攻击最近的生物（在这种情况下，魔宠视作受术者自身的一部分）。无法做上述规定动作的困惑生物只能毫无条理的说胡话。攻击困惑生物不会有任何特殊奖励。只要在被攻击的困惑生物其回合开始时还处于困惑中，他就会自动在接下来的回合内向攻击他的生物发起攻击。除了已经准备攻击的生物（要么是困惑生物最近一个动作的目标，要么是刚攻击过困惑生物的生物），困惑的生物将不会对其他生物进行借机攻击。"},
[cond_invisible			]={n="隐形"			,d="无法被视力探察。隐形生物攻击非隐形生物时在攻击掷骰上有+2加值，并忽视他的敏捷加值对AC的奖励。（见特殊能力中隐形的说明。）"},
[cond_incorporeal		]={n="虚体"			,d="没有肉体。虚体生物免疫一切非魔法类攻击。只有其它虚体生物的攻击、+1或更好的魔法武器、法术、类法术能力或超自然能力可以伤害到它。"},
[cond_checked			]={n="受阻"			,d="被一股力量阻止前进，例如风。在地上受阻仅仅是裹足不前。受阻的飞行生物会退后一段距离，这段距离在对应效果的描述中给出。"},
[cond_knocked_down		]={n="吹倒"			,d="由于体型关系，一个生物可以被一阵强风吹倒。在地面上的生物会被吹倒趴下。飞行生物会被吹后1d6x10尺。"},
[cond_blown_away		]={n="吹动"			,d="由于体型关系，一个生物可以被一阵强风吹动。在地面上处于被吹动状态的生物会被吹倒并翻滚1d4x10尺，每10尺受到1d4点非致命伤害。飞行中处于被吹动状态的生物会被吹后2d6x10尺并受到2d6点非致命伤害。"},

[cond_red_ache			]={n="红肿症"		,d="患者肤色转红、肿胀、发热。发病时造成1d6力量伤害。"},-- 伤口	15	1d3天	感染方式 DC 潜伏期
[cond_devil_chills		]={n="寒魔症"		,d="经由巴霸魔和深狱炼魔传染。发病时造成1d4力量伤害。必须经过三次成功的豁免检定才能恢复健康，而不是通常的两次。"},-- 伤口	14	1d4天
[cond_blinding_sickness	]={n="失明症"		,d="通过被污染的水传播。发病时造成1d4力量伤害，当此伤害为2或更高时，患者必须做一次额外的强韧检定，失败则永久目盲。"},-- 摄入	16	1d3天
[cond_shakes			]={n="颤栗症"		,d="患者会不由自主的抽搐发颤和痉挛。发病时造成1d8敏捷伤害。"},-- 接触	13	1天
[cond_filth_fever		]={n="腐热症"		,d="经由凶暴鼠与食腐兽传染。当伤口处于肮脏的环境中时也会感染。发病时造成1d3敏捷和1d3体质伤害。"},-- 伤口	12	1d3天
[cond_demon_fever		]={n="热魔症"		,d="经由老鬼婆传染。发病时造成1d6体质伤害，患者必须成功通过一次额外的强韧豁免，否则受到1点的永久属性吸取而非原来的属性伤害。"},-- 伤口	18	1天
[cond_mummy_rot			]={n="腐尸症"		,d="经由木乃伊传染。发病时造成1d6体质伤害。成功的豁免检定也不会使感染者恢复健康（但仍能避免伤害），只有魔法医疗才能治愈。"},-- 接触	20	1天
[cond_slimy_doom		]={n="胶质症"		,d="患者会由内到外逐渐变成有感染性的粘稠物。发病时造成1d4体质伤害，患者必须成功通过一次额外的强韧豁免，否则受到1点的永久属性吸取而非原来的属性伤害。"},-- 接触	14	1天
[cond_mindfire			]={n="脑热症"		,d="患者感到脑袋焦炽般的烧热。导致昏迷。发病时造成1d4智力伤害。"},-- 吸入	12	1天
[cond_cackle_fever		]={n="失心疯"		,d="症状包括高烧，意识模糊，以及经常发出阵阵狂笑。也称为“狂喊症”。发病时造成1d6感知伤害。"},-- 吸入	16	1天

[cond_command_fight		]={n="命令：战"		,d="在你的回合中，你将尽可能地进行战斗。"},
[cond_command_approach	]={n="命令：来"		,d="在你的回合中，你将尽可能迅速直接地走向此效果的施法者，其他什么也不做。"},
[cond_command_flee		]={n="命令：逃"		,d="在你的回合中，你将尽可能迅速直接地远离此效果的施法者，其他什么也不做。"},
[cond_command_halt		]={n="命令：停"		,d="在你的回合中，你将原地不动1轮，不能做任何动作，但并非无助。"},
[cond_command_fall		]={n="命令：倒"		,d="在你的回合中，你将躺倒在地1轮。俯卧中你能正常行动，但要受到相应的惩罚。"},
[cond_command_drop		]={n="命令：掉"		,d="在你的回合中，你将扔掉手中所有物品，直到你的下一回合之前都不会捡起来。"},

[cond_warm_shield		]={n="温暖护盾"		,d=pwr_fire_shield_f},
[cond_chill_shield		]={n="寒冷护盾"		,d=pwr_fire_shield_c},
[cond_prayer_favor		]={n="神之恩宠"		,d="神之恩宠笼罩着你，攻击、武器伤害、豁免和技能检定+1幸运加值。"},--祈祷术：
[cond_prayer_disfavor	]={n="神之厌恶"		,d="神之厌恶笼罩着你，攻击、武器伤害、豁免和技能检定-1减值。"},
[cond_curse_penalty		]={n="诅咒：惩罚"		,d="攻击、豁免、属性和技能检定上受到-4惩罚。"},
[cond_curse_disorder	]={n="诅咒：错乱"		,d="50%几率正常行动；否则无法行动。"},
[cond_comatose			]={n="沉睡"			,d="角色陷入僵硬的病态沉眠，无法被叫醒。这并非睡眠效果，因此精灵不能免疫它。"},
[cond_ethereal			]={n="灵体"			,d=pwr_ethereal_jaunt_d},
[cond_death_atk_1		]={n=s_death_atk_1	,d=s_death_atk_d},
[cond_death_atk_2		]={n=s_death_atk_2	,d=s_death_atk_d},
}